/* Atlas : montagnes et volcans, îles, déserts, continents — généré par tools/atlas-build-themes.mjs. Chiffres : Wikidata (CC0). Textes : Vikidia / Wikipédia (CC BY-SA 4.0), lien par fiche (src). */
window.MQ_ATLAS_T=window.MQ_ATLAS_T||{};Object.assign(window.MQ_ATLAS_T,{
"montagnes":{"agung":{"n":"Agung","t":"volcan","alt":3031,"bref":["L'Agung ou mont Agung, en balinais : en indonésien Gunung Agung, littéralement en français « montagne suprême » ou « montagne sacrée », est un volcan d'Indonésie situé sur l'île de Bali dont il constitue le point culminant avec 2 995, 3 031 ou 3 142 mètres d'altitude. Stratovolcan conique aux pentes régulières et escarpées, il est couronné par un cratère. Pour les Balinais hindouistes, il est considéré comme le fils du Semeru de Java qui est lui-même le fils du mont Meru de l'hindouisme."],"src":"https://fr.wikipedia.org/wiki/Agung","sw":"w","q":"Q158470","pays":["ID"],"c":["asie"]},"aiguille-du-midi":{"n":"Aiguille du Midi","t":"sommet","alt":3842,"massif":"massif du Mont-Blanc","bref":["Le téléphérique de l'aiguille du Midi qui relie Chamonix à l'aiguille du Midi avec une escale au Plan de l'Aiguille."],"src":"https://fr.vikidia.org/wiki/Aiguille_du_Midi","sw":"v","q":"Q404728","pays":["FR"],"c":["europe"]},"alpes":{"n":"Alpes","t":"massif","alt":4811,"bref":["Les Alpes sont une chaîne de montagnes du Sud de l'Europe. Elles traversent l'Italie, la France, Monaco, la Suisse, le Liechtenstein, l'Autriche, l'Allemagne et la Slovénie. Le plus haut sommet est le Mont Blanc avec 4 809 mètres d'altitude. Les Alpes déroulent leurs crêtes sur près de 1 250 km depuis Vado Ligure (Italie) jusqu'à Höflein an der Donau (Autriche), sur les bords du Danube. La largeur maximale de la chaîne est de 246 km, formant ainsi une épaisse barrière naturelle, toutefois facilement pénétrable et franchissable grâce aux nombreuses vallées fluviales et aux nombreux cols. L'homme y a aussi aménagé de nombreux tunnels (ferroviaires comme le tunnel du Saint-Gothard ou routiers comme le tunnel du Mont-Blanc). Il y a beaucoup de glaciers dans les Alpes."],"src":"https://fr.vikidia.org/wiki/Alpes","sw":"v","q":"Q1286","pays":["DE","AT","CH","FR","IT","SI","MC","LI","HU"],"c":["europe"]},"alpes-dinariques":{"n":"Alpes dinariques","t":"massif","alt":2694,"bref":["Les Alpes dinariques ou Dinarides sont un massif montagneux des Balkans occidentaux qui doivent leur nom au mont Dinara. Elles s'élèvent entre le bassin du moyen Danube au nord-est et la mer Adriatique au sud-ouest, en plusieurs chaînes montagneuses orientées principalement selon un axe nord-ouest - sud-est, de la Slovénie au nord de l'Albanie où culmine leur plus haut sommet, à 2 692 mètres d'altitude : le Maja e Jezercës. Elles couvrent au total six pays reconnus internationalement, auxquels peut s'ajouter le Kosovo. La plus grande ville est Sarajevo, capitale de la Bosnie-Herzégovine. Trois climats distincts influencent le massif : méditerranéen à l'ouest, montagnard au centre, où le relief est le plus élevé, et continental à l'est."],"src":"https://fr.wikipedia.org/wiki/Alpes_dinariques","sw":"w","q":"Q189915","pays":["RS","HR","BA","SI","ME","AL","XK"],"c":["europe"]},"alpes-du-sud":{"n":"Alpes du Sud","t":"massif","alt":3754,"bref":["Les Alpes du Sud (en anglais : Southern Alps, en maori de Nouvelle-Zélande : Kā Tiritiri o te Moana, littéralement « les crêtes de la mer », car leurs sommets enneigés font penser à des vagues sur la mer), aussi appelées Alpes néo-zélandaises, sont une chaîne de montagnes située sur la partie occidentale de l'île du Sud en Nouvelle-Zélande. Elles forment une limite naturelle dans le sens de la longueur de l'île du Sud. L'Aoraki/Mont Cook (Aoraki est le nom en langue māori jumelé avec le nom du navigateur britannique) est le point culminant à 3 724 m d'altitude. Seize autres sommets de la chaîne s'élèvent à plus de 3 000 m d'altitude.","Les parcs nationaux occupent une part importante du massif, les principaux étant : le parc national de Westland Tai Poutini, le parc national du mont Aspiring et le parc national Aoraki/Mount Cook. Les Alpes du Sud comptent aussi quelque 360 glaciers. Le glacier Tasman, le plus vaste d'entre eux, s'étend sur 29 kilomètres."],"src":"https://fr.wikipedia.org/wiki/Alpes_du_Sud_(Nouvelle-Z%C3%A9lande)","sw":"w","q":"Q206650","pays":["NZ"],"c":["oceanie"]},"alpes-maritimes":{"n":"Alpes maritimes","t":"sommet","alt":3297,"massif":"Alpes maritimes et Préalpes de Nice","bref":["Les Alpes-Maritimes (en occitan provençal : Aups Maritims ; en italien : Alpi Marittime) sont un département français de la région Provence-Alpes-Côte d'Azur créé en 1860 suite à l'annexion du comté de Nice (royaume de Sardaigne) à la France. Les villes de Menton et de Roquebrune (qui appartenaient alors à la principauté de Monaco) ainsi que l'arrondissement de Grasse, détaché du département du Var, rejoignent le département nouvellement formé.","Le département comprend 52 cantons et 163 communes. Ses principales villes sont, outre la préfecture Nice, Antibes, Cannes, Grasse et Menton."],"src":"https://fr.vikidia.org/wiki/Alpes-Maritimes","sw":"v","q":"Q2451856","pays":["FR","IT"],"c":["europe"]},"alpes-occidentales":{"n":"Alpes occidentales","t":"massif","alt":4810,"massif":"Alpes","bref":["Les Alpes occidentales sont une partie des Alpes comprenant notamment les Alpes maritimes, les Alpes ligures, les Alpes cottiennes, les Alpes grées et diverses Préalpes. Leur sommet le plus élevé est le mont Blanc, à 4 807 m."],"src":"https://fr.wikipedia.org/wiki/Alpes_occidentales","sw":"w","q":"Q74259","pays":["FR","IT","CH","MC"],"c":["europe"]},"alpes-scandinaves":{"n":"Alpes scandinaves","t":"massif","alt":2469,"bref":["Les Alpes scandinaves ou Scandes sont une chaîne de montagnes s'étendant tout le long de la côte ouest de la péninsule Scandinave. Elles couvrent l'essentiel de la Norvège, le Nord-Ouest et l'Ouest de la Suède ainsi qu'une toute petite partie de l'Extrême-Nord de la Finlande. Il s'agit d'une des plus importantes chaînes de montagnes d'Europe, s'étirant du sud-ouest au nord-est sur 1 700 km, avec une largeur maximale de 300 km. La chaîne possède deux zones de haute altitude, une dans le Sud de la Norvège, autour du Jotunheimen où se trouve le Galdhøpiggen (2 469 m), point culminant de la chaîne et du pays concerné, et une autre dans le Nord de la Suède, avec le Kebnekaise (2 102 m), point culminant du pays — le point culminant de Finlande se trouve aussi dans la chaîne : il s'agit du Halti (1 328 m)."],"src":"https://fr.wikipedia.org/wiki/Alpes_scandinaves","sw":"w","q":"Q186547","pays":["SE","FI","NO"],"c":["europe"]},"altai":{"n":"Altaï","t":"massif","alt":4506,"bref":["L'Altaï (ou les montagnes dorées) est une chaîne de montagnes située en Asie centrale et qui s'étend sur quatre États : le Kazakhstan, la Russie, la Chine et la Mongolie. Ce système montagneux a une longueur d'environ 2 000 km. Cette mesure inclut aussi l'Altaï mongol et l'Altaï de Gobi."],"src":"https://fr.vikidia.org/wiki/Alta%C3%AF","sw":"v","q":"Q5955","pays":["KZ","RU","MN","CN"],"c":["asie","europe"]},"annapurna":{"n":"Annapurna","t":"massif","alt":8091,"massif":"Himalaya","bref":["L'Annapurna est un massif de montagnes de l'Himalaya au Népal, comprenant six principaux sommets dont le plus haut, l'Annapurna I, culmine à 8 091 mètres, ce qui en fait le dixième plus haut sommet du monde."],"src":"https://fr.wikipedia.org/wiki/Annapurna","sw":"w","q":"Q159621","pays":["NP"],"c":["asie"]},"anti-liban":{"n":"Anti-Liban","t":"massif","alt":2814,"bref":["L'Anti-Liban, est une chaîne de montagnes située principalement au Liban et en Syrie, autour de la frontière entre les deux pays, ainsi qu'au plateau du Golan contrôlé par Israël. C'est une région peu habitée dominée par un climat aride sur une large partie de sa surface, mais qui abrite des températures plus froides à ses sommets."],"src":"https://fr.vikidia.org/wiki/Anti-Liban","sw":"v","q":"Q243276","pays":["LB","SY","IL"],"c":["asie"]},"aoraki-mont-cook":{"n":"Aoraki/Mont Cook","t":"sommet","alt":3724,"massif":"Alpes du Sud","bref":["L'Aoraki/Mont Cook est le plus haut sommet de la Nouvelle-Zélande, Aoraki signifiant en maori « perceur de nuages ». Il se situe dans les Alpes du Sud, plus précisément dans la région de Canterbury, et culmine à 3 724 mètres d'altitude. Il est bordé par les glaciers Hooker à l'ouest et Tasman à l'est, ce dernier étant le plus long de Nouvelle-Zélande. Les rivages de la mer de Tasman ne sont qu'à 34 km."],"src":"https://fr.vikidia.org/wiki/Aoraki%2FMont_Cook","sw":"v","q":"Q5059","pays":["NZ"],"c":["oceanie"]},"apennins":{"n":"Apennins","t":"massif","alt":2912,"bref":["Les Apennins (ou l'Apennin, au singulier) sont une chaîne de montagnes située en Italie et traversant celle-ci dans toute sa longueur. Le sommet culminant de cette chaîne est le Corno Grande (2 914 m) dans le parc Gran Sasso. Par temps clair, il y est possible de voir deux mers à la fois."],"src":"https://fr.vikidia.org/wiki/Apennins","sw":"v","q":"Q1285","pays":["IT","SM"],"c":["europe"]},"appalaches":{"n":"Appalaches","t":"massif","alt":2037,"bref":["Les Appalaches sont une chaîne de montagnes de l'Est des États-Unis et du Canada. Elles s'étendent de Terre-Neuve jusqu'en Alabama. Les Appalaches culminent en Caroline du Nord, au mont Mitchell, avec 2 037 m d'altitude."],"src":"https://fr.vikidia.org/wiki/Appalaches","sw":"v","q":"Q93332","pays":["US","CA","FR"],"c":["amerique-nord","europe"]},"aragats":{"n":"Aragats","t":"sommet","alt":4090,"massif":"haut plateau arménien","bref":["L'Aragats, en arménien : en russe : aussi appelé mont Aragats, Alagey, Aragatz ou encore Aragey, est un volcan éteint d'Arménie. Avec 4 095 mètres d'altitude, il constitue le point culminant de l'Arménie et du Petit Caucase et domine le haut-plateau arménien qui s'étend à ses pieds."],"src":"https://fr.wikipedia.org/wiki/Aragats","sw":"w","q":"Q203568","pays":["AM"],"c":["asie"]},"askja":{"n":"Askja","t":"volcan","alt":1516,"massif":"Dyngjufjöll","bref":["L'Askja est un emboîtement de caldeiras en Islande, éponyme d'un système volcanique appartenant au graben médian et composé de ces caldeiras, la plus interne étant occupée par un lac, l'Öskjuvatn, du massif volcanique qui les entoure, les Dyngjufjöll, reste d'un ancien volcan précédant la caldeira, ainsi que de volcans boucliers, de cratères et de fissures volcaniques s'étirant dans une direction nord-sud sur une centaine de kilomètres de longueur. La dernière éruption de l'Askja remonte à la fin 1961 mais sa plus puissante des temps historiques, responsable de la formation de la caldeira remplie par l'Öskjuvatn, s'est déroulée en 1875."],"src":"https://fr.wikipedia.org/wiki/Askja","sw":"w","q":"Q211665","pays":["IS"],"c":["europe"]},"atlas":{"n":"Atlas","t":"massif","alt":4165,"bref":["L'Atlas est une chaîne de montagnes située en Afrique du Nord et s'étendant sur trois pays : le Maroc, l'Algérie et la Tunisie.","Il atteint 4 167 mètres d'altitude au djebel Toubkal (le plus haut point des montagnes de l'Atlas)."],"src":"https://fr.vikidia.org/wiki/Atlas_(cha%C3%AEne_de_montagnes)","sw":"v","q":"Q130135","pays":["MA","DZ","TN"],"c":["afrique"]},"barre-des-ecrins":{"n":"Barre des Écrins","t":"sommet","alt":4102,"massif":"chaine Écrins-Grande Ruine-Agneaux","bref":["La barre des Écrins est un sommet des Alpes françaises culminant à 4 101 mètres d'altitude. Point culminant du massif des Écrins, du département des Hautes-Alpes et plus généralement du Dauphiné, il est le plus méridional des « 4 000 alpins ». Avant l'annexion de la Savoie en 1860, il était le point culminant de la France."],"src":"https://fr.wikipedia.org/wiki/Barre_des_%C3%89crins","sw":"w","q":"Q30480","pays":["FR"],"c":["europe"]},"bazarduzu":{"n":"Bazardüzü","t":"sommet","alt":4466,"massif":"Grand Caucase","bref":["Le mont Bazardüzü est une montagne du Grand Caucase située sur la frontière entre la Russie (Daghestan) et l'Azerbaïdjan. Il culmine à 4 466 m d'altitude et constitue le plus haut sommet d'Azerbaïdjan. Le point le plus méridional de la Russie est également situé à proximité."],"src":"https://fr.wikipedia.org/wiki/Bazard%C3%BCz%C3%BC","sw":"w","q":"Q725591","pays":["AZ","RU"],"c":["asie","europe"]},"beerenberg":{"n":"Beerenberg","t":"volcan","alt":2277,"massif":"dorsale médio-atlantique","bref":["Le Beerenberg (nom néerlandais pour « Montagne des ours ») est un volcan de l'île Jan Mayen située entre la mer du Groenland (océan Arctique) au nord-ouest et la mer de Norvège (océan Atlantique) au sud-est."],"src":"https://fr.wikipedia.org/wiki/Beerenberg","sw":"w","q":"Q814113","pays":["NO"],"c":["europe"]},"ben-nevis":{"n":"Ben Nevis","t":"sommet","alt":1345,"massif":"Monts Grampians","bref":["Le Ben Nevis est le point culminant des îles Britanniques avec 1 345 mètres d'altitude. Situé près de Fort William en Écosse, il fait partie des monts Grampians dans les Highlands. Gravi pour la première fois en 1771, il est coiffé par les ruines d'un observatoire construit et utilisé à la fin du XIXe siècle pour effectuer des observations météorologiques qui sont restées très importantes dans la compréhension du climat en Grande-Bretagne. Celui qui sévit au sommet, extrêmement rude, lui vaut d'ailleurs son nom, Nibheis signifiant « malveillant » en gaélique écossais."],"src":"https://fr.wikipedia.org/wiki/Ben_Nevis","sw":"w","q":"Q104674","pays":["GB"],"c":["europe"]},"broad-peak":{"n":"Broad Peak","t":"sommet","alt":8051,"massif":"Gasherbrum","bref":["Le Broad Peak est un sommet culminant à 8 051 mètres d'altitude, à la frontière entre la Chine et le Pakistan, dans le Karakoram. Il constitue le douzième plus haut sommet du monde. Sa première ascension a été réussie le 9 juin 1957 par les Autrichiens Hermann Buhl, Kurt Diemberger, Marcus Schmuck et Fritz Wintersteller. Leur itinéraire, par l'éperon ouest puis le final par l'arête nord, est devenu la voie normale empruntée par la quasi-totalité des alpinistes, les autres voies étant rarement répétées."],"src":"https://fr.wikipedia.org/wiki/Broad_Peak","sw":"w","q":"Q180996","pays":["PK","CN"],"c":["asie"]},"caldeira-de-yellowstone":{"n":"Caldeira de Yellowstone","t":"volcan","alt":2805,"massif":"montagnes Rocheuses","bref":["La caldeira de Yellowstone est une dépression vaste (85 × 45 km) mais très peu profonde, située dans le parc national de Yellowstone (Wyoming, États-Unis). Elle a été découverte au cours des années 1960 et 1970, lors d'investigations géologiques dirigées par Robert Christiansen, de l'Institut d'études géologiques des États-Unis.","Cette dépression est une caldeira, le résultat de l'effondrement du toit d'une chambre magmatique quand une éruption l'a vidée (pour les caldeiras de grande taille comme celle-ci, il s'agit en général d'une éruption explosive, qui détruit aussi l'édifice volcanique qui surmontait la chambre). La caldeira de Yellowstone résulte de la dernière superéruption, il y a environ 640 000 ans, du volcan de Yellowstone, qualifié de supervolcan. Ce volcan est considéré comme endormi."],"src":"https://fr.wikipedia.org/wiki/Caldeira_de_Yellowstone","sw":"w","q":"Q650836","pays":["US"],"c":["amerique-nord"]},"carpates":{"n":"Carpates","t":"massif","alt":2655,"bref":["Les Carpates sont une importante chaîne de montagnes de l'Europe centrale. En fait, elles prolongent les Alpes, et forment un grand arc qui débute aux portes de Bratislava, en Slovaquie. Dans ce pays se trouve le sommet de la chaîne (le Gerlachovsky štít). La chaîne de montagnes déborde sur le territoire de la République tchèque, traverse ensuite le Sud de la Pologne, puis l'Ukraine et la Roumanie, avant de se terminer en Serbie. Les Carpates ont une surface de 209 000 km2 dont 53 % se situent en Roumanie et 17 % en Slovaquie.","Le mot « Carpates » provient du mot albanais « karpë » qui veut dire « rocher »."],"src":"https://fr.vikidia.org/wiki/Carpates","sw":"v","q":"Q1288","pays":["RS","UA","AT","CZ","SK","PL","HU","RO"],"c":["europe"]},"caucase":{"n":"Caucase","t":"massif","alt":5642,"bref":["La géographie du Caucase peut être schématisée par une chaîne de montagnes rectiligne, qui ne prend une certaine hauteur qu'à environ 300 km du détroit de Kertch et culmine, dans sa partie centrale, avec de vastes massifs volcaniques englacés."],"src":"https://fr.wikipedia.org/wiki/G%C3%A9ographie_du_Caucase","sw":"w","q":"Q5477","pays":["RU"],"c":["asie","europe"]},"cervin":{"n":"Cervin","t":"sommet","alt":4478,"massif":"Alpes pennines","bref":["Le mont Cervin, appelé Matterhorn en allemand, Matterhòre en greschòneytitsch (un dialecte de l'alémanique) et Monte Cervino en italien, est un sommet alpin de 4 478 mètres d'altitude, situé dans les Alpes pennines à la frontière italo-suisse, entre le canton du Valais (en Suisse), et la vallée d'Aoste (en Italie).","L'image du mont Cervin est emblématique de la Suisse, surtout pour son aspect pyramidal et la vue que l'on en a depuis le Gornergrat, un sommet voisin du village de Zermatt et accessible par voie ferrée. En effet, le Gornergratbahn, un chemin de fer à crémaillère, fait le bonheur de très nombreux touristes, été comme hiver. Depuis le point de vue de la gare terminale du Gornergratbahn, le 6 mars ou le 6 octobre, on peut voir par temps clair le soleil se coucher juste derrière le Cervin."],"src":"https://fr.vikidia.org/wiki/Mont_Cervin","sw":"v","q":"Q1374","pays":["CH","IT"],"c":["europe"]},"cevennes":{"n":"Cévennes","t":"massif","alt":1702,"massif":"Massif central","bref":["Les Cévennes sont une chaîne de montagnes, faisant partie du Massif central, et situées sur les départements de la Lozère et du Gard."],"src":"https://fr.vikidia.org/wiki/C%C3%A9vennes","sw":"v","q":"Q626655","pays":["FR"],"c":["europe"]},"chaine-des-cascades":{"n":"Chaîne des Cascades","t":"massif","alt":4392,"massif":"chaînes côtières du Pacifique","bref":["La chaîne des Cascades, en anglais Cascade Range, est une suite montagneuse qui prend naissance au Canada, sur la rive sud du fleuve Fraser, en Colombie-Britannique, et se poursuit aux États-Unis dans les États de Washington et de l'Oregon pour se terminer en Californie dans les environs du pic Lassen. La chaîne a une longueur de 1 210 kilomètres et est orientée nord-sud."],"src":"https://fr.vikidia.org/wiki/Cha%C3%AEne_des_Cascades","sw":"v","q":"Q4558","pays":["US","CA"],"c":["amerique-nord"]},"chaine-pontique":{"n":"Chaîne pontique","t":"massif","alt":3937,"bref":["La chaîne pontique, aussi appelée Alpes pontiques, est un massif montagneux situé dans le nord de la Turquie (il tire son nom de la région du Pont), et dont l'extrémité orientale atteint le sud-ouest de la Géorgie. La chaîne s'étire approximativement d'ouest en est sur 500 km, surplombant la côte méridionale de la mer Noire. Son sommet le plus élevé est le Kaçkar Dağı (ou mont Cauron jusqu'au XIe siècle) qui s'élève à 3 942 m. La faille nord-anatolienne et la faille anatolienne du nord-est courent le long de la chaîne.","Les montagnes sont principalement couvertes de forêts denses, composées majoritairement de conifères et formant une écorégion spécifique. L'étroite plaine côtière entre les sommets de la chaîne et la mer, ainsi que les nombreuses vallées qui l'arrosent, ont été autrefois le cœur du royaume du Pont et de l'empire de Trébizonde ; elle abrite une forêt tempérée humide. Le plateau anatolien, au sud de la chaîne, connaît un climat continental bien plus sec."],"src":"https://fr.wikipedia.org/wiki/Cha%C3%AEne_pontique","sw":"w","q":"Q519263","pays":["TR"],"c":["asie","europe"]},"chaine-transantarctique":{"n":"Chaîne Transantarctique","t":"massif","alt":4528,"bref":["La chaîne Transantarctique, ou monts Transantarctiques, est une longue chaîne de montagnes située en Antarctique. Elle traverse une grande partie du continent, de la terre Victoria à la mer de Weddell, en séparant sa partie orientale d'une part de sa partie occidentale et de la côte ouest de la mer de Ross d'autre part. Elle est entrecoupée par de nombreux glaciers alimentés par l'inlandsis Est-Antarctique et s'épanchant depuis le plateau Antarctique. Elle culmine à 4 528 mètres d'altitude au mont Kirkpatrick et possède vingt sommets d'au moins 4 000 mètres d'altitude."],"src":"https://fr.wikipedia.org/wiki/Cha%C3%AEne_Transantarctique","sw":"w","q":"Q319671"},"chimborazo":{"n":"Chimborazo","t":"volcan","alt":6263,"massif":"cordillère des Andes","bref":["Le Chimborazo est un volcan d’Équateur culminant à 6 263 m d’altitude et situé près de Riobamba, à environ 180 km au sud de Quito. C’est le plus haut sommet des Andes équatoriennes, qui domine une région de 50 000 km2, sa base faisant 20 km de diamètre.","Il est surnommé Taita Chimborazo, c’est-à-dire Papa Chimborazo, la mère associée étant Mama Tungurahua."],"src":"https://fr.wikipedia.org/wiki/Chimborazo_(volcan)","sw":"w","q":"Q14081","pays":["EC"],"c":["amerique-sud"]},"chkhara":{"n":"Chkhara","t":"sommet","alt":5193,"massif":"Muraille de Bezengui","bref":["Le Chkhara est une montagne du Grand Caucase sur la frontière entre la Géorgie et la Russie. À une altitude de 5 193 m, il est le point culminant de la Géorgie, et le troisième sommet le plus élevé de Russie et du continent européen. Située à l'extrémité orientale de la muraille de Bezengui, la montagne fait partie de la chaîne du Grand Caucase central.","À sa base se trouve la communauté d'Ouchgouli, un groupe de villages de la région géorgienne de Svanétie établi au moins depuis le haut Moyen Âge et devenu une destination touristique importante de Géorgie, tandis que le versant nord se trouve au sein de la réserve naturelle de haute montagne de Kabardino-Balkarie. Ce n'est qu'en 1888 que la montagne apparaît dans les documents officiels sous ce nom, après la première ascension de son sommet par une équipe anglo-suisse. La montagne est ensuite escaladée à de nombreuses reprises au cours du XXe siècle, mais reste l'une des ascensions les plus difficiles d'Europe, parfois comparée au mont Everest."],"src":"https://fr.wikipedia.org/wiki/Chkhara","sw":"w","q":"Q217457","pays":["GE","RU"],"c":["europe","asie"]},"cho-oyu":{"n":"Cho Oyu","t":"sommet","alt":8188,"massif":"Mahalangur Himal","bref":["Le Cho Oyu est un sommet culminant à 8 188 mètres d'altitude, à la frontière entre le Tibet, en Chine, et le Népal, dans l'Himalaya. Il constitue le sixième sommet le plus élevé du monde. Sa première ascension a été réussie le 19 octobre 1954, un an et demi après celle de l'Everest situé à moins de trente kilomètres, par Herbert Tichy, Josef Jöchler et Pasang Dawa Lama. L'itinéraire qu'ils ont gravi, se terminant sur la face nord-ouest et peu technique, est devenu la voie normale empruntée par la quasi-totalité des alpinistes, malgré une grande diversité de voies ouvertes dans la seconde moitié du XXe siècle. Les versants nord et sud font respectivement partie de la réserve naturelle du Qomolangma et du parc national de Sagarmatha."],"src":"https://fr.wikipedia.org/wiki/Cho_Oyu","sw":"w","q":"Q170089","pays":["NP","CN"],"c":["asie"]},"copahue":{"n":"Copahue","t":"volcan","alt":2997,"massif":"cordillère des Andes","bref":["Le Copahue est un stratovolcan situé à la frontière entre l'Argentine et le Chili."],"src":"https://fr.wikipedia.org/wiki/Copahue","sw":"w","q":"Q312930","pays":["AR","CL"],"c":["amerique-sud"]},"cordillere-australienne":{"n":"Cordillère australienne","t":"massif","alt":2228,"bref":["La Cordillère australienne (en anglais : Great Dividing Range) est une chaîne de montagnes de l'Est de l'Australie. D'une longueur d'environ 3500 km, elle traverse trois États et un territoire : l'État de Victoria depuis les monts Grampians, la Nouvelle-Galles du Sud, le territoire de la capitale fédérale, et enfin le Queensland jusqu'au cap Melville."],"src":"https://fr.vikidia.org/wiki/Cordill%C3%A8re_australienne","sw":"v","q":"Q192583","pays":["AU"],"c":["oceanie"]},"cordillere-des-andes":{"n":"Cordillère des Andes","t":"massif","alt":6962,"massif":"cordillère américaine","bref":["La cordillère des Andes, couramment appelée les Andes, est une chaîne de montagnes d'Amérique du Sud. C'est la plus longue de la Terre et, après avoir décrit un arc dans le Nord de l'Amérique du Sud, elle s'oriente nord-sud le long de la côte ouest du Chili. Les habitants des Andes sont les Andins.","Le mot Andes vient du quechua anti qui désigne les habitants de la montagne du Pérou. Le mot cordillère quant à lui vient de l'espagnol cordillera, qui signifie « corde »."],"src":"https://fr.vikidia.org/wiki/Cordill%C3%A8re_des_Andes","sw":"v","q":"Q5456","pays":["BO","CL","CO","EC","PE","VE","AR"],"c":["amerique-sud"]},"cordillere-du-kunlun":{"n":"Cordillère du Kunlun","t":"massif","alt":7167,"bref":["La cordillère du Kunlun (ou Kunlun Shan en chinois) est un système montagneux d'Asie centrale qui s'étend depuis le Pamir au Tadjikistan à l'ouest jusqu'aux chaînes adjacentes (Burhan Budai, Bayan Har et A'nyêmaqên Shan) de la province centrale de Qinghai, en Chine, à l'est. D'une longueur d'environ 2 600 kilomètres, le Kunlun a une largeur variable, sans toutefois dépasser 170 kilomètres."],"src":"https://fr.vikidia.org/wiki/Cordill%C3%A8re_du_Kunlun","sw":"v","q":"Q187871","pays":["CN"],"c":["asie"]},"cotopaxi":{"n":"Cotopaxi","t":"volcan","alt":5897,"massif":"cordillère des Andes","bref":["Le volcan Cotopaxi (en espagnol, volcán Cotopaxi) est situé en Équateur, et plus précisément à 56 km au sud de la capitale, Quito, et à 75 km au sud de la ligne équatoriale."],"src":"https://fr.vikidia.org/wiki/Volcan_Cotopaxi","sw":"v","q":"Q181476","pays":["EC"],"c":["amerique-sud"]},"denali":{"n":"Denali","t":"sommet","alt":6190,"massif":"chaîne d'Alaska","bref":["Le mont McKinley (auparavant Denali, de 2015 à 2025) est le point culminant de l'Amérique du Nord (définition comprenant une grande partie du Mexique jusqu'à l'isthme de Tehuantepec). Il se situe aux États-Unis, dans l'État d'Alaska, et a une altitude de 6 190 m (20 310 pieds).","La décision de changer le nom « Denali » en « mont McKinley » a été prise par le président Donald Trump et rendue effective le 24 janvier 2025."],"src":"https://fr.vikidia.org/wiki/Mont_McKinley","sw":"v","q":"Q130018","pays":["US"],"c":["amerique-nord"]},"dhaulagiri":{"n":"Dhaulagiri","t":"sommet","alt":8167,"massif":"Himalaya","bref":["Le Dhaulagiri, ou Dhaulagiri I, est un sommet culminant à 8 167 mètres d'altitude au Népal, dans l'Himalaya. Il constitue le septième plus haut sommet du monde. Sa première ascension a été réussie le 13 mai 1960 par Albin Schelbert, Kurt Diemberger, Ernst Forrer, Peter Diener, avec Nawang Dorje et Nima Dorje, aidés d'un avion. Leur itinéraire, par l'arête nord-est, est devenu la voie normale empruntée par la grande majorité des alpinistes."],"src":"https://fr.wikipedia.org/wiki/Dhaulagiri","sw":"w","q":"Q165440","pays":["NP"],"c":["asie"]},"djebel-toubkal":{"n":"Djebel Toubkal","t":"sommet","alt":4167,"massif":"Haut Atlas","bref":["Le djebel Toubkal est le point culminant d'Afrique du Nord, du Maroc, du Haut Atlas et de l'Atlas en général. C'est dans le Haut Atlas et dans la province d'Al Haouz que se situe le sommet. Son altitude de 4 167 mètres, lui confère le vingt-et-unième rang d'Afrique. Marrakech se trouve à 64 kilomètres au nord. La station hivernale d'Oukaïmeden se situe à dix-sept kilomètres au nord-nord-est."],"src":"https://fr.vikidia.org/wiki/Djebel_Toubkal","sw":"v","q":"Q503433","pays":["MA"],"c":["afrique"]},"dolomites":{"n":"Dolomites","t":"massif","alt":3343,"massif":"Préalpes orientales méridionales","bref":["Les Dolomites (en italien : Dolomiti ; en allemand : Dolomiten ; en ladin : Dolomites), anciennement appelées Monti Pallidi (« montagnes pâles »), sont un massif montagneux des Préalpes orientales méridionales réparti de façon à peu près égale entre les régions italiennes du Trentin-Haut-Adige et de la Vénétie.","Territoire aux limites imprécises, les Dolomites correspondent à un ensemble alpin incluant au sens large les Alpes de Fiemme et les Préalpes vicentines. Culminant à 3 343 mètres à la Marmolada, ce massif se caractérise par l'abondance de la dolomie, roche sédimentaire carbonatée auquel leur nom actuel est associé."],"src":"https://fr.wikipedia.org/wiki/Dolomites","sw":"w","q":"Q1283","pays":["IT"],"c":["europe"]},"drakensberg":{"n":"Drakensberg","t":"massif","alt":3482,"massif":"Great Escarpment, Australia","bref":["Le Drakensberg (en afrikaans : Drakensberge, en zoulou : uKhahlamba, en langues sotho-tswana : Maluti) est une chaîne de montagnes en Afrique australe. Situé dans l'Est de l'Afrique du Sud, au Lesotho et en Eswatini, il correspond géographiquement à la partie orientale du Grand Escarpement. Il culmine à 3 482 m d'altitude au Thabana Ntlenyana.","Un parc classé sur la liste du patrimoine mondial protège la faune, la flore et les vestiges archéologiques."],"src":"https://fr.wikipedia.org/wiki/Drakensberg_(cha%C3%AEne_de_montagnes)","sw":"w","q":"Q183295","pays":["ZA","LS"],"c":["afrique"]},"eifel":{"n":"Eifel","t":"massif","alt":747,"massif":"Massif schisteux rhénan","bref":["L'Eifel est une région de collines à l'ouest de l'Allemagne et à l'est de la Belgique. Il fait partie du massif schisteux rhénan."],"src":"https://fr.vikidia.org/wiki/Eifel","sw":"v","q":"Q152356","pays":["DE"],"c":["europe"]},"eiger":{"n":"Eiger","t":"sommet","alt":3967,"massif":"Chaîne Jungfrau-Fiescherhorn","bref":["L’Eiger est un sommet individualisé des Alpes situé en Suisse dans le massif des Alpes bernoises. Son nom, attesté en 1252, ne signifie pas « ogre », contrairement à une idée reçue, mais plus probablement « grand épieu ». La confusion est due aux alpinistes morts lors de la montée de la face nord : celle-ci, presque totalement verticale ou déversante, est considérée comme la plus impressionnante et la plus célèbre face des Alpes, si ce n'est la plus haute. Avec les faces nord du Cervin et des Grandes Jorasses, elle a constitué pour l'alpinisme l'un des « trois derniers problèmes des Alpes », et le dernier résolu.","L'Eiger est traversé par le tunnel d'un chemin de fer à crémaillère de la compagnie de la Jungfraubahn. Il existe une gare dans la paroi de la face nord, appelée Eigerwand, qui permet d'avoir une vue au sein de la face nord."],"src":"https://fr.wikipedia.org/wiki/Eiger","sw":"w","q":"Q4425","pays":["CH"],"c":["europe"]},"el-chichon":{"n":"El Chichón","t":"volcan","alt":1060,"massif":"Sierra Madre de Chiapas","bref":["El Chichón est un volcan du Mexique situé à moins d'une vingtaine de kilomètres de la route reliant Villahermosa à Tuxtla Gutiérrez."],"src":"https://fr.wikipedia.org/wiki/El_Chich%C3%B3n","sw":"w","q":"Q841189","pays":["MX"],"c":["amerique-nord"]},"elbourz":{"n":"Elbourz","t":"massif","alt":5610,"bref":["L'Elbourz, en persan ou Alborz, est une chaîne de montagnes située dans le Nord de l'Iran. Son versant septentrional borde la mer Caspienne. La chaîne constitue un arc montagneux de 920 kilomètres de long qui s'étend de la frontière de l'Azerbaïdjan à l'ouest à la région du Khorassan à l'est, en ne dépassant toutefois pas la ville de Machhad. La capitale du pays, Téhéran, se trouve juste au pied de la chaîne, dans une échancrure de sa partie centrale, sur le versant sud."],"src":"https://fr.vikidia.org/wiki/Elbourz","sw":"v","q":"Q484725","pays":["IR"],"c":["asie"]},"elbrouz":{"n":"Elbrouz","t":"sommet","alt":5642,"massif":"Bokovoy Range","bref":["Le mont Elbrouz ou mont Elbrous, en russe est un stratovolcan endormi situé dans le Grand Caucase, dans l'Ouest de la Russie.","De nombreuses légendes tournent autour de cette montagne, comme celle qui raconte que Prométhée y aurait été attaché par Zeus pour le punir d'avoir doté les hommes du feu. Selon cette même légende, son foie serait dévoré chaque jour par un aigle, mais repousserait la nuit."],"src":"https://fr.vikidia.org/wiki/Mont_Elbrouz","sw":"v","q":"Q43105","pays":["RU"],"c":["asie","europe"]},"emi-koussi":{"n":"Emi Koussi","t":"volcan","alt":3445,"massif":"massif du Tibesti","bref":["L'Emi Koussi est un volcan éteint du Tchad situé dans le nord du pays et faisant partie du massif du Tibesti. Son altitude de 3 415 mètres en fait le point culminant du Tibesti, du Tchad et du Sahara."],"src":"https://fr.wikipedia.org/wiki/Emi_Koussi","sw":"w","q":"Q257441","pays":["TD"],"c":["afrique"]},"etna":{"n":"Etna","t":"volcan","alt":3357,"bref":["L’Etna est un volcan actif situé au nord-nord-ouest de Catane, en Sicile, la plus grande île d'Italie. L'Etna forme une montagne massive d'une hauteur de 3 357 mètres, ce qui en fait le volcan le plus haut d'Europe. Durant les 125 dernières années, son altitude a pris quatre-vingt-trois mètres de plus à cause de l'accumulation des coulées de lave et de boue."],"src":"https://fr.vikidia.org/wiki/Etna","sw":"v","q":"Q16990","pays":["IT"],"c":["europe"]},"everest":{"n":"Everest","t":"sommet","alt":8849,"massif":"Mahalangur Himal","bref":["Le mont Everest, ou plus simplement l’Everest, aussi appelé Chomolangma Feng (« Déesse mère des neiges » en tibétain) ou Sagarmatha (« Mère de l'Univers » en népalais), est un mont situé au centre de la chaîne de l'Himalaya, entre le Népal et le Tibet (situé en Chine), au sud de l'Asie centrale.","Son sommet est le plus élevé du monde : il y fait si froid que la neige ne fond pas de l'année. Les dernières mesures donnent une hauteur d'environ 8 848 m, mais sont généralement reconnues celles de 1999 : environ 8 850 m. Il fait partie des quatorze sommets de plus de 8 000 m, tous répartis entre l'Himalaya et le Karakoram."],"src":"https://fr.vikidia.org/wiki/Mont_Everest","sw":"v","q":"Q513","pays":["NP","CN"],"c":["asie"]},"foret-noire":{"n":"Forêt-Noire","t":"sommet","alt":1493,"bref":["La Forêt-Noire, en allemand Schwarzwald, est une région montagneuse du sud-ouest de l'Allemagne, qui fait face aux Vosges, de l'autre côté du Rhin. Elle est située dans le Land du Bade-Wurtemberg, non loin des agglomérations de Karlsruhe, Fribourg-en-Brisgau et Stuttgart, et à une trentaine de kilomètres à l'est de la ville française de Strasbourg.","Son point culminant est le Feldberg (1493 mètres). Il est situé en haute Forêt-Noire, au sud du massif montagneux. Plusieurs petits lacs sont situés au sein de la Forêt-Noire, comme par exemple le Titisee et le Schluchsee au sud, ou encore le Mummelsee au centre."],"src":"https://fr.vikidia.org/wiki/For%C3%AAt-Noire","sw":"v","q":"Q4204","pays":["DE"],"c":["europe"]},"gangkhar-puensum":{"n":"Gangkhar Puensum","t":"sommet","alt":7570,"massif":"Himalaya","bref":["Le Gangkhar Puensum, Gangkar Punsum ou Gankar Punzum (« les trois frères spirituels »), est une montagne à la frontière entre le Bhoutan et la Chine culminant à 7 570 mètres d'altitude. C'est le point culminant du Bhoutan, et le plus haut sommet vierge du monde."],"src":"https://fr.wikipedia.org/wiki/Gangkhar_Puensum","sw":"w","q":"Q219986","pays":["BT"],"c":["asie"]},"gasherbrum-i":{"n":"Gasherbrum I","t":"sommet","alt":8080,"massif":"Gasherbrum","bref":["Le Gasherbrum I, ou Hidden Peak, anciennement K5, est un sommet culminant à 8 080 mètres d'altitude, à la frontière entre la Chine et le Pakistan, dans le Karakoram. Il constitue le onzième plus haut sommet du monde. Sa première ascension a été réussie le 5 juillet 1958 par les Américains Pete Schoening et Andy Kauffman. La voie normale est depuis devenue le couloir des Japonais, grimpé pour la première fois en 1986."],"src":"https://fr.wikipedia.org/wiki/Gasherbrum_I","sw":"w","q":"Q187138","pays":["PK","CN"],"c":["asie"]},"gasherbrum-ii":{"n":"Gasherbrum II","t":"sommet","alt":8034,"massif":"Gasherbrum","bref":["Le Gasherbrum II, anciennement K4, est un sommet culminant à 8 035 mètres d'altitude, à la frontière entre la Chine et le Pakistan, dans le Karakoram. Il constitue le treizième plus haut sommet au monde. Sa première ascension a été réussie le 7 juillet 1956 par les Autrichiens Josef Larch, Fritz Moravec et Hans Willenpart. Leur itinéraire, par l'arête sud-ouest puis le final par l'arête est, est devenu la voie normale empruntée par la quasi-totalité des alpinistes, les autres voies étant rarement répétées."],"src":"https://fr.wikipedia.org/wiki/Gasherbrum_II","sw":"w","q":"Q186853","pays":["PK","CN"],"c":["asie"]},"gerlachovsky-stit":{"n":"Gerlachovský štít","t":"sommet","alt":2654,"massif":"Hautes Tatras","bref":["Le Gerlachovský štít, parfois Gerlach ou pic Gerlach en français, culmine à 2 654 mètres d'altitude ce qui en fait le point culminant de la Slovaquie, de la chaîne des Tatras et de toutes les Carpates. Il était le point culminant de la Hongrie jusqu'à la fin de la Première Guerre mondiale et celui de la Tchécoslovaquie jusqu'en 1992.","Longtemps considéré par erreur comme une montagne de taille moyenne du massif des Hautes Tatras, il a pris une grande importance depuis les mesures par triangulation du début du XIXe siècle qui ont établi sa prédominance au point de changer six fois de nom, dont quatre différents, au cours des XIXe et XXe siècles. D'aspect pyramidal, marqué par un important cirque, il a été gravi pour la première fois en 1834."],"src":"https://fr.wikipedia.org/wiki/Gerlachovsk%C3%BD_%C5%A1t%C3%ADt","sw":"w","q":"Q81213","pays":["SK"],"c":["europe"]},"ghats-occidentaux":{"n":"Ghâts occidentaux","t":"massif","alt":2695,"bref":["Les Ghats occidentaux ou Sahyadrī sont une chaîne de montagnes ; ils bordent le plateau du Deccan dans l'Ouest de l'Inde (à l'opposé des Ghats orientaux), et le séparent de l'étroite plaine côtière des mers d'Arabie et des Laquedives. De par sa richesse naturelle cette région est classée comme un point chaud de biodiversité par Conservation International."],"src":"https://fr.wikipedia.org/wiki/Ghats_occidentaux","sw":"w","q":"Q4527","pays":["IN"],"c":["asie"]},"grand-balkan":{"n":"Grand Balkan","t":"massif","alt":2376,"massif":"Balcanides","bref":["Le Grand Balkan, est une chaîne de montagnes des Balkans située en Bulgarie et Serbie. Son point culminant est le pic Botev (2 376 m)."],"src":"https://fr.wikipedia.org/wiki/Grand_Balkan","sw":"w","q":"Q170427","pays":["RS","BG"],"c":["europe"]},"grand-caucase":{"n":"Grand Caucase","t":"massif","alt":5642,"massif":"Caucase","bref":["Le Grand Caucase est une des deux chaînes de montagnes du Caucase. Il est séparé de l'autre chaîne, située plus au sud et appelée Petit Caucase, par la Transcaucasie."],"src":"https://fr.wikipedia.org/wiki/Grand_Caucase","sw":"w","q":"Q486986","pays":["AZ","GE","RU"],"c":["asie","europe"]},"grandes-jorasses":{"n":"Grandes Jorasses","t":"sommet","alt":4208,"massif":"massif du Mont-Blanc","bref":["Les Grandes Jorasses sont un sommet des Alpes dans le massif du Mont-Blanc, entre la France (Haute-Savoie) et l'Italie (Vallée d'Aoste)."],"src":"https://fr.wikipedia.org/wiki/Grandes_Jorasses","sw":"w","q":"Q30453","pays":["IT","FR"],"c":["europe"]},"grimsvotn":{"n":"Grímsvötn","t":"volcan","alt":1725,"bref":["Le Grímsvötn est un volcan d'Islande situé sous la calotte glaciaire du Vatnajökull, sur les Hautes Terres d'Islande, dans une région éloignée de toute habitation et infrastructure. Il s'agit d'une caldeira n'émergeant du glacier que sous la forme d'un escarpement rocheux et abritant un lac sous-glaciaire, lui aussi appelé Grímsvötn. Le débordement de ce lac, généralement en raison d'éruptions sous-glaciaires, entraîne régulièrement des jökulhlaups, un type d'inondations brutales et dévastatrices. Le Grímsvötn est l'un des volcans les plus actifs d'Islande avec en moyenne une éruption tous les dix ans au cours du XXe siècle."],"src":"https://fr.wikipedia.org/wiki/Gr%C3%ADmsv%C3%B6tn","sw":"w","q":"Q182913","pays":["IS"],"c":["europe"]},"grossglockner":{"n":"Grossglockner","t":"sommet","alt":3798,"massif":"Glockner Group","bref":["Le Großglockner ou Grossglockner, souvent abrégé en Glockner, est, avec 3 798 mètres d'altitude, le point culminant de l'Autriche, entre la Carinthie et le Tyrol. Ce pic marqué, en roches appartenant à un faciès à schistes verts, appartient au chaînon du Glockner situé au centre des Hohe Tauern, et est considéré comme le sommet le plus important des Alpes orientales. Depuis les premières reconnaissances au XVIIIe siècle et la première ascension par quatre alpinistes d'une grande expédition organisée par le prince-évêque Salm-Reifferscheidt-Krautheim en 1800, le Großglockner a joué un rôle important dans le développement de l'alpinisme. Il est resté très important pour le tourisme de la région et représente un but apprécié des alpinistes, avec 5 000 ascensions par an."],"src":"https://fr.wikipedia.org/wiki/Gro%C3%9Fglockner","sw":"w","q":"Q3388","pays":["AT"],"c":["europe"]},"harz":{"n":"Harz","t":"massif","alt":1141,"bref":["Le Harz, également en français le Hartz, est à la fois le nom donné à une région, à un district allemand, à un massif montagneux couvrant environ 2 000 km2 au centre-nord de l'Allemagne et à la forêt qui le couvre, parfois considérée comme une relique de la forêt hercynienne décrite par les auteurs antiques et médiévaux, elle-même relique de la forêt primaire européenne."],"src":"https://fr.wikipedia.org/wiki/Harz","sw":"w","q":"Q4186","pays":["DE"],"c":["europe"]},"haut-plateau-armenien":{"n":"Haut plateau arménien","t":"massif","alt":5,"massif":"Petit Caucase","bref":["Le haut plateau arménien ou plateau d'Arménie est une plaine d'altitude située en Arménie, dans la partie occidentale de l'Azerbaïdjan (enclave du Nakhitchevan), le Sud de la Géorgie, le Nord-Ouest de l'Iran et la partie nord-est de la Turquie. Ce territoire se situe entre 1 000 et 2 000 mètres d'altitude, au milieu des massifs montagneux de Transcaucasie qui relient le Petit Caucase aux monts Taurus."],"src":"https://fr.wikipedia.org/wiki/Haut_plateau_arm%C3%A9nien","sw":"w","q":"Q211263","pays":["AM","GE","TR","IR","AZ"],"c":["asie","europe"]},"hekla":{"n":"Hekla","t":"volcan","alt":1491,"bref":["L'Hekla est un volcan situé dans le sud de l'Islande, dans les Hautes Terres, et culmine à 1 488 mètres d'altitude. Il se situe à environ 50 km au nord-est du village de Hvolsvöllur. Il est l'un des volcans les plus actifs d'Islande avec plus de 20 éruptions depuis 874.","C'est l'un des volcans les plus connus d'Islande et également l'un des plus actifs. Il fait partie des stratovolcans basaltiques les plus actifs au monde. Bien qu'il soit assez facile d'accès, son sommet n'est gravi qu'en 1750 par Eggert Ólafson et Bjarni Pálsson, car la croyance locale voulait que ce soit l'entrée des Enfers."],"src":"https://fr.wikipedia.org/wiki/Hekla","sw":"w","q":"Q184975","pays":["IS"],"c":["europe"]},"himalaya":{"n":"Himalaya","t":"massif","alt":8849,"bref":["L'Himalaya, qui s'étend en Asie sur le Pakistan, l'Inde, le Népal, la Chine (Tibet) et le Bhoutan, est l'ensemble montagneux le plus haut du monde : son altitude moyenne est de plus de 4 000 m. Son point culminant, l'Everest (8 848 m), est par ailleurs le plus haut sommet du monde ; et dix des quatorze plus hauts sommets du monde — surnommés « les 8000 » — sont himalayens. Parmi eux le Kangchenjunga, deuxième sommet de l'Himalaya et point culminant de l'Inde. Les quatre autres se situent dans la chaîne du Karakoram. Aux extrémités de la chaîne, on trouve à l'ouest le Nanga Parbat et â l'est le Namcha Barwa."],"src":"https://fr.vikidia.org/wiki/Himalaya","sw":"v","q":"Q5451","pays":["NP","MM","CN","PK","IN","AF","BT"],"c":["asie"]},"hindou-kouch":{"n":"Hindou Kouch","t":"massif","alt":7708,"bref":["L'Hindou Kouch est une chaîne de hautes montagnes en Afghanistan et au Pakistan. Il est le prolongement occidental de la chaîne de l'Himalaya."],"src":"https://fr.wikipedia.org/wiki/Hindou_Kouch","sw":"w","q":"Q5472","pays":["AF","PK"],"c":["asie"]},"hoggar":{"n":"Hoggar","t":"massif","alt":2908,"bref":["Le Hoggar (ou Ahaggar) est un massif montagneux du Sud-Est de l'Algérie dans le désert du Sahara. Le Hoggar culmine au Tahat à 2 918 m d'altitude (qui est aussi le point culminant de l'Algérie). Le Hoggar a environ 3 800 km2 de superficie.","Le massif est formé de plateaux étagés composés de granites et de gneiss. La partie centrale (Koudiat) est un massif volcanique, avec du basalte et du porphyre très démantelé par l'érosion et présente de nombreux pitons rocheux."],"src":"https://fr.vikidia.org/wiki/Hoggar","sw":"v","q":"Q26399","pays":["DZ"],"c":["afrique"]},"hoverla":{"n":"Hoverla","t":"sommet","alt":2061,"massif":"Chornohora","bref":["Le mont Hoverla, avec 2 061 m, est la montagne la plus haute d'Ukraine. Il est situé dans les Carpates orientales, dans la région appelée Tchornohora (littéralement « montagne noire » en français). Ses pentes sont recouvertes de forêts de hêtres et d'épicéas, au-dessus desquelles se trouve l'étage des prairies subalpines, appelées polonyna en polonais et ukrainien. Sur son versant est se trouve la source principale de la rivière Prout."],"src":"https://fr.wikipedia.org/wiki/Hoverla","sw":"w","q":"Q627508","pays":["UA"],"c":["europe"]},"ile-amsterdam":{"n":"Île Amsterdam","t":"volcan","alt":867,"bref":["L'île Amsterdam, appelée île de la Nouvelle-Amsterdam jusqu'en 1965, est une petite île française subantarctique située dans le sud de l'océan Indien, à 1 368 km au nord-nord-est des îles Kerguelen et à 2 713 km au sud-est de l'île Maurice. Elle forme avec l'île Saint-Paul, distante de 91 km plus au sud, le district des îles Saint-Paul et Amsterdam, l'un des cinq districts des Terres australes et antarctiques françaises (les quatre autres sont l'archipel Crozet, les îles Kerguelen, la terre Adélie et les îles Éparses)."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Amsterdam","sw":"w","q":"Q194215","pays":["FR"],"c":["europe"]},"jengish-chokusu":{"n":"Jengish Chokusu","t":"sommet","alt":7439,"massif":"Kakshaal Too","bref":["Le Jengish Chokusu, anciennement pic Pobedy (pic de la Victoire) ou en chinois Tömür Feng, est le point culminant du Tian Shan et du Kirghizistan. Il est situé sur la frontière entre la Chine et le Kirghizistan. Le sommet s'élève à 7 439 d'altitude dans le Kakshaal-Too, un chaînon du Tian Shan central. Son nom (Jengish, victoire) commémore la victoire des Alliés à la fin de la Deuxième Guerre mondiale, le terme « chokusu » signifiant « pic »."],"src":"https://fr.vikidia.org/wiki/Jengish_Chokusu","sw":"v","q":"Q332762","pays":["KG","CN"],"c":["asie"]},"jungfrau":{"n":"Jungfrau","t":"sommet","alt":4158,"massif":"Chaîne Jungfrau-Fiescherhorn","bref":["La Jungfrau est un sommet individualisé des Alpes situé en Suisse dans le massif des Alpes bernoises. Il culmine à 4 158 mètres d'altitude."],"src":"https://fr.wikipedia.org/wiki/Jungfrau","sw":"w","q":"Q15312","pays":["CH"],"c":["europe"]},"k2":{"n":"K2","t":"sommet","alt":8611,"massif":"Baltoro Muztagh","bref":["Le K2, en chinois Qogir Feng, est le point culminant de la chaîne du Karakoram. Il s'élève à 8 611 m d'altitude. La montagne fut longtemps appelée « mont Godwin-Austen », du nom d'un topographe et géographe britannique, mais celui-ci nom ne fut jamais rendu officiel. Ce toponyme apparut pourtant sur de nombreuses cartes. Aujourd'hui, un glacier proche du K2 rend hommage à cet expert-géographe."],"src":"https://fr.vikidia.org/wiki/K2","sw":"v","q":"Q43512","pays":["PK"],"c":["asie"]},"kangchenjunga":{"n":"Kangchenjunga","t":"sommet","alt":8586,"massif":"Himalaya","bref":["Le Kangchenjunga (ou Kanchenjunga) est avec 8 586 mètres d'altitude le point culminant de l'Inde, le deuxième sommet de l'Himalaya et le troisième du monde. Sa proéminence est de 3 922 mètres, mesure qui classe la montagne ving-neuvième du monde pour cette spécialité. Au Tibet, il est nommé Sewalungma en limbou, une langue tibéto-birmane."],"src":"https://fr.vikidia.org/wiki/Kangchenjunga","sw":"v","q":"Q82019","pays":["IN","NP"],"c":["asie"]},"karakoram":{"n":"Karakoram","t":"massif","alt":8611,"bref":["Le Karakoram ou Karakorum est une chaîne de montagnes se trouvant dans la région montagneuse du Gilgit-Baltistan, dans le Nord du Pakistan, du Nord de l’Inde et de l'Ouest de la Chine."],"src":"https://fr.wikipedia.org/wiki/Karakoram","sw":"w","q":"Q5469","pays":["CN","TJ","IN","AF","PK"],"c":["asie"]},"katla":{"n":"Katla","t":"volcan","alt":1450,"bref":["Le Katla est un volcan d'Islande recouvert par le Mýrdalsjökull, une calotte glaciaire du Sud du pays. Il est situé à l'est de l'Eyjafjöll, un autre volcan considéré comme lié au Katla. Il s'agit d'un des volcans les plus actifs et des plus destructeurs d'Islande, à l'origine de plusieurs jökulhlaups."],"src":"https://fr.wikipedia.org/wiki/Katla","sw":"w","q":"Q201914","pays":["IS"],"c":["europe"]},"kebnekaise":{"n":"Kebnekaise","t":"massif","alt":2097,"massif":"Alpes scandinaves","bref":["Le Kebnekaise, en same Giebmegáisi ou Giebnegáisi, littéralement « rebord du chaudron », est un sommet de Suède, point culminant du pays avec 2 097 mètres d'altitude. Bien que situé dans une région reculée dans le nord du pays, il constitue un but de randonnée populaire."],"src":"https://fr.wikipedia.org/wiki/Kebnekaise","sw":"w","q":"Q214011","pays":["SE"],"c":["europe"]},"khan-tengri":{"n":"Khan Tengri","t":"sommet","alt":7010,"massif":"Tengritau","bref":["Le Khan Tengri est une montagne qui s'élève à 7 010 mètres d'altitude dans la chaîne du Tian Shan. Ce sommet est le point culminant du Kazakhstan, à la frontière avec le Kirghizistan dont il est le troisième plus haut sommet, et très proche du Xinjiang en Chine. Il est gravi pour la première fois en 1931 par Mikhail Pogrebetsky. Sommet particulièrement dangereux, son ascension est principalement tentée par des alpinistes russes et kazakhs."],"src":"https://fr.wikipedia.org/wiki/Khan_Tengri","sw":"w","q":"Q211529","pays":["KG","KZ","CN"],"c":["asie","europe"]},"kilauea":{"n":"Kīlauea","t":"volcan","alt":1247,"massif":"chaîne sous-marine Hawaï-Empereur","bref":["Le Kīlauea ou Kilauea est un volcan situé dans le sud-est de l'île d'Hawaï, elle-même située dans le sud-est de l'archipel d'Hawaï aux États-Unis. Ce volcan bouclier s'est construit au pied du Mauna Loa voisin et culmine à 1 246,2 mètres d'altitude, ce qui en fait l'un des plus imposants du monde si on tient compte de l'empilement total de ses coulées de lave. De son sommet couronné par une caldeira de cinq kilomètres de longueur s'égrènent dans deux directions de nombreux cratères, cônes et fissures volcaniques sur plusieurs dizaines de kilomètres de longueur. Le Kīlauea est l'un des volcans les plus actifs au monde, avec 52 éruptions au XXe siècle, dont celle du ayant duré 35 ans, de 1983 à 2018."],"src":"https://fr.wikipedia.org/wiki/K%C4%ABlauea","sw":"w","q":"Q188698","pays":["US"],"c":["amerique-nord"]},"kilimanjaro":{"n":"Kilimanjaro","t":"volcan","alt":5895,"massif":"Montagnes du rift est-africain","bref":["Le Kilimandjaro ou Kilimanjaro est une montagne d'Afrique composée de trois volcans éteints. Son point culminant est le pic Uhuru, sur le mont Kibo, qui s'élève à 5 891 mètres d'altitude.","Le Kilimandjaro fut découvert en 1848 par les Allemands Johannes Rebmann et Johann Ludwig Krapf, deux missionnaires de l'Église."],"src":"https://fr.vikidia.org/wiki/Kilimandjaro","sw":"v","q":"Q7296","pays":["TZ"],"c":["afrique"]},"klioutchevskoi":{"n":"Klioutchevskoï","t":"volcan","alt":4800,"massif":"Groupe volcanique du Klioutchevskoï","bref":["Le Klioutchevskoï ou Klioutchevskaïa Sopka est un volcan actif situé en Russie, dans le centre du Kamtchatka. Administrativement, il fait partie du kraï du Kamtchatka, situé dans l'Extrême-Orient russe. Il se trouve à 84 kilomètres à l'ouest-nord-ouest des rives de l'océan Pacifique les plus proches et à 358 kilomètres au nord-nord-est de Petropavlovsk-Kamtchatski, la capitale du kraï.","La première ascension fut réalisée en 1788 par Daniel Gauss et deux membres de l'expédition Billings."],"src":"https://fr.vikidia.org/wiki/Klioutchevsko%C3%AF","sw":"v","q":"Q210252","pays":["RU"],"c":["asie","europe"]},"la-soufriere":{"n":"La Soufrière","t":"volcan","alt":1467,"massif":"Guadeloupe","bref":["La Soufrière, surnommée « vyé madanm la » en créole guadeloupéen, littéralement « la vieille dame » en français, est un volcan en activité situé sur le territoire de la commune de Saint-Claude en Guadeloupe, dans le parc national de la Guadeloupe et la réserve de biosphère de l'archipel de la Guadeloupe, dans le sud de l'île de Basse-Terre. La commune de Basse-Terre, chef-lieu du département et région d'outre-mer, se trouve à une dizaine de kilomètres au sud-ouest et les chutes du Carbet sur son flanc est. C’est le seul volcan actif de l’île, actuellement à l’état de repos éruptif.","La Soufrière fait partie d’un ensemble volcanique comprenant plusieurs bouches éruptives qui, en plus du dôme de lave principal, a formé plusieurs autres dômes, cônes (le morne Carmichaël, la Citerne, etc.) et cratères ; des sources chaudes sur les flancs du volcan et zones de fumerolles sont apparues au niveau des zones les plus actives."],"src":"https://fr.wikipedia.org/wiki/La_Soufri%C3%A8re_(Guadeloupe)","sw":"w","q":"Q1149310","pays":["FR"],"c":["europe"]},"lakagigar":{"n":"Lakagígar","t":"volcan","alt":812,"bref":["Les Lakagígar, toponyme islandais signifiant littéralement en français « les cratères du Laki », aussi appelés Laki par métonymie, sont un ensemble de plus de cent cratères volcaniques du Sud de l'Islande alignés sur 27 kilomètres de longueur le long d'une fissure volcanique ouverte de part et d'autre du Laki, un volcan antérieur à la formation des cratères. Il s'agit du même système volcanique que le Grímsvötn situé plus au nord-est sous le Vatnajökull.","Ils se sont formés au cours d'une éruption débutée en 1783, appelée Skaftáreldar, en français « feux de la Skaftá », et considérée comme la plus importante éruption lavique des temps historiques. Cette éruption eut d'importantes conséquences en Islande, à l'origine d'une importante famine, la Móðuharðindin, ainsi que dans le reste de l'Europe."],"src":"https://fr.wikipedia.org/wiki/Lakag%C3%ADgar","sw":"w","q":"Q203726","pays":["IS"],"c":["europe"]},"lascar":{"n":"Láscar","t":"volcan","alt":5592,"massif":"cordillère des Andes","bref":["Le Láscar est un volcan du Chili situé dans le nord du pays, dans les Andes. Considéré comme étant le volcan le plus actif de cette région du Chili, il est entouré par d'autres volcans comme l'Aguas Calientes, le Chiliques et l'Acamarachi."],"src":"https://fr.wikipedia.org/wiki/L%C3%A1scar","sw":"w","q":"Q48783","pays":["CL"],"c":["amerique-sud"]},"lhotse":{"n":"Lhotse","t":"sommet","alt":8516,"massif":"Mahalangur Himal","bref":["Le Lhotse est un sommet culminant à 8 516 mètres d'altitude, à la frontière entre la Chine et le Népal, dans l'Himalaya. Il constitue par son éĺévation le quatrième sommet du monde. Sa première ascension a été réussie le 18 mai 1956 par les Suisses Fritz Luchsinger et Ernst Reiss. Leur itinéraire, par le versant nord-ouest, est devenu la voie normale empruntée par la quasi-totalité des alpinistes, les autres voies n'étant pas répétées."],"src":"https://fr.wikipedia.org/wiki/Lhotse","sw":"w","q":"Q168702","pays":["NP","CN"],"c":["asie"]},"licancabur":{"n":"Licancabur","t":"volcan","alt":5920,"massif":"Cordillera Occidental","bref":["Le Licancabur est un stratovolcan andin, situé à la frontière entre la Bolivie et le Chili."],"src":"https://fr.wikipedia.org/wiki/Licancabur","sw":"w","q":"Q422713","pays":["BO","CL"],"c":["amerique-sud"]},"llullaillaco":{"n":"Llullaillaco","t":"volcan","alt":6723,"massif":"cordillère des Andes","bref":["Le Llullaillaco ou Llullay-Yacu est par son élévation le deuxième volcan actif au monde, après l'Ojos del Salado et constitue le site archéologique le plus haut du monde. Le volcan se trouve dans les Andes à la frontière entre l'Argentine (dans la province de Salta) et le Chili (dans la région d'Antofagasta)."],"src":"https://fr.wikipedia.org/wiki/Llullaillaco","sw":"w","q":"Q214916","pays":["AR","CL"],"c":["amerique-sud"]},"makalu":{"n":"Makalu","t":"sommet","alt":8485,"massif":"Mahalangur Himal","bref":["Le Makalu est un sommet culminant à 8 485 mètres d'altitude, à la frontière entre le Tibet, en Chine, et le Népal, dans l'Himalaya. Il constitue par son élévation le cinquième sommet du monde. Sa première ascension a été réussie le 15 mai 1955, deux ans après celle de l'Everest situé à moins de vingt kilomètres, par les Français Lionel Terray et Jean Couzy. Ses versants nord et sud font respectivement partie de la réserve naturelle du Qomolangma et du parc national de Makalu Barun."],"src":"https://fr.wikipedia.org/wiki/Makalu","sw":"w","q":"Q169986","pays":["NP","CN"],"c":["asie"]},"manaslu":{"n":"Manaslu","t":"sommet","alt":8163,"massif":"Mansiri Himal","bref":["Le Manaslu est une montagne située au Népal, dans la chaîne de l'Himalaya. Avec une altitude de 8 163 mètres, il est le huitième sommet le plus haut du monde.","Les Britanniques le représentent sur les cartes au milieu du XIXe siècle puis, à la suite de l'ouverture des frontières du Népal en 1950, ce sont les premiers à évaluer les difficultés de son relief pyramidal. Toutefois, le Japon lance cinq expéditions consécutives au cours de cette décennie et, le 9 mai 1956, Toshio Imanishi et le sherpa Gyalzen Norbu parviennent à atteindre son sommet par le versant nord-est, suivis de deux de leurs équipiers deux jours plus tard. Aucune autre expédition n'est lancée avant les années 1970. En 1971, une nouvelle expédition japonaise ouvre une voie le long de l'arête occidentale."],"src":"https://fr.wikipedia.org/wiki/Manaslu","sw":"w","q":"Q170070","pays":["NP"],"c":["asie"]},"massif-central":{"n":"Massif central","t":"massif","alt":1886,"bref":["Le Massif central est un massif montagneux au centre de la France. Il s'agit des restes érodés d'une très ancienne chaîne de montagnes, abritant principalement des roches granitiques, sur lesquelles on trouve les traces d'une grande chaîne de volcans, aujourd'hui éteints.","Au sud, on trouve d'immenses plateaux calcaires : les Grands Causses. Le point culminant est le puy de Sancy (1 886 m), qui est un volcan. Par sa position centrale, les pluies et l'enneigement une partie de l'année, il donne naissance à de nombreuses rivières qui alimentent la Seine, la Loire, le Rhône, la Garonne et la Dordogne. On le surnomme le « château d'eau » de la France."],"src":"https://fr.vikidia.org/wiki/Massif_central","sw":"v","q":"Q190695","pays":["FR"],"c":["europe"]},"massif-des-vosges":{"n":"Massif des Vosges","t":"massif","alt":1424,"bref":["Le massif des Vosges (ou les Vosges) est un ensemble montagneux d'altitude moyenne et de formes arrondies (les ballons) de l'est de la France. Le point culminant des Vosges est le Grand Ballon, dit aussi ballon de Guebwiller. Son altitude est de 1 424 mètres. Les Vosges isolent le plateau lorrain de la plaine d'Alsace."],"src":"https://fr.vikidia.org/wiki/Massif_des_Vosges","sw":"v","q":"Q187843","pays":["FR"],"c":["europe"]},"massif-vinson":{"n":"Massif Vinson","t":"massif","alt":4892,"massif":"massif Sentinel","bref":["Le massif Vinson est un massif de l'Antarctique occidental, situé dans la chaîne Sentinel, elle-même constituant une partie d'un plus grand ensemble, les monts Ellsworth. Le point le plus élevé du massif, désigné sous le nom de « mont Vinson », culmine à 4 892 mètres d'altitude. Il est le plus haut sommet du continent Antarctique, îles comprises."],"src":"https://fr.vikidia.org/wiki/Massif_Vinson","sw":"v","q":"Q163758"},"mauna-kea":{"n":"Mauna Kea","t":"volcan","alt":4207,"massif":"chaîne sous-marine Hawaï-Empereur","bref":["Le Mauna Kea est un volcan endormi situé dans l'océan Pacifique, dans la moitié nord de l'île d'Hawaï, dans l'archipel américain de même nom. Il est l'un des cinq volcans de Hawaï, avec le Kohala, le Huhalalai, le Mauna Loa et le Kilauea.","Le volcan atteint 4 205 mètres d'altitude au Pu'u Wekiu, la plus haute cîme de l'île. Cette élévation permet à Hawaï d'obtenir le sixième rang dans le classement des plus hauts États de l'union américaine. Le sommet fut gravi pour la première fois en 1823 par un missionnaire américain, Joseph F. Goodrich."],"src":"https://fr.vikidia.org/wiki/Mauna_Kea","sw":"v","q":"Q131230","pays":["US"],"c":["amerique-nord"]},"mauna-loa":{"n":"Mauna Loa","t":"volcan","alt":4169,"massif":"chaîne sous-marine Hawaï-Empereur","bref":["Le Mauna Loa est un volcan actif des États-Unis situé sur l'île d'Hawaï, dans l'État du même nom. Culminant à 4 169 mètres d'altitude, c'est le deuxième plus haut sommet de l'île et de l'archipel d'Hawaï après le Mauna Kea. Le Mauna Loa est le plus haut volcan du monde : il s'élève à dix-sept kilomètres au-dessus de sa base, qui s'enfonce dans le plancher océanique, et la superficie de sa partie émergée, 5 271 km2, représente plus de la moitié de la surface de l'île. Le Mauna Loa, qui est un volcan bouclier caractérisé par des laves fluides pauvres en silice, a été créé par un point chaud à l'origine de la formation de l'archipel des Îles Hawaï."],"src":"https://fr.wikipedia.org/wiki/Mauna_Loa","sw":"w","q":"Q159762","pays":["US"],"c":["amerique-nord"]},"mayon":{"n":"Mayon","t":"volcan","alt":2462,"bref":["Le Mayon est un volcan actif des Philippines, sur l'île de Luçon, dans la province d'Albay, entre les villes de Legazpi au sud-est, Tabaco au nord-est et Ligao à l'ouest."],"src":"https://fr.wikipedia.org/wiki/Mayon","sw":"w","q":"Q1484","pays":["PH"],"c":["asie"]},"merapi":{"n":"Merapi","t":"volcan","alt":2910,"bref":["Le Merapi, en indonésien et en javanais Gunung Merapi, est un volcan d'Indonésie situé sur l'île de Java, au nord de la ville de Yogyakarta. Il s'élève de près de 2 900 mètres au-dessus des forêts et des champs. Avec 49 éruptions explosives entre 1548 et 2010, il est considéré comme le volcan le plus actif et le plus dangereux d'Indonésie, produisant de périodiques nuées ardentes. Ses éruptions sont habituellement espacées de quatre ou cinq ans, mais de plus importantes peuvent avoir lieu tous les siècles, comme la dernière survenue en octobre-novembre 2010."],"src":"https://fr.wikipedia.org/wiki/Merapi","sw":"w","q":"Q134108","pays":["ID"],"c":["asie"]},"mont-abu":{"n":"Mont Âbû","t":"sommet","alt":1220,"massif":"Ârâvalli","bref":["Mount Âbû est une localité située à l'extrémité de la chaîne des Ârâvalli au Rajasthan, à quelque 100 km à l'ouest d'Udaipur connu comme grand lieu de pèlerinage dans le jaïnisme et en tant que seule station de montagne (hill station) du Rajasthan."],"src":"https://fr.wikipedia.org/wiki/Mount_%C3%82b%C3%BB","sw":"w","q":"Q695221","pays":["IN"],"c":["asie"]},"mont-apo":{"n":"Mont Apo","t":"volcan","alt":2954,"massif":"Apo–Talomo Range","bref":["Le mont Apo est le point culminant des Philippines, avec 2954 mètres de hauteur. C'est un volcan situé sur l'île de Mindanao, à une trentaine de kilomètres de la plus grande ville, Davao.","La première personne qui l’a gravi a été Don Joaquin Rajal, en 1880. Le mont Apo est une destination très touristique car on y monte assez facilement, contrairement aux autres grandes montagnes du pays."],"src":"https://fr.vikidia.org/wiki/Mont_Apo","sw":"v","q":"Q455963","pays":["PH"],"c":["asie"]},"mont-ararat":{"n":"Mont Ararat","t":"volcan","alt":5137,"massif":"haut plateau arménien","bref":["C'est un volcan actif et sa dernière éruption a eu lieu en 1840. Il est situé près des frontières iranienne et arménienne, respectivement à une dizaine et une quarantaine de kilomètres de distance."],"src":"https://fr.vikidia.org/wiki/Mont_Ararat","sw":"v","q":"Q72303","pays":["TR"],"c":["asie","europe"]},"mont-asama":{"n":"Mont Asama","t":"volcan","alt":2568,"bref":["Le mont Asama est un stratovolcan du Japon se trouvant au centre de l’île de Honshū, à environ 140 km de Tokyo. C’est l’un des volcans les plus actifs du Japon. Ses plus violentes éruptions, aux temps historiques, datent de 1108 et 1783. Sa dernière éruption remonte à août 2019."],"src":"https://fr.wikipedia.org/wiki/Mont_Asama","sw":"w","q":"Q242730","pays":["JP"],"c":["asie"]},"mont-athos":{"n":"Mont Athos","t":"sommet","alt":2033,"bref":["Le mont Athos est une péninsule montagneuse située à l'est de la Chalcidique, dans le nord de la Grèce.","Du point de vue administratif, la « Sainte Montagne » constitue un nome de la République de Grèce qui porte le nom de République monastique du mont Athos, formant une communauté théocratique rattachée au Patriarcat œcuménique de Constantinople, disposant d'un statut particulier où les lois sont différentes de celles appliquées sur l'ensemble du territoire grec."],"src":"https://fr.vikidia.org/wiki/Mont_Athos","sw":"v","q":"Q130321","pays":["GR"],"c":["europe"]},"mont-beloukha":{"n":"Mont Béloukha","t":"sommet","alt":4506,"massif":"Monts Katoun","bref":["Le mont Béloukha, situé dans les monts Katoun, est le sommet le plus élevé de l'Altaï à la frontière entre le Kazakhstan et la Russie. Il est également le second plus haut sommet de la Sibérie derrière le Klioutchevskoï (dans le Kamtchatka).","Il fait partie de la liste du patrimoine mondial en tant que montagne d'or de l’Altaï et il se trouve dans le territoire de la réserve naturelle de la Katoun et du parc national Béloukha."],"src":"https://fr.wikipedia.org/wiki/Mont_B%C3%A9loukha","sw":"w","q":"Q724367","pays":["RU"],"c":["asie","europe"]},"mont-berlin":{"n":"Mont Berlin","t":"sommet","alt":3478,"massif":"Flood Range","bref":["Le mont Berlin est un volcan de l'Antarctique, le sixième plus haut de ce continent."],"src":"https://fr.wikipedia.org/wiki/Mont_Berlin","sw":"w","q":"Q645451"},"mont-blanc":{"n":"Mont Blanc","t":"sommet","alt":4806,"massif":"massif du Mont-Blanc","bref":["Le mont Blanc est le point culminant (le sommet le plus haut) des Alpes et de l'Europe de l'Ouest, ainsi que le sixième d'Europe (derrière les sommets du Caucase). Il se situe en France, dans le massif du Mont-Blanc, à 4 808 mètres d'altitude, dans le département de la Haute-Savoie. Il domine au nord la vallée de l'Arve et au sud-est la vallée du Fiume Dora di Veny. Chamonix-Mont-Blanc se trouve à 10 kilomètres au nord du point le plus haut. Ce sommet est le plus isolé d'Eurasie et donc d'Europe. Le mont le plus proche dépassant le mont Blanc en altitude est le Kukurtlu Dome, situé à 2 866 kilomètres dans le Grand Caucase, non loin du mont Elbrouz."],"src":"https://fr.vikidia.org/wiki/Mont_Blanc","sw":"v","q":"Q583","pays":["FR","IT"],"c":["europe"]},"mont-cameroun":{"n":"Mont Cameroun","t":"volcan","alt":4095,"massif":"ligne du Cameroun","bref":["Le mont Cameroun est un volcan du Cameroun, point culminant du pays à 4 040 ou 4 095 mètres d'altitude au Fako, le point le plus élevé du cratère sommital. Il fait partie d'une suite volcanique, la ligne du Cameroun. Il se situe à 68 kilomètres à l'ouest-nord-ouest de Douala."],"src":"https://fr.vikidia.org/wiki/Mont_Cameroun","sw":"v","q":"Q190562","pays":["CM"],"c":["afrique"]},"mont-damavand":{"n":"Mont Damavand","t":"volcan","alt":5610,"massif":"Elbourz","bref":["Le mont Damavand est le point culminant des monts Elbourz (ou Alborz), en Iran. Il se situe dans le Nord de l'Iran, dans la partie orientale de la chaîne et à 68 kilomètres à l'est-nord-est de Téhéran. Il est aussi un volcan éteint."],"src":"https://fr.vikidia.org/wiki/Mont_Damavand","sw":"v","q":"Q40758","pays":["IR"],"c":["asie"]},"mont-dolent":{"n":"Mont Dolent","t":"sommet","alt":3820,"massif":"massif du Mont-Blanc","bref":["Le mont Dolent est un sommet du massif du Mont-Blanc culminant à 3 819 m selon la carte suisse et la carte italienne, et 3 823 m selon la carte française. Pour la France son sommet est le tripoint avec la Suisse et l'Italie. Pour la Suisse et l'Italie, le tripoint est le nœud orographique à 150 m au nord-ouest du sommet, ce dernier étant sur la frontière italo-suisse."],"src":"https://fr.wikipedia.org/wiki/Mont_Dolent","sw":"w","q":"Q665130","pays":["CH","IT","FR"],"c":["europe"]},"mont-du-temple":{"n":"Mont du Temple","t":"sommet","alt":743,"massif":"Jerusalem mountains","bref":["L'Esplanade des Mosquées est un mont situé dans la vieille ville de Jérusalem, représentant un haut lieu saint pour la religion juive et la religion musulmane. En effet, l'esplanade comporte entre autres des infrastructures sacrées pour les juifs, avec l'ancien placement du Temple de Jérusalem (sous l'esplanade), ou encore le Mur des Lamentations, ainsi que pour les musulmans pour lesquels se trouvent le Dôme du Rocher et la Mosquée Al-Aqsa.","Les querelles rituelles entre les juifs et les musulmans, voire des chrétiens, pour l'affirmation du culte de ce lieu saint font de l'Esplanade des Mosquées le théâtre de tensions plus ou moins dangereuses, surtout depuis la fin de la Seconde Guerre Mondiale et le contrôle des Israéliens sur la ville de Jérusalem."],"src":"https://fr.vikidia.org/wiki/Esplanade_des_Mosqu%C3%A9es","sw":"v","q":"Q193163","pays":["PS","IL"],"c":["asie"]},"mont-emei":{"n":"Mont Emei","t":"sommet","alt":3099,"bref":["Le mont Emei ou Omei, ou Emei Shan, est l'une des quatre montagnes sacrées bouddhiques de Chine, située sur le territoire de la ville d'Emeishan dans la province du Sichuan."],"src":"https://fr.wikipedia.org/wiki/Mont_Emei","sw":"w","q":"Q134927","pays":["CN"],"c":["asie"]},"mont-erciyes":{"n":"Mont Erciyes","t":"volcan","alt":3916,"massif":"monts Taurus","bref":["Le mont Erciyes, ou mont Argée (Ardjéh dagh) est un volcan endormi du Miocène, situé à 25 km au sud de Kayseri, en Turquie.","Le mont Erciyes est le point culminant d'Anatolie centrale (3 916 mètres). Il appartient à la région volcanique qui s'étend au nord du Taurus cilicien et à l’ouest de l’Anti-Taurus."],"src":"https://fr.wikipedia.org/wiki/Mont_Erciyes","sw":"w","q":"Q126804","pays":["TR"],"c":["asie","europe"]},"mont-erebus":{"n":"Mont Erebus","t":"volcan","alt":3794,"massif":"chaîne Transantarctique","bref":["Le mont Erebus est un volcan d'Antarctique. Situé sur l'île de Ross, il est le plus austral des volcans actifs du monde. Proche du continent, l'île de Ross appartient à l'océan Pacifique Sud et se trouve à 3 485 kilomètres au sud de l'île du Sud, en Nouvelle-Zélande."],"src":"https://fr.vikidia.org/wiki/Mont_Erebus","sw":"v","q":"Q188982"},"mont-fuji":{"n":"Mont Fuji","t":"volcan","alt":3777,"bref":["Le mont Fuji, est un volcan japonais de type stratovolcan. C'est la montagne la plus haute du Japon avec une altitude de 3 776 m. Ses pentes sud descendent jusqu’aux rivages de la mer dans la baie de Suruga. Sa dernière éruption date de l'an 1707. Son activité a augmenté ces dernières années, une éruption serait catastrophique car la région est très peuplée (avec Tokyo 40 millions d'habitants). Un séisme pourrait réveiller ce volcan très dangereux, comme en 1707 selon certains, dans le Japon qui a subi plein de séismes et catastrophes, Typhons, inondations, tsunamis Raz-de-marée."],"src":"https://fr.vikidia.org/wiki/Mont_Fuji","sw":"v","q":"Q39231","pays":["JP"],"c":["asie"]},"mont-hermon":{"n":"Mont Hermon","t":"sommet","alt":2814,"massif":"Anti-Liban","bref":["Le mont Hermon est une montagne de l'Anti-Liban, culminant à 2 814 mètres d'altitude. Le sommet se situe à la frontière entre la Syrie et le Liban. L'extrémité méridionale de la montagne fait partie du plateau du Golan, occupé, colonisé et annexé par Israël depuis la guerre des Six Jours en 1967, sans reconnaissance de la majorité de la communauté internationale. Depuis le 8 décembre 2024, le versant sud du mont Hermon jusqu'à son sommet, alors situé dans une zone démilitarisée, est occupé par l'armée israélienne."],"src":"https://fr.wikipedia.org/wiki/Mont_Hermon","sw":"w","q":"Q215471"},"mont-hood":{"n":"Mont Hood","t":"volcan","alt":3425,"massif":"Oregon Cascades","bref":["Le mont Hood est un stratovolcan situé dans le nord de l’État américain de l'Oregon. La montagne est localisée à environ 100 km à l’est de Portland. Ses pics couverts de neige marquent la frontière entre les comtés de Clackamas et de Hood River. C’est le plus haut sommet de l’Oregon et le quatrième de la chaîne des Cascades. On peut voir facilement la montagne depuis Portland et Vancouver, ville de l'État de Washington. La montagne se trouve dans la forêt nationale du même nom."],"src":"https://fr.wikipedia.org/wiki/Mont_Hood","sw":"w","q":"Q275662","pays":["US"],"c":["amerique-nord"]},"mont-kailash":{"n":"Mont Kailash","t":"sommet","alt":6638,"massif":"Kailas","bref":["Le mont Kailash, également appelé en tibétain Gang Rinpoché et dans le jaïnisme aṣṭapāda, est une montagne culminant à 6 638 mètres d'altitude et faisant partie de la chaîne de Gangdise ou Transhimalaya. Elle est située dans la préfecture de Ngari, dans la région autonome du Tibet, à proximité du lac Manasarovar et du lac Rakshastal. Quatre des plus grands cours d'eau d'Asie, l'Indus, le Sutlej, le Brahmapoutre et la Karnali prennent leur source à proximité du mont Kailash.","Cette montagne est sacrée dans quatre religions : pour les hindous, elle est la demeure de Shiva ; pour les bouddhistes tibétains, celle de Chenresig, le bodhisattva de la compassion dont le dalaï-lama est une des personifications ; quant au fondateur du jaïnisme, c’est à son sommet qu’il a reçu l’illumination ; le culte bön, pré-bouddhisme chamanique, la considère comme le symbole de l’âme. Elle correspondrait peut-être au mythique mont Mérou considéré comme l'axe du monde dans les mythologies persane, bouddhique, jaïne et surtout hindoue. La circumambulation autour du mont Kailash (kora), longue de 51 km, est l’un des pèlerinages les plus importants d'Asie."],"src":"https://fr.wikipedia.org/wiki/Mont_Kailash","sw":"w","q":"Q229107","pays":["CN"],"c":["asie"]},"mont-kazbek":{"n":"Mont Kazbek","t":"volcan","alt":5033,"massif":"Grand Caucase","bref":["Le mont Kazbek est un sommet et volcan endormi culminant à 5 047 mètres d'altitude en Géorgie, près de la frontière avec la Russie. C'est la cinquième plus haute montagne du Caucase et la deuxième de Géorgie après le mont Chkhara. Il est couvert de glaciers et son ascension ne présente que des difficultés moyennes. Il a été gravi pour la première fois le 1er juillet 1868 par Douglas William Freshfield, Adolphus Warburton Moore et Charles Comyns Tucker."],"src":"https://fr.wikipedia.org/wiki/Mont_Kazbek","sw":"w","q":"Q207680","pays":["RU"],"c":["asie","europe"]},"mont-kenya":{"n":"Mont Kenya","t":"sommet","alt":5199,"massif":"Kilimanjaro","bref":["Le mont Kenya est un volcan éteint situé en Afrique. Il a donné son nom au Kenya, le pays dans lequel il est situé. Avec une altitude maximale de 5 199 mètres à la pointe Batian, il s'agit du deuxième sommet d'Afrique par l'altitude après le mont Kibo, dans le massif du Kilimandjaro.","Les différentes ethnies qui vivent dans le massif l'appellent Kirinyaga dans le cas des Kikuyus, Kirenia dans le cas des Embus ou Ol Donyo Eibor dans le cas des Masaïs. Ces différentes dénominations signifient montagne blanche. En effet, le sommet se caractérise par la présence de petits glaciers et la persistance de neige au sommet n'est pas rare."],"src":"https://fr.vikidia.org/wiki/Mont_Kenya","sw":"v","q":"Q172070","pays":["KE"],"c":["afrique"]},"mont-kinabalu":{"n":"Mont Kinabalu","t":"sommet","alt":4095,"massif":"Banjaran Crocker","bref":["Le mont Kinabalu, en malais gunung Kinabalu, est le point culminant de l'île de Bornéo et de la Malaisie. Cette montagne appartient au Banjaran Crocker, un massif du Nord de Bornéo, à la pointe nord-est de l'État malaisien de Sabah. L'altitude du Kinabalu est de 4 095 mètres. Ce sommet est le plus èlevé de l'archipel malais. Il est aussi par l'altitude le troisième sommet insulaire du monde, après le Puncak Jaya (Indonésie) et le Mauna Kea (Hawaï, États-Unis). C'est donc un sommet qui compte beaucoup dans la géographie de l'Asie du Sud-Est."],"src":"https://fr.vikidia.org/wiki/Mont_Kinabalu","sw":"v","q":"Q60967","pays":["MY"],"c":["asie"]},"mont-kirkpatrick":{"n":"Mont Kirkpatrick","t":"sommet","alt":4528,"massif":"Monts de la Reine-Alexandra","bref":["Le mont Kirkpatrick est le point culminant du chaînon de la Reine-Alexandra, en Antarctique. Situé à 8 kilomètres à l'ouest du mont Dickerson, le mont Kirkpatrick est le point culminant de la chaîne Transantarctique. Découvert et nommé par l'expédition Nimrod en 1908-1909, la montagne doit son nom à un homme d'affaires de Glasgow, qui était l'un des sponsors de l'expédition."],"src":"https://fr.wikipedia.org/wiki/Mont_Kirkpatrick","sw":"w","q":"Q1929197"},"mont-kosciuszko":{"n":"Mont Kosciuszko","t":"sommet","alt":2228,"massif":"Snowy Mountains","bref":["Le mont Kosciuszko est le point culminant du sous-continent australien avec 2 228 mètres d'altitude, ce qui lui vaut, non sans controverses, d'être classé sur la liste de Bass des sept sommets et en fait la montagne la plus aisée à gravir parmi ceux-ci. Le sommet fut officiellement vaincu en 1840 par l'explorateur polonais Paweł Edmund Strzelecki qui en profita pour le nommer en l'honneur de son compatriote Tadeusz Kościuszko. En raison de l'exploitation de la montagne par les bergers, puis du développement touristique et enfin des travaux d'aménagement hydrographique, le milieu naturel, caractérisé par une flore alpine unique en Australie, est fragilisé. La zone est protégée en 1944 puis classée officiellement au sein du parc national du Kosciuszko en 1967."],"src":"https://fr.wikipedia.org/wiki/Mont_Kosciuszko","sw":"w","q":"Q178167","pays":["AU"],"c":["oceanie"]},"mont-logan":{"n":"Mont Logan","t":"sommet","alt":5959,"massif":"chaîne Saint-Élie","bref":["Le mont Logan est un sommet d'Amérique du Nord situé dans la chaîne Saint-Élie, au Canada. La montagne s'élève à 5 959 mètres d'altitude."],"src":"https://fr.vikidia.org/wiki/Mont_Logan","sw":"v","q":"Q120306","pays":["CA"],"c":["amerique-nord"]},"mont-olympe":{"n":"Mont Olympe","t":"sommet","alt":2918,"bref":["Le mont Olympe est une montagne de Grèce située au nord de la Thessalie. C'est la plus haute du pays : elle culmine à 2 917 m."],"src":"https://fr.vikidia.org/wiki/Mont_Olympe","sw":"v","q":"Q80344","pays":["GR"],"c":["europe"]},"mont-orohena":{"n":"Mont Orohena","t":"sommet","alt":2241,"bref":["Le mont Orohena est un sommet français situé en Polynésie française sur Tahiti-Nui, la partie nord-ouest de l'île de Tahiti. Il culmine à 2 241 mètres d'altitude. C'est un ancien volcan dont l'origine remonte à environ 500 000 ans. La montagne est composée majoritairement d'ignimbrites, une roche formée par des débris de lave acide.","Le mont Orohena ne se situe pas exactement au centre de l'île. Le sommet est légérement décalé vers le nord et la ville côtière la plus proche est le village de Mahina, situé sur la côte septentrionale de Tahiti-Nui."],"src":"https://fr.vikidia.org/wiki/Mont_Orohena","sw":"v","q":"Q512465","pays":["FR"],"c":["europe"]},"mont-paektu":{"n":"Mont Paektu","t":"volcan","alt":2744,"massif":"Massif du Paektu","bref":["Le mont Paektu ou mont Changbai est la montagne la plus haute de Corée, située à la fois en Corée du Nord et en Chine. Elle culmine à 2 744 mètres d'altitude. Il s'agit d'un volcan gris dont l'éruption de 946 a été l'une des plus violentes de l'histoire.","Les Coréens et les Mandchous la considèrent comme une montagne sacrée. Les hymnes nationaux de la Corée du Nord (Aegukka) et de la Corée du Sud (Aegukga) la mentionnent. Le mont Paektu est représenté sur l'emblème de la Corée du Nord. Selon la légende coréenne, Dangun, le fondateur du premier royaume coréen Gojoseon, serait né sur le mont Paektu."],"src":"https://fr.vikidia.org/wiki/Mont_Paektu","sw":"v","q":"Q107635","pays":["KP","CN"],"c":["asie"]},"mont-parnasse":{"n":"Mont Parnasse","t":"sommet","alt":2455,"massif":"Pinde","bref":["Le mont Parnasse est une montagne du centre de la Grèce, qui surplombe la cité de Delphes, à proximité d'Aráchova. Particulièrement vénéré dans l'Antiquité, il était consacré à la fois au dieu Apollon et aux neuf Muses, dont il était l'une des deux résidences avec le mont Hélicon. Il fait partie des dix parcs nationaux de Grèce. Le Parnasse accueille le principal domaine skiable de Grèce."],"src":"https://fr.wikipedia.org/wiki/Mont_Parnasse","sw":"w","q":"Q105261","pays":["GR"],"c":["europe"]},"mont-rainier":{"n":"Mont Rainier","t":"volcan","alt":4389,"massif":"chaîne des Cascades","bref":["Le mont Rainier, en anglais Mount Rainier, est un volcan actif des États-Unis situé dans l'État de Washington, dans la région du Puget Sound et appartenant à l'arc volcanique des Hautes Cascades. Son altitude de 4 392 mètres lui permet d'être le point culminant de la chaîne des Cascades et de l'État de Washington. Ses coordonnées géographiques sont : 46° 51′ 08″ N 121° 45′ 37″ W / 46.852313, -121.760318."],"src":"https://fr.vikidia.org/wiki/Mont_Rainier","sw":"v","q":"Q194057","pays":["US"],"c":["amerique-nord"]},"mont-roraima":{"n":"Mont Roraima","t":"sommet","alt":2810,"massif":"Sierra de Pacaraima","bref":["Le mont Roraima est une montagne d'Amérique du Sud partagée entre le Brésil, le Guyana et le Venezuela. Il s'agit d'un tepuy, une montagne tabulaire caractéristique du plateau des Guyanes. Délimité par des falaises d'environ 1 000 mètres de hauteur, son plateau sommital présente un environnement totalement différent de la forêt tropicale humide et de la savane qui s'étendent à ses pieds. Ainsi, la forte pluviométrie est à l'origine de formations pseudokarstiques, dont de nombreuses et grandes grottes, ainsi que du lessivage du sol."],"src":"https://fr.wikipedia.org/wiki/Mont_Roraima","sw":"w","q":"Q4777","pays":["VE","BR","GY"],"c":["amerique-sud"]},"mont-ruapehu":{"n":"Mont Ruapehu","t":"volcan","alt":2797,"massif":"massif du Tongariro","bref":["Le mont Ruapehu, ou simplement Ruapehu, est un volcan actif de Nouvelle-Zélande inclus dans le parc national de Tongariro et situé dans le centre de l'île du Nord dont il est le point culminant avec 2 797 mètres d'altitude. La montagne comporte les seuls glaciers et les plus grandes pistes de ski de l'île du Nord. Le climat alpin qui règne au sommet de la montagne permet le maintien de neiges éternelles et de petits glaciers autour du lac de cratère."],"src":"https://fr.wikipedia.org/wiki/Mont_Ruapehu","sw":"w","q":"Q207284","pays":["NZ"],"c":["oceanie"]},"mont-saint-helens":{"n":"Mont Saint Helens","t":"volcan","alt":2549,"massif":"chaîne des Cascades","bref":["Le mont Saint Helens est un volcan explosif actif situé dans l'État de Washington, au Nord-Ouest des États-Unis, à 150 kilomètres au sud de la ville de Seattle (Washington) et à 80 kilomètres au nord-est de la ville de Portland (Oregon).","Le mont Saint Helens n'a pas été nommé en l'honneur de sainte Hélène, mais en hommage à un diplomate anglais portant le titre de Lord St Helens. Ami de l'explorateur George Vancouver, il explora cette zone à la fin du XVIIIe siècle."],"src":"https://fr.vikidia.org/wiki/Mont_Saint_Helens","sw":"v","q":"Q4675","pays":["US"],"c":["amerique-nord"]},"mont-sidley":{"n":"Mont Sidley","t":"sommet","alt":4181,"massif":"Chaîne du Comité Exécutif","bref":["Le mont Sidley, en anglais Mount Sidley, est le plus haut volcan de l'Antarctique avec 4 181 ou 4 285 mètres d'altitude, ce qui l'inclut dans la liste des sept sommets volcaniques. Il est situé dans l'ouest de l'Antarctique, dans la terre Marie Byrd, et il comporte une caldeira en forme de fer à cheval de cinq kilomètres de largeur. Il reste très méconnu hormis des volcanologues."],"src":"https://fr.wikipedia.org/wiki/Mont_Sidley","sw":"w","q":"Q924312"},"mont-sinai":{"n":"Mont Sinaï","t":"sommet","alt":2287,"massif":"Sinai mountain range","bref":["Le mont Sinaï (ou Djebel Moussa, \"la Montagne de Moïse \") est un mont d’Égypte, haut de plus de 2 200 mètres.","Dans la tradition biblique, le mont Sinaï est le lieu où Moïse a reçu les 10 commandements."],"src":"https://fr.vikidia.org/wiki/Mont_Sina%C3%AF","sw":"v","q":"Q377485","pays":["EG"],"c":["afrique"]},"mont-tai":{"n":"Mont Tai","t":"sommet","alt":1545,"bref":["Le mont Tai ou Taishan, se situe au nord de la ville de Tai'an, dans la province du Shandong en république populaire de Chine. Son point culminant, le pic de l'Empereur de jade, a une altitude de 1 545 m. Il est particulièrement important par son histoire et sa signification culturelle, car c'est l'une des cinq montagnes sacrées de la Chine. C'est le Mont de l'Est, associé à l'aurore, à la naissance et au renouveau, et la plus vénérée des cinq montagnes sacrées. Les temples qui y sont perchés sont une destination de choix pour les pèlerins depuis 3 000 ans. C'est le théâtre d'un pèlerinage unique : l'ascension nocturne vers le pic sacré de l'Empereur de jade."],"src":"https://fr.wikipedia.org/wiki/Mont_Tai","sw":"w","q":"Q216059","pays":["CN"],"c":["asie"]},"mont-taranaki":{"n":"Mont Taranaki","t":"volcan","alt":2518,"bref":["Le Taranaki Maunga, jusqu'en 2025 mont Taranaki ou mont Egmont, en anglais Mount Taranaki ou Mount Egmont, est une montagne de Nouvelle-Zélande située dans le Sud-Ouest de l'île du Nord, au cœur du parc national d'Egmont. Volcan au repos culminant à 2 518 mètres d'altitude, sa forme conique aux pentes régulières et prononcées est considérée comme une des plus symétriques au monde."],"src":"https://fr.wikipedia.org/wiki/Taranaki_Maunga","sw":"w","q":"Q850051","pays":["NZ"],"c":["oceanie"]},"mont-terror":{"n":"Mont Terror","t":"volcan","alt":3230,"massif":"chaîne Transantarctique","bref":["Le mont Terror est une montagne de l'île de Ross en Antarctique, volcan bouclier désormais éteint et voisin du mont Erebus toujours actif."],"src":"https://fr.wikipedia.org/wiki/Mont_Terror","sw":"w","q":"Q1056741"},"mont-titano":{"n":"Mont Titano","t":"sommet","alt":756,"massif":"Apennines of Rimini","bref":["Le mont Titano ou mont Titan (en italien : Monte Titano) est un relief montagneux des Apennins qui s'élève à 739 m.","C'est la montagne principale de la république de Saint-Marin. Il en constitue souvent le symbole, du fait de sa grande extension par rapport aux dimensions modestes de l'État. Ses trois principaux sommets portent chacun d'eux les trois châteaux (ou tours) qui assurèrent la défense de la Ville de Saint-Marin : Guaita, Cesta et Montale (que l'on retrouve stylisés sur les armoiries de la république)."],"src":"https://fr.wikipedia.org/wiki/Mont_Titano","sw":"w","q":"Q158526","pays":["SM"],"c":["europe"]},"mont-tyree":{"n":"Mont Tyree","t":"sommet","alt":4852,"massif":"massif Sentinel","bref":["Le mont Tyree est un sommet culminant à 4 852 mètres d'altitude en Antarctique, ce qui en fait le deuxième plus haut du continent après le massif Vinson situé à moins de dix kilomètres. Il fait partie du massif Sentinel des monts Ellsworth, à la base de la péninsule Antarctique. Découvert en 1958, il est gravi pour la première fois en 1967 et seules cinq expéditions sont parvenues à son sommet en date de 2013. Son ascension est l'une des plus difficiles au monde."],"src":"https://fr.wikipedia.org/wiki/Mont_Tyree","sw":"w","q":"Q1950776"},"mont-ventoux":{"n":"Mont Ventoux","t":"sommet","alt":1910,"massif":"monts de Vaucluse","bref":["Le mont Ventoux est une montagne culminant à 1 909 m en Provence, France. Vénérée par les Celtes qui la considéraient comme sacrée, la montagne devient populaire au-delà de la région après avoir été escaladée et décrite par Pétrarque en 1336. De nos jours, elle est accessible par une route de montagne qui est d'une grande importance pour les cyclistes. Le mont Ventoux est surnommé le Géant de Provence."],"src":"https://fr.vikidia.org/wiki/Mont_Ventoux","sw":"v","q":"Q209064","pays":["FR"],"c":["europe"]},"mont-whitney":{"n":"Mont Whitney","t":"sommet","alt":4421,"massif":"sierra Nevada","bref":["Le mont Whitney est le point culminant de la sierra Nevada, des chaînes côtières du Pacifique, de la Californie et des États-Unis, sans l'Alaska. En effet seul cet État détient des sommets plus hauts. Ce mont californien a une altitude de 4 419 mètres. Son isolement topographique est aussi considérable : il s'élève à 2 649 kilomètres. Cette distance correspond à l'éloignement du plus proche sommet dépassant le mont Whitney en altitude, soit le pico de Aguila (4 620 mètres), situé au Mexique, dans la cordillère Néovolcanique. Enfin, la proéminence du mont est de 3 072 mètres, ce qui classe le mont Whitney septième des États-Unis pour cette spécialité. Le nom du sommet rend hommage au géologue Josiah Dwight Whitney."],"src":"https://fr.vikidia.org/wiki/Mont_Whitney","sw":"v","q":"Q235539","pays":["US"],"c":["amerique-nord"]},"montagne-de-la-table":{"n":"Montagne de la Table","t":"sommet","alt":1085,"bref":["La montagne de la Table (en afrikaans : Tafelberg, en anglais : Table Mountain) est un massif de la province du Cap-Occidental en Afrique du Sud, qui surplombe la ville du Cap.","Elle fait partie des sept nouvelles merveilles de la nature."],"src":"https://fr.wikipedia.org/wiki/Montagne_de_la_Table","sw":"w","q":"Q213360","pays":["ZA"],"c":["afrique"]},"montagne-pelee":{"n":"Montagne Pelée","t":"volcan","alt":1397,"bref":["La montagne Pelée est un volcan gris qui se situe à l'extrême nord de la Martinique. La montagne Pelée culmine à 1 397 m d’altitude. Elle a une superficie de 120 km².","C'est un stratovolcan. Un stratovolcan est un édifice volcanique formé d'un empilement de coulées de laves et de dépôts pyroclastiques résultant de multiples éruptions à partir d'un évent central ou d'évents proches). Ces volcans forment généralement des cônes pentus et peuvent être éventrés plusieurs fois au cours de leur période d'activité par la formation d'explosions ou d'avalanches."],"src":"https://fr.vikidia.org/wiki/Montagne_Pel%C3%A9e","sw":"v","q":"Q76309","pays":["FR"],"c":["europe"]},"montagnes-rocheuses":{"n":"Montagnes Rocheuses","t":"massif","alt":4401,"massif":"cordillère nord-américaine","bref":["Les montagnes Rocheuses ou simplement les Rocheuses sont une chaîne de montagnes d'Amérique du Nord, située aux Canada et aux États-Unis. Orientées nord-ouest/sud-est, elles s'étendent sur environ 3 400 km de long et leur largeur atteint à son maximum 640 km."],"src":"https://fr.vikidia.org/wiki/Montagnes_Rocheuses","sw":"v","q":"Q5463","pays":["CA","US"],"c":["amerique-nord"]},"monts-huang":{"n":"Monts Huang","t":"massif","alt":1864,"bref":["Les monts Huang, ou Huangshan ou monts Jaunes sont un massif montagneux de l'Anhui méridional, province de l'est de la Chine. La région est connue pour sa beauté, qui repose sur la forme des pics de granite, sur celle tourmentée des conifères, et sur les nuages qui entourent fréquemment le massif. Cette montagne mythique change sans cesse de visage au gré des vents et des bruines... désespérant parfois les artistes qui désirent en fixer la beauté. La région abrite également des sources d'eau chaude, et des sources minérales qui alimentent des piscines naturelles. Ces montagnes sont un sujet privilégié pour la peinture et la littérature chinoises traditionnelles."],"src":"https://fr.wikipedia.org/wiki/Monts_Huang","sw":"w","q":"Q36034","pays":["CN"],"c":["asie"]},"monts-saian":{"n":"Monts Saïan","t":"massif","alt":3492,"bref":["Les monts Saïan, ou massif des Saïan (russe : Saïany ; en mongol : (Soyonï nurû) ; en vieux-turc : (Kögmen)), sont une chaîne de montagnes s'étendant en Sibérie méridionale entre les sujets de Khakassie, de Krasnoïarsk, de Touva, d'Irkoutsk et de Bouriatie en Russie et l'aïmag de Khövsgöl en Mongolie. Elle consiste en deux parties, avec le Saïan oriental du Baïkal au Ienisseï sur plus de 1 000 km, et le Saïan occidental jusqu'au massif de l'Altaï sur près de 500 km. Le Mounkou Sardyk, dans le Saïan oriental, constitue le point culminant de la chaîne avec 3 491 mètres d'altitude, tandis que le Kyzyl Taïga à 3 121 mètres est le point culminant du Saïan oriental."],"src":"https://fr.wikipedia.org/wiki/Monts_Sa%C3%AFan","sw":"w","q":"Q203239","pays":["RU"],"c":["asie","europe"]},"monts-taurus":{"n":"Monts Taurus","t":"massif","alt":3756,"bref":["Les monts Taurus, ou simplement les Taurus (en turc : Toroslar), sont une chaîne de montagnes de Turquie, formant la bordure sud-est du plateau de l'Anatolie et culminant à 3 756 m au Demirkazık."],"src":"https://fr.wikipedia.org/wiki/Monts_Taurus","sw":"w","q":"Q172556","pays":["TR"],"c":["asie","europe"]},"moussala":{"n":"Moussala","t":"sommet","alt":2925,"massif":"Rila","bref":["Le mont Moussala est un ensemble de sommets des Balkans (dont il constitue le point culminant), dans le massif du Rila. Il culmine à 2 925 mètres d'altitude."],"src":"https://fr.wikipedia.org/wiki/Moussala_(montagne)","sw":"w","q":"Q209341","pays":["BG"],"c":["europe"]},"nanda-devi":{"n":"Nanda Devi","t":"sommet","alt":7816,"massif":"Himalaya","bref":["La Nanda Devi, signifiant « déesse de la Félicité » (de devi, « déesse », et nanda, « joie »), est la plus haute montagne complètement contenue dans le territoire indien. C'est aussi le plus haut sommet de la chaîne du Garhwal. Il est protégé dans un parc national."],"src":"https://fr.wikipedia.org/wiki/Nanda_Devi","sw":"w","q":"Q213262","pays":["IN"],"c":["asie"]},"nanga-parbat":{"n":"Nanga Parbat","t":"sommet","alt":8126,"massif":"Himalaya","bref":["Le Nanga Parbat est un sommet de l'Himalaya situé au Pakistan, dans la province du Gilgit-Batistan. Il fait partie de l'Himalaya du Pendjab dont il est le point culminant. Le sommet ne se trouve qu'à vingt-cinq kilomètres au sud-est de la vallée de l'Indus."],"src":"https://fr.vikidia.org/wiki/Nanga_Parbat","sw":"v","q":"Q130736","pays":["PK"],"c":["asie"]},"nemrut-dag":{"n":"Nemrut Dağı","t":"sommet","alt":2150,"massif":"monts Taurus","bref":["Le mont Nemrut (en turc : Nemrut Dağı) est une montagne de l'Est de la Turquie, en Anatolie. Elle domine la vallée de l'Euphrate, dans une région très isolée, au nord de la ville d'Urfa.","La montagne porte à son sommet, à 2 150 m, un sanctuaire antique, composé d'un tumulus et de monuments cultuels, constituant le mausolée d'Antiochos Ier, roi de Commagène, issu d'une dynastie arménienne, qui a régné sur la région aux environs de 69 à 40 av. J.-C."],"src":"https://fr.vikidia.org/wiki/Mont_Nemrut","sw":"v","q":"Q207917","pays":["TR"],"c":["asie","europe"]},"nevado-coropuna":{"n":"Nevado Coropuna","t":"volcan","alt":6425,"massif":"Cordillera Ampato","bref":["Le Nevado Coropuna est un stratovolcan du Pérou. Il se trouve dans la province de Condesuyos, au sein de la région d'Arequipa, dans le Sud du pays, et fait partie de la zone volcanique centrale des Andes. Il culmine à 6 377 mètres et est couronné par une calotte glaciaire qui descend jusqu'à 5 200 mètres d'altitude."],"src":"https://fr.wikipedia.org/wiki/Nevado_Coropuna","sw":"w","q":"Q946035","pays":["PE"],"c":["amerique-sud"]},"nevado-del-ruiz":{"n":"Nevado del Ruiz","t":"volcan","alt":5389,"massif":"Cordillère Centrale","bref":["Le Nevado del Ruiz est un volcan actif situé en Colombie, près de la ville de Manizales, dans les Andes. Son sommet se situe à 5 321 mètres d'altitude.","C'est un volcan de type explosif, l'éruption la plus meurtrière a eu lieu en 1985. Sa dernière éruption commencée le 28 novembre 2014 est toujours en cours."],"src":"https://fr.vikidia.org/wiki/Nevado_del_Ruiz","sw":"v","q":"Q233351","pays":["CO"],"c":["amerique-sud"]},"nevado-ojos-del-salado":{"n":"Nevado Ojos del Salado","t":"sommet","alt":6893,"massif":"cordillère des Andes","bref":["Le Nevado Ojos del Salado (ce qui signifie les yeux du salé) est un volcan situé dans la cordillère des Andes. Il culmine à 6 893 mètres d'altitude.","La montagne fut vaincue pour la première fois le 26 février 1937 par deux Polonais, Justin Tymon Wojsznis et Jan Alfred Szczepanski."],"src":"https://fr.vikidia.org/wiki/Nevado_Ojos_del_Salado","sw":"v","q":"Q233836","pays":["CL","AR"],"c":["amerique-sud"]},"newtontoppen":{"n":"Newtontoppen","t":"sommet","alt":1713,"bref":["Le Newtontoppen, du norvégien signifiant en français « pic Newton », est une montagne de Norvège, constituant le point culminant du massif de Chydeniusfjella, du Svalbard et de Spitzberg, sa plus grande île, avec 1 713 mètres d'altitude."],"src":"https://fr.wikipedia.org/wiki/Newtontoppen","sw":"w","q":"Q1419222","pays":["NO"],"c":["europe"]},"nowshak":{"n":"Nowshak","t":"sommet","alt":7492,"massif":"Hindou Kouch","bref":["Le Nowshak, ou Noshaq, culminant à 7 492 m d'altitude, est une montagne entre l'Afghanistan, dont il est le point culminant, et le Pakistan, ainsi que le deuxième plus haut sommet de l’Hindou Kouch après le Tirich Mir (7 690 m)."],"src":"https://fr.wikipedia.org/wiki/Nowshak","sw":"w","q":"Q271700","pays":["AF","PK"],"c":["asie"]},"nyamuragira":{"n":"Nyamuragira","t":"volcan","alt":3058,"massif":"Montagnes des Virunga","bref":["Le Nyamuragira, également appelé Girungo-Namlagira, Namlagira, Nyamlagira ou Nyamulagira, est un volcan de la république démocratique du Congo. Volcan le plus actif d'Afrique, il est capable de produire des coulées de lave de plus de trente kilomètres de longueur qui atteignent ainsi le lac Kivu situé au sud."],"src":"https://fr.wikipedia.org/wiki/Nyamuragira","sw":"w","q":"Q695846","pays":["CD"],"c":["afrique"]},"nyiragongo":{"n":"Nyiragongo","t":"volcan","alt":3470,"massif":"Montagnes des Virunga","bref":["Le Nyiragongo est un volcan d'Afrique situé en république démocratique du Congo, non loin de la frontière séparant le pays du Rwanda et à 168 kilomètres au sud de la ligne équatoriale. Il se trouve sur la branche occidentale de la vallée du Grand Rift, au nord de la ville de Goma, elle-même construite sur la rive nord du lac Kivu."],"src":"https://fr.vikidia.org/wiki/Nyiragongo","sw":"v","q":"Q214696","pays":["CD"],"c":["afrique"]},"oural-q35600":{"n":"Oural (montagnes)","t":"massif","alt":1895,"bref":["L'Oural est une chaîne de montagnes en Russie. Elle se développe sur 2 300 km, de la mer de Kara au fleuve Oural, qui marque la limite sud de la chaîne. La largeur de la chaîne varie de 96 kilomètres dans le nord à seulement 32 dans le Sud. On dit traditionnellement que cette chaîne est la limite entre l'Europe et l'Asie. C'est vrai. Mais il faut préciser comment les choses se sont déroulées.","En réalité, c'est le tsar Pierre le Grand qui est à l'origine de cette démarcation. Au sud de la chaîne, les monts Mughalzar sont une extension de l'Oural au Kazakhstan. Bien que distincts des monts Oural, ils appartiennent à la ceinture orogénique ouralienne (ou système ouralien). Au nord, la chaîne est prolongée par les crêtes Pay Khoy, faisant elles aussi partie de la ceinture ouralienne."],"src":"https://fr.vikidia.org/wiki/Oural","sw":"v","q":"Q35600","pays":["RU"],"c":["asie","europe"]},"pamir":{"n":"Pamir","t":"massif","alt":7649,"bref":["Le Pamir est un ensemble de massifs de haute montagne situé en Asie centrale, plus précisément dans le centre et l’Est du Tadjikistan et qui se prolonge en Afghanistan à l’ouest-sud-ouest, au Kirghizistan au nord et en Chine au nord-est."],"src":"https://fr.vikidia.org/wiki/Pamir","sw":"v","q":"Q161750","pays":["KG","TJ","CN","AF","IN","PK"],"c":["asie"]},"paricutin":{"n":"Paricutín","t":"volcan","alt":2800,"massif":"Cordillère néovolcanique","bref":["Le Paricutín est un volcan du Mexique situé dans l'État du Michoacán. Il est né le 20 février 1943 au cours d'une éruption qui a duré neuf ans, ce qui en fait un des volcans les plus jeunes de la Terre avec Surtsey né en 1963 et l'Ardoukôba en 1978. Il se présente sous la forme d'un cône volcanique aux pentes escarpées culminant à 3 170 mètres d'altitude, dominant des coulées de lave d'où émerge le clocher de l'ancien village de San Juan Parangaricutiro."],"src":"https://fr.wikipedia.org/wiki/Paricut%C3%ADn","sw":"w","q":"Q231620","pays":["MX"],"c":["amerique-nord"]},"petit-caucase":{"n":"Petit Caucase","t":"massif","alt":4090,"massif":"Caucase","bref":["Le Petit Caucase, ou Caucase mineur, est une des deux chaînes de montagnes du Caucase, longue de près de 600 km. La chaîne montagneuse du Petit Caucase s'étend du sud-est au nord-ouest, au sud de la chaîne du Grand Caucase et marque la limite du haut-plateau arménien.","Le Petit Caucase est relié au Grand Caucase par la chaîne de montagnes de Sourami (ou Likhi), et en est séparé par le pays de Colchide à l'ouest et la vallée du fleuve Koura à l'est. Vers l'ouest, en Turquie, le Petit Caucase trouve son prolongement dans la chaîne pontique qui longe la côte sud de la mer Noire."],"src":"https://fr.wikipedia.org/wiki/Petit_Caucase","sw":"w","q":"Q216593","pays":["GE","AM","AZ"],"c":["europe","asie"]},"pic-d-adam":{"n":"Pic d'Adam","t":"sommet","alt":2243,"massif":"Massif Central","bref":["Le pic d'Adam (en singhalais : (Sri Pada) : « noble pied », ou (Samanala-kanda) : « pic de Saman (en) » ; en tamoul : (Sivanolipatha Malai) : « montagne des lumineux pieds de Shiva », ou (Baavaa Aadaam Malai) : « montagne du Père Adam » parmi les maures srilankais ; en arabe : (Al-Rohun ou Al-Rahun) : « l'âme ») est un des sommets les plus importants de l'île du Sri Lanka. Conique et haut de 2 243 m, il est considéré comme un lieu saint par les hindous et les bouddhistes srilankais, qui en ont fait un lieu de pèlerinage, ainsi que par les musulmans."],"src":"https://fr.wikipedia.org/wiki/Pic_d'Adam","sw":"w","q":"Q60789","pays":["LK"],"c":["asie"]},"pic-d-orizaba":{"n":"Pic d'Orizaba","t":"sommet","alt":5636,"massif":"Cordillère néovolcanique","bref":["Le pic d'Orizaba (en espagnol pico de Orizaba) est le plus haut sommet du Mexique. Il est accessoirement connu sous le nom nahuatl de Citlaltepetl (montagne de l'étoile), couramment employé lors de l'arrivée des Espagnols au Mexique. Il se situe à 99 kilomètres à l'est de Puebla, dans l'État de Puebla, et s'élève au-dessus de la sierra Madre orientale."],"src":"https://fr.vikidia.org/wiki/Pic_d'Orizaba","sw":"v","q":"Q238147","pays":["MX"],"c":["amerique-nord"]},"pic-du-canigou":{"n":"Pic du Canigou","t":"sommet","alt":2784,"massif":"massif du Canigou","bref":["Le pic du Canigou ou pic du Canigó (catalan : Pica del Canigó) est le haut sommet le plus oriental des Pyrénées, culminant à 2 785 mètres d'altitude. Il fait partie du massif du Canigou, dont il est le point culminant, et il est situé dans le Conflent, dans le département français des Pyrénées-Orientales."],"src":"https://fr.wikipedia.org/wiki/Pic_du_Canigou","sw":"w","q":"Q6650","pays":["FR"],"c":["europe"]},"pic-ismail-samani":{"n":"Pic Ismail Samani","t":"sommet","alt":7495,"massif":"chaînon de l'Académie des Sciences","bref":["Le pic Ismail Samani, anciennement pic Staline puis pic du Communisme, est le point culminant du Tadjikistan et de l'ancienne Union soviétique. Il s'élève à 7 495 mètres d'altitude dans le massif du Pamir. Gravi pour la première fois en 1933 par Evgeny Abalakov, il est devenu un sommet très fréquenté par les alpinistes."],"src":"https://fr.wikipedia.org/wiki/Pic_Ismail_Samani","sw":"w","q":"Q41413","pays":["TJ"],"c":["asie"]},"pic-mawson":{"n":"Pic Mawson","t":"volcan","alt":2745,"massif":"Big Ben","bref":["Le pic Mawson, en anglais Mawson Peak, est un volcan d'Australie situé sur l'île Heard, dans le territoire extérieur des îles Heard-et-MacDonald situé dans le Sud de l'océan Indien. Culminant à 2 745 mètres d'altitude, il est le point culminant du territoire australien devant le mont Kosciuszko qui s'élève à 2 228 mètres d'altitude."],"src":"https://fr.wikipedia.org/wiki/Pic_Mawson","sw":"w","q":"Q2114101","pays":["AU"],"c":["oceanie"]},"pico-do-fogo":{"n":"Pico do Fogo","t":"volcan","alt":2829,"bref":["Le Pico do Fogo est un stratovolcan situé sur l'île de Fogo, au Cap-Vert, point culminant du pays avec 2 829 m d'altitude. Il est également le plus haut sommet d'Afrique de l'Ouest et le second de Macaronésie après le Teide. Volcan actif, il est entré en éruption pour la dernière fois entre le 23 novembre 2014 et le 8 février 2015."],"src":"https://fr.wikipedia.org/wiki/Pico_do_Fogo","sw":"w","q":"Q499108","pays":["CV"],"c":["afrique"]},"pinatubo":{"n":"Pinatubo","t":"volcan","alt":1486,"massif":"Monts Zambales","bref":["Le Pinatubo est un stratovolcan actif situé dans l'ouest de l'île de Luçon aux Philippines, à 100 km au nord-ouest de Manille."],"src":"https://fr.vikidia.org/wiki/Pinatubo","sw":"v","q":"Q1451","pays":["PH"],"c":["asie"]},"piton-de-la-fournaise":{"n":"Piton de la Fournaise","t":"volcan","alt":2621,"massif":"massif du Piton de la Fournaise","bref":["Le piton de la Fournaise est un volcan situé sur l'île de la Réunion, dans l'océan Indien, à 736 km à l'est de Madagascar. Il occupe presque un tiers de l'île. Le piton de la Fournaise est âgé de 530 000 ans. Environ 58 éruptions ont été recensées depuis 1931 et au moins 153 depuis l'an 1640. Elles ont duré chacune de 8 à 15 jours.","La première ascension du piton a été réalisée en 1751 par Andoche Dolnet de Palmaroux. Il a une altitude de 2631 m. Il est actif : il est entré en éruption plusieurs fois en 2017, 2018 et 2019."],"src":"https://fr.vikidia.org/wiki/Piton_de_la_Fournaise","sw":"v","q":"Q1049644","pays":["FR"],"c":["europe"]},"piton-des-neiges":{"n":"Piton des Neiges","t":"volcan","alt":3070,"massif":"massif du Piton des Neiges","bref":["Le piton des Neiges est un volcan bouclier endormi situé sur l'île de La Réunion, île française de l'océan Indien. Le volcan se dresse à 3 070 mètres au dessus du niveau de la mer, ce qui en fait le point culminant de cette île mais également de l'archipel des Mascareignes et de toutes les îles de l'océan Indien. Ce sommet fait de La Réunion la deuxième île d'Afrique par l'altitude, classement qui s'étend aux îles de la dorsale centre-atlantique. Seule l'île de Tenerife est plus haute (Îles Canaries, Espagne)."],"src":"https://fr.vikidia.org/wiki/Piton_des_Neiges","sw":"v","q":"Q1545452","pays":["FR"],"c":["europe"]},"plateaux-d-ethiopie":{"n":"Plateaux d'Éthiopie","t":"massif","alt":4550,"bref":["Les hauts plateaux abyssins, également appelés hauts plateaux éthiopiens ou trapps d'Éthiopie, forment une région montagneuse accidentée de la Corne de l'Afrique. Principalement situés en Éthiopie, ils s'étendent également partiellement en Érythrée et en Somalie (Somaliland).","Ces plateaux sont formés d'une série de trapps mis en place il y a trente millions d'années par épanchement fissural d'un magma mantellique, liée à la remontée d'un point chaud. Ces dépôts volcaniques massifs, qui ont probablement eu lieu en moins d'un million d'années, se sont accumulées sur 2 500 m d'épaisseur. Ils encadrent le graben de la vallée du Grand Rift et notamment la dépression de l'Afar ; ils se prolongent au nord par l'Itbay qui longe la rive occidentale de la mer Rouge."],"src":"https://fr.wikipedia.org/wiki/Hauts_plateaux_abyssins","sw":"w","q":"Q319288","pays":["ET"],"c":["afrique"]},"poas":{"n":"Poás","t":"volcan","alt":2708,"massif":"cordillère Centrale","bref":["Le Poás est un stratovolcan du Costa Rica. Très actif, il a connu au moins 39 épisodes éruptifs depuis 1828. Il connaît actuellement une activité moyenne (fumerolles, éruptions phréatiques). Situé à 37 km au nord-ouest de la capitale San José, ce volcan culmine à 2 708 m d'altitude. Il est intégré dans le parc national du volcan Poás (Parque Nacional Volcán Poás). Son cratère principal dégage régulièrement des vapeurs sulfurées toxiques et héberge un lac acide qui peut disparaître en fonction de son activité."],"src":"https://fr.wikipedia.org/wiki/Po%C3%A1s","sw":"w","q":"Q1969482","pays":["CR"],"c":["amerique-nord"]},"popocatepetl":{"n":"Popocatepetl","t":"volcan","alt":5452,"massif":"Cordillère néovolcanique","bref":["Le Popocatepetl est un volcan de type explosif situé au Mexique, près de Puebla, à 70 km de Mexico. Le mot Popocatepetl est un terme nahuatl qui signifie « montagne qui fume ».","Il culmine dans la cordillère Néovolcanique entre 5 393 et 5 413 mètres d'altitude selon les sources, ce qui fait de lui le second sommet du pays, après le pic d'Orizaba, qui est un autre volcan."],"src":"https://fr.vikidia.org/wiki/Popocatepetl","sw":"v","q":"Q181157","pays":["MX"],"c":["amerique-nord"]},"puncak-jaya":{"n":"Puncak Jaya","t":"sommet","alt":4884,"massif":"chaîne de Sudirman","bref":["Le Puncak Jaya ou pyramide Carstensz est une montagne d'Indonésie située sur l'île de Nouvelle-Guinée, dans la province de Papouasie centrale. Ses 4 884 mètres d'altitude font de cette montagne le point culminant de l'Indonésie et de l'Océanie — ce qui l'inscrit dans la catégorie des sept sommets — et place la Nouvelle-Guinée en première position dans le classement des îles par altitude.","Découverte par le Néerlandais Jan Carstenszoon en 1623, la montagne n'est approchée qu'au début du XXe siècle et n'est gravie qu'en 1962 en raison de sa relative inaccessibilité. La présence du Puncak Jaya dans la liste des sept sommets attire cependant de nombreux alpinistes désireux de gravir les points culminants des sept continents. Le Puncak Jaya et les sommets voisins sont un des rares endroits à présenter des glaciers sous des latitudes équatoriales. Ces quelques glaciers, dont le glacier Carstensz, qui s'étend sur la face orientale du Puncak Jaya, sont les restes d'une calotte glaciaire beaucoup plus importante, qui a commencé à régresser à la fin de la dernière période glaciaire, il y a 12 000 ans."],"src":"https://fr.wikipedia.org/wiki/Puncak_Jaya","sw":"w","q":"Q1045888","pays":["ID"],"c":["asie"]},"puy-de-dome":{"n":"Puy de Dôme","t":"volcan","alt":1465,"massif":"chaîne des Puys","bref":["Le puy de Dôme est un volcan d'Auvergne. Son altitude est de 1 465 mètres. C'est un volcan explosif endormi, dont la seule et unique éruption a eu lieu il y a 12 000 ans.","On peut accéder en navette à son sommet d'où la vue est splendide, car on voit toute la chaîne des Puys."],"src":"https://fr.vikidia.org/wiki/Puy_de_D%C3%B4me","sw":"v","q":"Q607372","pays":["FR"],"c":["europe"]},"puy-de-sancy":{"n":"Puy de Sancy","t":"volcan","alt":1885,"massif":"Monts Dore","bref":["Le puy de Sancy est un volcan éteint situé en Auvergne dans le département du Puy-de-Dôme, non loin de celui du Cantal. C'est le plus haut sommet du Massif central, il culmine à 1 886 mètres. Il se trouve à 35 km au sud-ouest de Clermont-Ferrand."],"src":"https://fr.vikidia.org/wiki/Puy_de_Sancy","sw":"v","q":"Q778597","pays":["FR"],"c":["europe"]},"pyrenees":{"n":"Pyrénées","t":"massif","alt":3404,"bref":["Les Pyrénées sont une chaîne de montagnes du sud-ouest de l'Europe, séparant la France et l'Espagne et abritant l'Andorre.","De direction est-ouest, elles s'étendent à peu près sur 430 km d'est en ouest, du golfe de Gascogne (Atlantique) au golfe du Lion (Méditerranée), et sur 60 à 140 km du nord au sud, entre la Gascogne et le bassin de l'Èbre. Leur point culminant est le pic d’Aneto, en Espagne (3 404 m)."],"src":"https://fr.vikidia.org/wiki/Pyr%C3%A9n%C3%A9es","sw":"v","q":"Q12431","pays":["ES","FR","AD"],"c":["europe"]},"rhodopes":{"n":"Rhodopes","t":"massif","alt":2191,"bref":["Les Rhodopes sont un massif montagneux des Balkans, situé dans le Sud-Ouest de la Bulgarie ne débordant qu'en Macédoine-Orientale-et-Thrace, dans le Nord-Est de la Grèce. Avec les massifs du Rila et du Pirin, il forme un même ensemble montagneux. Son plus haut sommet, le Goljam Perelik (2 191 m), est le septième sommet de Bulgarie par son altitude. Les Rhodopes sont le massif le plus étendu de Bulgarie et occupent environ un septième de la surface totale du pays, de 220 à 240 km d’ouest en est et 100 km environ du nord au sud. Sur une surface totale de 14 571 km2, 83 % des Rhodopes se trouvent sur le territoire bulgare, le reste en territoire grec. Les importantes réserves d'eau et la douceur du climat favorisent une grande variété végétale et animale."],"src":"https://fr.wikipedia.org/wiki/Rhodopes","sw":"w","q":"Q6489","pays":["GR","BG"],"c":["europe"]},"rysy":{"n":"Rysy","t":"sommet","alt":2501,"massif":"Hautes Tatras","bref":["Le Rysy est un sommet de la chaîne des Hautes Tatras, dans l'arc extérieur des Carpates occidentales, sur la frontière entre la Pologne et la Slovaquie. Il culmine à 2 500 mètres d'altitude en Slovaquie. Sur son versant septentrional, à 2 499,1 mètres d'altitude, se trouve le point culminant de la Pologne.","La montagne est le point le plus élevé des Hautes Tatras accessible aux randonneurs par des sentiers balisés sans guide de haute montagne. Un refuge, le Chata pod Rysmi, situé 250 mètres plus bas que le sommet est à leur disposition. Depuis le début du XXe siècle, de nombreuses personnalités en ont fait l'ascension comme les époux Pierre et Marie Curie ou Lénine, dont l'ascension n'est pas prouvée mais fut largement exploitée par le pouvoir communiste dans le cadre d'une rencontre internationale pour la jeunesse."],"src":"https://fr.wikipedia.org/wiki/Rysy","sw":"w","q":"Q672936","pays":["SK","PL"],"c":["europe"]},"sakurajima":{"n":"Sakurajima","t":"volcan","alt":1117,"bref":["Le Sakurajima est un édifice volcanique situé au Japon, sur l'île de Kyūshū.","Plus localement, il se trouve dans le Nord de la baie de Kagoshima, en mer de Chine orientale."],"src":"https://fr.vikidia.org/wiki/Sakurajima","sw":"v","q":"Q128841","pays":["JP"],"c":["asie"]},"semeru":{"n":"Semeru","t":"volcan","alt":3676,"massif":"Caldeira Tengger","bref":["Le Semeru, ou gunung Semeru en indonésien, est un volcan d'Indonésie situé dans la province de Java-Oriental, dans l'Est de l'île de Java."],"src":"https://fr.vikidia.org/wiki/Semeru","sw":"v","q":"Q270158","pays":["ID"],"c":["asie"]},"shishapangma":{"n":"Shishapangma","t":"sommet","alt":8027,"massif":"Jugal Himal","bref":["Le Shishapangma ou Shisha Pangma, aussi appelé Gosainthan en sanskrit, est une montagne de Chine culminant à 8 027 mètres d'altitude dans la ville-préfecture de Shigatsé, au sein de la région autonome du Tibet. Il est situé dans la chaîne de l'Himalaya et constitue le quatorzième sommet le plus élevé au monde et le dernier des « 8 000 ». Il est gravi pour la première fois par une expédition chinoise en 1964, alors que les frontières du pays étaient fermées aux étrangers. La voie normale emprunte les versants nord de la montagne et présente relativement peu de difficultés."],"src":"https://fr.wikipedia.org/wiki/Shishapangma","sw":"w","q":"Q105124","pays":["CN"],"c":["asie"]},"sierra-nevada-q26955":{"n":"Sierra Nevada (Espagne)","t":"massif","alt":3478,"bref":["La sierra Nevada, qui signifie \"chaîne enneigée\" en espagnol, est une chaîne de montagnes faisant partie du système pénibétique de la région espagnole d'Andalousie. C'est la chaîne de montagnes ayant la plus haute altitude dans toute l'Europe occidentale, à l'ouest des Alpes. Elle contient le point culminant de l'Espagne continentale, le Mulhacén, à 3 479 m. En 1986, elle a été déclarée réserve de biosphère par l'UNESCO et en 1999, une grande partie de son territoire a été déclarée parc national pour ses valeurs botaniques, paysagères et naturelles.","C'est une destination touristique populaire, car ses hauts sommets permettent de skier dans la station de ski la plus méridionale d'Europe, dans une zone située le long de la mer Méditerranée, connue principalement pour ses températures chaudes et son soleil abondant. À ses pieds se trouve la ville de Grenade et, un peu plus loin, Malaga et Almería."],"src":"https://fr.vikidia.org/wiki/Sierra_Nevada_(Espagne)","sw":"v","q":"Q26955","pays":["ES"],"c":["europe"]},"sierra-nevada":{"n":"Sierra Nevada (États-Unis)","t":"massif","alt":4421,"massif":"cordillère nord-américaine","bref":["La sierra Nevada (« la montagne enneigée » en espagnol) est une chaîne de montagnes située dans l'Est de la Californie, aux États-Unis."],"src":"https://fr.vikidia.org/wiki/Sierra_Nevada_(%C3%89tats-Unis)","sw":"v","q":"Q26777","pays":["US"],"c":["amerique-nord"]},"sinabung":{"n":"Sinabung","t":"volcan","alt":2460,"massif":"Bukit Barisan","bref":["Le Sinabung, en indonésien Gunung Sinabung, est un stratovolcan culminant à 2 460 mètres d’altitude sur l’île de Sumatra en Indonésie."],"src":"https://fr.wikipedia.org/wiki/Sinabung","sw":"w","q":"Q207678","pays":["ID"],"c":["asie"]},"sn-fellsjokull":{"n":"Snæfellsjökull","t":"volcan","alt":1446,"bref":["Le Snæfellsjökull est un stratovolcan d'Islande surmonté d'une calotte glaciaire qui culmine à 1 446 mètres d'altitude. Il est situé à l'extrémité occidentale de la péninsule de Snæfellsnes."],"src":"https://fr.wikipedia.org/wiki/Sn%C3%A6fellsj%C3%B6kull","sw":"w","q":"Q1315012","pays":["IS"],"c":["europe"]},"sniejka":{"n":"Sniejka","t":"sommet","alt":1603,"massif":"monts des Géants","bref":["Sniejka (« la neigeuse », en tchèque : Sněžka ; en polonais : Śnieżka ; en allemand : Schneekoppe) est la plus haute montagne des monts des Géants. Elle est traversée en son sommet par la frontière entre la Pologne et la Tchéquie. On peut y accéder par un télésiège depuis la ville tchèque de Pec pod Sněžkou. Le point culminant se situe à 1 602 ou 1 603 mètres d'altitude ; c'est aussi le point culminant de la Tchéquie. Le sommet a une superficie plane importante, ce qui a permis d'y construire plusieurs bâtiments. La température annuelle moyenne y est de 0,2 °C. Sniejka est le point de départ ou le but de nombreux chemins de randonnée pédestre (dont le chemin de l'Amitié tchéco-polonaise), cyclistes et de ski de fond."],"src":"https://fr.wikipedia.org/wiki/Sniejka","sw":"w","q":"Q617511","pays":["CZ","PL"],"c":["europe"]},"sudetes":{"n":"Sudètes","t":"massif","massif":"Massif de Bohême","bref":["Les Sudètes (en allemand : Sudeten ; en tchèque et en polonais : Sudety ; nom complet dans la littérature tchèque : Krkonošsko-jesenická subprovincie) sont une chaîne de montagnes d'Europe centrale, qui représente la partie nord-est du large massif de Bohême. S'étendant du massif gréseux de l'Elbe à la porte de Moravie, les Sudètes sont à cheval sur l'Allemagne à l'ouest, la Pologne au nord et la Tchéquie au sud, et forment la frontière entre ces deux derniers pays.","Moyennes montagnes, elles culminent à 1 603 mètres d'altitude au mont Sniejka, sur la frontière polono-tchèque. Elles comprennent plusieurs massifs, dont les monts des Géants et le Hrubý Jeseník, qui forment la zone frontalière entre les régions historiques de la Bohême, la Moravie, la Silésie et la Haute-Lusace."],"src":"https://fr.wikipedia.org/wiki/Sud%C3%A8tes_(montagne)","sw":"w","q":"Q152131","pays":["CZ","PL","DE"],"c":["europe"]},"tajumulco":{"n":"Tajumulco","t":"volcan","alt":4203,"massif":"Sierra Madre de Chiapas","bref":["Le Tajumulco est un stratovolcan situé dans le Sud-Ouest du Guatemala, à soixante-cinq kilomètres de l'océan Pacifique."],"src":"https://fr.vikidia.org/wiki/Tajumulco","sw":"v","q":"Q818467","pays":["GT"],"c":["amerique-nord"]},"tambora":{"n":"Tambora","t":"volcan","alt":2850,"bref":["Le Tambora, en indonésien Gunung Tambora, est un stratovolcan actif qui forme la péninsule de Sanggar de l'île de Sumbawa, dans l'archipel des Petites îles de la Sonde, en Indonésie. Il culmine à 2 850 m d'altitude, mais, avant l'éruption de 1815 qui a formé une caldeira de près de 6 km de diamètre et 1 110 m de profondeur, il s'élevait à une altitude d'environ 4 300 m. Le volcan se situe à 340 kilomètres au nord de la fosse de la Sonde, une des zones sismiques les plus actives de la planète, et constitue un des éléments de la chaîne volcanique de la Sonde, qui compte des dizaines de volcans actifs tels que le Krakatoa. Le Tambora est âgé d'environ 50 000 ans."],"src":"https://fr.wikipedia.org/wiki/Tambora","sw":"w","q":"Q168714","pays":["ID"],"c":["asie"]},"tassili-n-ajjer":{"n":"Tassili n'Ajjer","t":"massif","alt":2158,"bref":["Le tassili n’Ajjer est un massif de montagnes situé au centre du Sahara, dans le Sud-Est de l'Algérie et dont la frange orientale se trouve en territoire libyen."],"src":"https://fr.wikipedia.org/wiki/Tassili_n'Ajjer","sw":"w","q":"Q190048","pays":["DZ"],"c":["afrique"]},"tatras":{"n":"Tatras","t":"massif","alt":2654,"massif":"Fatra-Tatra Area","bref":["Les Tatras sont une chaîne de montagnes à cheval sur la frontière entre la Pologne et la Slovaquie. Il s'agit de la partie la plus élevée de la chaîne des Carpates et dont le point culminant est le Gerlachovský štít (ou pic Gerlach), à 2 654 mètres d'altitude, en Slovaquie. Elles font plus précisément partie des Carpates occidentales.","La réserve de biosphère des Tatras a été reconnue par l'Unesco en 1993. Elle est transfrontière entre la Slovaquie et la Pologne."],"src":"https://fr.wikipedia.org/wiki/Tatras","sw":"w","q":"Q194263","pays":["SK","PL"],"c":["europe"]},"teide":{"n":"Teide","t":"volcan","alt":3715,"bref":["Le Teide encore appelé pic de Teide, anciennement pic de Tenerife, est le point culminant de Tenerife et de l'Espagne. C'est un volcan d'environ 3 718 mètres d'altitude.","Il possède des coulées de lave très fluides et son activité d'éruption est très active. Par sa taille, il est le troisième volcan au monde."],"src":"https://fr.vikidia.org/wiki/Teide","sw":"v","q":"Q38954","pays":["ES"],"c":["europe"]},"tian-shan":{"n":"Tian Shan","t":"massif","alt":7439,"bref":["Le Tian Shan (montagnes célestes) est un système montagneux situé en Asie centrale et se répartissant en Ouzbekistan, au Tadjikistan, au Kirghizistan, au Kazakhstan et en Chine. Il s'étend sur 2 500 kilomètres de longueur selon une direction ouest-sud-ouest / est-nord-est. La chaîne est large de 500 kilomètres aux extrémités et de 350 kilomètres au centre. Il existe dans ces montagnes 15 953 glaciers occupant une surface de 15 416 kilomètres carrés."],"src":"https://fr.vikidia.org/wiki/Tian_Shan","sw":"v","q":"Q5474","pays":["KG","KZ","CN","UZ"],"c":["asie","europe"]},"tibet":{"n":"Tibet","t":"sommet","alt":4380,"bref":["Le Tibet, ou anciennement Thibet, est une région de plateau située au nord de l'Himalaya en Asie, habitée traditionnellement par les Tibétains et d'autres groupes ethniques (Monbas, Qiang et Lhobas) et comportant également une population importante de Hans et de Huis. Le Tibet est le plateau habité le plus élevé de la planète, avec une altitude moyenne de 4 900 m."],"src":"https://fr.wikipedia.org/wiki/Tibet","sw":"w","q":"Q17252","pays":["CN"],"c":["asie"]},"tirich-mir":{"n":"Tirich Mir","t":"sommet","alt":7708,"massif":"Hindou Kouch","bref":["Le Tirich Mir est un sommet du Pakistan s'élevant à 7 708 mètres d'altitude dans la province de Khyber Pakhtunkhwa et constituant le point culminant de l'Hindou Kouch. Il est entouré de glaciers. Des alpinistes norvégiens ont réalisé les premières ascensions de la cime principale et de la cime orientale, la deuxième par l'altitude, respectivement en 1950 et en 1964."],"src":"https://fr.wikipedia.org/wiki/Tirich_Mir","sw":"w","q":"Q207132","pays":["PK"],"c":["asie"]},"triglav":{"n":"Triglav","t":"sommet","alt":2864,"massif":"Triglav Group","bref":["Il est un des symboles du pays, c'est-à-dire qu'il évoque la Slovénie par lui-même. En effet, on retrouve le Triglav dessiné sur le blason et le drapeau slovène ainsi que sur la pièce de 0.50 euro (autrement dit la pièce de 50 centimes) depuis que la Slovénie a adopté l'euro comme monnaie nationale. Le nom de Triglav (Trois Têtes) fait référence à la forme que prend le sommet qui est visible à plus de 100 km, notamment dans le land de Carinthie, en Autriche."],"src":"https://fr.vikidia.org/wiki/Triglav","sw":"v","q":"Q1024","pays":["SI"],"c":["europe"]},"tungurahua":{"n":"Tungurahua","t":"volcan","alt":5016,"massif":"Cordillère Orientale","bref":["Le Tungurahua est un stratovolcan équatorien en activité de 5 023 mètres d'altitude, situé à cheval entre les provinces de Chimborazo et Tungurahua. En éruption depuis le 5 octobre 1999, son activité éruptive a repris le 28 mai 2010 et connaît à partir du 26 avril 2011 une nouvelle phase explosive."],"src":"https://fr.wikipedia.org/wiki/Tungurahua","sw":"w","q":"Q207421","pays":["EC"],"c":["amerique-sud"]},"uluru":{"n":"Uluru","t":"sommet","alt":863,"bref":["Uluru/Ayers Rock est un inselberg en grès situé dans le Territoire du Nord, au centre de l'île principale de l'Australie. Il s'élève à 348 mètres au-dessus de la plaine et est situé à 335 kilomètres au sud-ouest d'Alice Springs. Exploré et gravi par les Européens pour la première fois par William Gosse et Edwin S. Berry (en) en 1873, il a été nommé en l'honneur de Henry Ayers, Premier ministre et secrétaire en chef de l'Australie-Méridionale entre 1863 et 1877.","Il est sacré pour le peuple aborigène de la région, les Pitjantjatjaras, qui font partie des Anangus. Le site abrite des points d'eau, des grottes et des peintures rupestres. Il est classé sur la liste du patrimoine mondial de l'UNESCO au travers du parc national d'Uluṟu-Kata Tjuṯa dont il est, avec les Kata Tjuṯa/monts Olga, l'une des formations emblématiques."],"src":"https://fr.wikipedia.org/wiki/Uluru%2FAyers_Rock","sw":"w","q":"Q33910","pays":["AU"],"c":["oceanie"]},"vesuve":{"n":"Vésuve","t":"volcan","alt":1281,"massif":"Somma-Vesuvius complex","bref":["Le Vésuve est un volcan italien situé en Campanie, à quinze kilomètres à l'est de Naples, et qui culmine à 1 281 mètres.","C'est l'un des grands volcans encore en activité de nos jours. Ses émanations peuvent se propager à plus de 35 km alentour. Sa dernière éruption importante remonte à mars 1944."],"src":"https://fr.vikidia.org/wiki/V%C3%A9suve","sw":"v","q":"Q524","pays":["IT"],"c":["europe"]},"vignemale":{"n":"Vignemale","t":"sommet","alt":3299,"massif":"massif du Vignemale","bref":["Le Vignemale, plus précisément la pique Longue, est un sommet des Pyrénées, situé à la frontière franco-espagnole, dans le massif du Vignemale. Il est, avec ses 3 298 m (ou 3 299 m selon des cartes espagnoles), le point culminant des Pyrénées françaises, des Hautes-Pyrénées, de la région Occitanie et de l'ancienne province de Gascogne. C'est aussi le 11e plus haut sommet de toute la chaîne des Pyrénées selon la liste officielle des 212 pics à plus de 3 000 mètres pyrénéens.","En bordure du parc national des Pyrénées, et de la reserva de la Biosfera Ordesa-Viñamala, il est accessible depuis Gavarnie, Cauterets ou Torla-Ordesa. Une partie de l'itinéraire d'accès côté français emprunte le GR 10. La voie d'accès la plus facile et évidente traverse une grande partie du glacier d'Ossoue (ou glacier de Baysselance), depuis les grottes de Bellevue sur le GR 10 jusqu'à la base de la pique Longue, où il faut alors finir l'ascension avec un peu d'escalade facile. Le Vignemale est l'un des sommets mythiques des Pyrénées. En aragonais, il est appelé pico de Comachibosa et en espagnol pico Viñamala."],"src":"https://fr.wikipedia.org/wiki/Vignemale","sw":"w","q":"Q1348903","pays":["ES","FR"],"c":["europe"]},"volcan-de-agua":{"n":"Volcán de Agua","t":"volcan","alt":3760,"massif":"Sierra Madre de Chiapas","bref":["Le Volcán de Agua est un stratovolcan du Guatemala inactif depuis environ 10 000 ans. Au XVIe siècle une importante coulée de boue se produit et détruit une cité entière. Ses flancs fertiles sont propices à l'agriculture et sont largement cultivés."],"src":"https://fr.wikipedia.org/wiki/Volc%C3%A1n_de_Agua","sw":"w","q":"Q1327687","pays":["GT"],"c":["amerique-nord"]},"volcan-de-fuego":{"n":"Volcán de Fuego","t":"volcan","alt":3765,"massif":"Sierra Madre de Chiapas","bref":["Le Volcán de Fuego (toponyme espagnol signifiant littéralement « volcan de feu » en français) est un volcan du Guatemala."],"src":"https://fr.wikipedia.org/wiki/Volc%C3%A1n_de_Fuego","sw":"w","q":"Q859376","pays":["GT"],"c":["amerique-nord"]},"zagros":{"n":"Zagros","t":"massif","alt":4409,"bref":["Les monts Zagros forment la plus longue chaîne de montagnes d'Iran. Ils prennent naissance entre Bandar Khamir et Bandar Abbas, sur le détroit d'Ormuz (golfe Persique). Ils s'étendent sur environ 1 540 km du nord du détroit jusqu'au Cheekha Dar, point culminant de l'Irak et proche du lac salé Orumieh (Iran). Au-delà débutent les monts Hakkiari, qui se poursuivent jusqu'à la frontière turque où ils constituent une charnière avec le Sud du haut plateau arménien. Côté iranien s'étend la province de l'Azerbaïdjan occidental. La chaîne forme la limite sud-ouest du plateau iranien."],"src":"https://fr.vikidia.org/wiki/Monts_Zagros","sw":"v","q":"Q167021","pays":["IR","IQ","TR"],"c":["asie","europe"]},"zugspitze":{"n":"Zugspitze","t":"sommet","alt":2962,"massif":"Wetterstein","bref":["La Zugspitze, qui signifie en allemand le « pic des traînées de neige » (laissées par les avalanches), est le point culminant de l'Allemagne (2 962 m). Situé à l'extrême sud de la Bavière, dans les Alpes, ce sommet fait partie du Wetterstein, un massif calcaire germano-autrichien."],"src":"https://fr.vikidia.org/wiki/Zugspitze","sw":"v","q":"Q3375","pays":["DE","AT"],"c":["europe"]}},
"iles":{"antigua-et-barbuda":{"n":"Antigua-et-Barbuda","t":"île","km2":440,"pop":101489,"bref":["Antigua-et-Barbuda (en anglais : Antigua and Barbuda) est un État des Petites Antilles, situé à l'est de la mer des Caraïbes et au nord de la Guadeloupe, au sein des îles Sous-le-Vent. Il est formé de deux îles habitées, Antigua (280 km2) et Barbuda (161 km2), et d'un îlot rocheux, Redonda (1,6 km2).","Antigua-et-Barbuda est membre du Commonwealth. La capitale est Saint John's, la langue officielle l'anglais et les habitants les Antiguais et Barbudiens."],"src":"https://fr.vikidia.org/wiki/Antigua-et-Barbuda","sw":"v","q":"Q781"},"aruba":{"n":"Aruba","t":"île","km2":193,"pop":106739,"bref":["Aruba est une île située dans la mer des Caraïbes, qui fait partie des Petites Antilles. Sa capitale est Oranjestad.","Jusqu'en 1986, Aruba faisait partie des Antilles néerlandaises. Depuis cette date, c'est un État à part entière du royaume des Pays-Bas. À la tête de son gouvernement, se trouvent le roi des Pays-Bas (Willem-Alexander des Pays-Bas), fils de Béatrix et le gouverneur Fredis Refunjol."],"src":"https://fr.vikidia.org/wiki/Aruba","sw":"v","q":"Q21203","pays":["AW"],"c":["amerique-nord"]},"bahamas":{"n":"Bahamas","t":"île","km2":13878,"pop":399440,"bref":["Les Bahamas (forme courante), aussi nommés Commonwealth des Bahamas (forme officielle), sont un État formé par un vaste archipel d'environ 700 îles de l'Atlantique Nord, au nord des Antilles. Elles se différencient de ces dernières par leur aspect géologique : récifs corallien face aux volcans actifs des Petites Antilles et aux formations volcano-sédimentaires d'Hispaniola et de Cuba. En tant que récif corallien, l'archipel appartient au monde océanique et non à la plate-forme continentale. Les Bahamas relèvent de la plaque tectonique nord-américaine alors que les Antilles, à l'exception toutefois de Cuba, relèvent de la plaque Caraïbe."],"src":"https://fr.vikidia.org/wiki/Bahamas","sw":"v","q":"Q778","pays":["BS"],"c":["amerique-nord"]},"bahrein":{"n":"Bahreïn","t":"île","km2":787,"pop":1569666,"bref":["Le Bahreïn, aussi nommé Royaume de Bahreïn ou, plus rarement, État de Bahreïn (formes officielles), est un État insulaire situé en Asie, dans le golfe Persique, proche de l'Arabie saoudite et du Qatar. Son nom arabe, Al Baḩrayn, signifie « les deux mers ». Sa capitale est Manama."],"src":"https://fr.vikidia.org/wiki/Bahre%C3%AFn","sw":"v","q":"Q398","pays":["BH"],"c":["asie"]},"barbade":{"n":"Barbade","t":"île","km2":439,"pop":303431,"bref":["La Barbade (nom courant et officiel, en anglais Barbados) est à la fois un État et une île, la plus à l'est des Antilles. Plus précisément, elle fait partie d'un groupe d'îles, les îles du Vent, dans le Sud-Est des Antilles. Sa capitale est Bridgetown et ses 300 000 habitants environ s'appellent les Barbadiens."],"src":"https://fr.vikidia.org/wiki/Barbade","sw":"v","q":"Q244","pays":["BB"],"c":["amerique-nord"]},"borneo":{"n":"Bornéo","t":"île","km2":748168,"pop":18590000,"bref":["Bornéo est une grande île du sud-est asiatique (Insulinde), la quatrième île au monde par sa superficie (736 000 km2), après l'Australie, le Groenland et la Nouvelle-Guinée.","Elle est baignée par la mer de Chine méridionale au nord-ouest et à l'ouest, par la mer de Sulu à l'extrême nord-est, par la mer de Célèbes au nord-est, par le détroit de Makassar à l'est et par la mer de Java au sud."],"src":"https://fr.vikidia.org/wiki/Born%C3%A9o","sw":"v","q":"Q36117","pays":["ID","MY","BN"],"c":["asie"]},"buru":{"n":"Buru","t":"île","km2":8473,"pop":124000,"bref":["Buru (jadis écrit Boeroe) est la troisième plus grande île de l'archipel indonésien des Moluques, avec 9 505 km2. Elle est située en mer de Banda, à 68 km à l'ouest des îles d'Ambon et de Céram, ainsi qu'à 71 km au sud de Sanana, la plus méridionale des îles Sula. Sa rive nord borde la mer de Céram. L'île est montagneuse et couverte de forêts, et possède une étroite plaine côtière. La ville principale est Namlea, qui possède un port et un aéroport militaire. Directement au sud-est se trouve l'île d'Ambelau.","Administrativement, Buru et les îles voisines appartiennent à la province des Moluques (en indonésien Provinsi Maluku) ; elles sont divisées entre le kabupaten de Buru, dont le chef-lieu est Namlea, et le kabupaten de Buru du Sud, dont le chef-lieu est Namrole, la deuxième ville de l'île."],"src":"https://fr.wikipedia.org/wiki/Buru","sw":"w","q":"Q271030","pays":["ID"],"c":["asie"]},"cap-vert":{"n":"Cap-Vert","t":"île","km2":4033,"pop":555988,"bref":["Le Cap-Vert, officiellement Cabo Verde, en forme longue la république du Cap-Vert ou république de Cabo Verde (en portugais : Cabo Verde et República de Cabo Verde), est un État insulaire d'Afrique de l'Ouest, composé d'un archipel de dix îles volcaniques. Situé dans l'océan Atlantique, au large des côtes du Sénégal et de la Mauritanie, il couvre une superficie d'environ 4 000 km2. Praia, la capitale, se trouve à 644 km à l'ouest de la presqu'île du Cap-Vert, au Sénégal. L'archipel se divise en deux séries d'îles : au sud, les îles de Sotavento (Brava, Fogo, São Tiago ou Santiago et Maio) et au nord, les îles de Barlavento (Boa Vista, Sal, São Nicolau, Santa Luzia, São Vicente et Santo Antão)."],"src":"https://fr.wikipedia.org/wiki/Cap-Vert","sw":"w","q":"Q1011","pays":["CV"],"c":["afrique"]},"cayes-du-belize":{"n":"Cayes du Belize","t":"île","km2":963,"bref":["La barrière de corail du Belize (en anglais : Belize Barrier Reef) est un système de récifs coralliens s'étendant le long de la côte du Belize, en Amérique centrale, dans la mer des Caraïbes.","Elle forme le tronçon le plus septentrional du système méso-américain de barrière de corail, et constitue, selon les indicateurs retenus, le plus grand récif barrière de l'hémisphère nord ou le deuxième plus vaste ensemble corallien au monde, après la Grande Barrière de corail australienne."],"src":"https://fr.wikipedia.org/wiki/Barri%C3%A8re_de_corail_du_Belize","sw":"w","q":"Q28361","pays":["BZ"],"c":["amerique-nord"]},"celebes":{"n":"Célèbes","t":"île","km2":174600,"pop":18455058,"bref":["Célèbes est une île majeure d´Indonésie. Elle fait partie des grandes îles de la Sonde, et en est la troisième par la superficie, avec une aire de 189 035 km2 qui la classe aussi onzième île du monde. Elle se situe à 120 kilomètres à l'est-sud-est de Bornéo, à 423 kilomètres au sud de Mindanao, aux Philippines, à 290 kilomètres au nord-nord-ouest de l'île de Florès et à 243 kilomètres à l'ouest d'Halmahera.."],"src":"https://fr.vikidia.org/wiki/C%C3%A9l%C3%A8bes","sw":"v","q":"Q3812","pays":["ID"],"c":["asie"]},"ceram":{"n":"Céram","t":"île","km2":70370,"pop":218993,"bref":["Céram, en indonésien Seram ou Pulau Seram, est une île d'Indonésie située dans l'archipel des Moluques en mer de Banda. C'est la plus grande et principale île de la province des Moluques en Indonésie. Elle est située juste au nord de la petite île d’Ambon et de quelques autres îles voisines, telles que Saparua, Haruku et les îles Banda."],"src":"https://fr.wikipedia.org/wiki/C%C3%A9ram","sw":"w","q":"Q185532","pays":["ID"],"c":["asie"]},"chypre-du-nord":{"n":"Chypre du Nord","t":"île","km2":3355,"pop":489308,"bref":["La Chypre du Nord (forme longue : République turque de Chypre du Nord) est un État situé dans la partie nord de Chypre, une île située à l'est de la mer Méditerranée. Elle est étendue sur 3 355 km² et est peuplée de 270 000 habitants.","Sa capitale est Nicosie. Avec la Turquie, elle utilise comme monnaie la Livre turque (TRY), alors que la République de Chypre utilise l'Euro depuis 2008. Sa langue officielle est également le turc."],"src":"https://fr.vikidia.org/wiki/Chypre_du_Nord","sw":"v","q":"Q23681"},"comores":{"n":"Comores","t":"île","km2":2034,"pop":902348,"bref":["Les Comores, en forme longue l'union des Comores (en comorien : Komori et Udzima wa Komori, en arabe : (Juzur al Qamar) et (al-Ittiḥād al-Qamariyy)), sont un État indépendant d'Afrique australe composé de trois îles situées dans le nord du canal du Mozambique, un espace maritime de l'océan Indien.","Le pays a pour capitale Moroni, pour langues officielles le comorien (shikomori), parlé par 96,9 % de la population, le français et l'arabe, et pour monnaie le franc comorien."],"src":"https://fr.wikipedia.org/wiki/Comores_(pays)","sw":"w","q":"Q970","pays":["KM"],"c":["afrique"]},"crete":{"n":"Crète","t":"île","km2":8336,"pop":623065,"bref":["La Crète, historiquement également appelée Candie (en latin, italien et vénitien: Candia), est la plus grande et la plus peuplée des îles de Grèce, et la cinquième plus grande île de la mer Méditerranée. Située à environ 100 km au sud du Péloponnèse et 300 km au sud-ouest de l'Anatolie, elle s'étend sur 8 450 km2 et son littoral de 1 046 km de long borde la mer Égée et sépare la mer de Crète, au nord, de la mer de Libye, au sud. Très allongée d'ouest en est (260 km) mais beaucoup plus étroite du nord au sud, elle s'étend sur trois unités de longitude différentes mais seulement sur une demi-latitude.","Avec toutes les petites îles et îlots qui l'entourent, elle forme la périphérie de Crète, la plus méridionale des treize régions grecques et la cinquième plus peuplée. Sa capitale et plus grande ville est Héraklion, située sur la côte nord de l'île. Selon le recensement de la population de 2021, la périphérie comptait 624 408 habitants. Les régions voisines, de l'autre côté de la mer de Crète, sont le Dodécanèse au nord-est, les Cyclades au nord et le Péloponnèse au nord-ouest."],"src":"https://fr.wikipedia.org/wiki/Cr%C3%A8te","sw":"w","q":"Q34374","pays":["GR"],"c":["europe"]},"cuba":{"n":"Cuba","t":"île","km2":109884,"pop":10985974,"bref":["Cuba est un pays formé d'une grande île des Antilles, située entre les États-Unis et l'Amérique centrale. Sa capitale est La Havane.","Cuba est une ancienne colonie espagnole, indépendante depuis 1868."],"src":"https://fr.vikidia.org/wiki/Cuba","sw":"v","q":"Q241","pays":["CU"],"c":["amerique-nord"]},"curacao":{"n":"Curaçao","t":"île","km2":444,"pop":152849,"bref":["Curaçao est une des îles Sous-le-Vent, aux Petites Antilles.","Depuis la dissolution de la fédération des Antilles néerlandaises, le 10 octobre 2010, Curaçao forme un État autonome au sein du royaume des Pays-Bas."],"src":"https://fr.vikidia.org/wiki/Cura%C3%A7ao","sw":"v","q":"Q25279","pays":["NL"],"c":["europe"]},"dominique":{"n":"Dominique","t":"île","km2":751,"pop":74656,"bref":["La Dominique (en anglais : Dominica), ou officiellement le Commonwealth de la Dominique, est un pays formé d'une île de l'archipel des Antilles, située à mi-chemin des îles françaises de la Guadeloupe et de la Martinique. Sa capitale est Roseau.","La Dominique a été une colonie française, avant de devenir colonie britannique en 1768, puis État indépendant depuis 1978."],"src":"https://fr.vikidia.org/wiki/Dominique_(pays)","sw":"v","q":"Q784","pays":["DM"],"c":["amerique-nord"]},"etats-federes-de-micronesie":{"n":"États fédérés de Micronésie","t":"île","km2":702,"pop":75817,"bref":["La Micronésie (en anglais : Micronesia) ou les États fédérés de Micronésie (forme longue), est un pays qui se compose de 607 îles fédérées en 4 états : Kosrae, Pohnpei, Chuuk, et Yap. Toutes font partie de l’archipel des îles Carolines dans le Pacifique occidental. La capitale est Palikir."],"src":"https://fr.vikidia.org/wiki/Micron%C3%A9sie_(pays)","sw":"v","q":"Q702","pays":["FM"],"c":["oceanie"]},"fidji":{"n":"Fidji","t":"île","km2":18274,"pop":926276,"bref":["Les (îles) Fidji ou Fiji sont un archipel de 322 îles de l’océan Pacifique sud, situé à l’est des îles Vanuatu, à l’ouest des îles Tonga et au sud des îles Tuvalu. Elles forment un État dont le nom officiel est République des Îles Fidji. Leur capitale est Suva."],"src":"https://fr.vikidia.org/wiki/Fidji","sw":"v","q":"Q712","pays":["FJ"],"c":["oceanie"]},"grande-barriere-de-corail":{"n":"Grande barrière de corail","t":"île","km2":348000,"bref":["La Grande Barrière de corail ou récif de la Grande Barrière (en anglais : Great Barrier Reef) constitue le plus grand récif corallien du monde. L'ensemble, qui s'étire sur plus de 2 300 kilomètres depuis Bundaberg jusqu'à la pointe de la péninsule du cap York en Australie, couvre une superficie de 344 400 km2. Le site est inscrit en 1981 sur la liste du patrimoine mondial de l'UNESCO sous le nom de Grande Barrière.","La Grande Barrière de corail, située en mer de Corail au large du Queensland, en Australie, est composée de 2 500 récifs et 900 îles. Visible de l'espace, elle est la plus grande structure vivante biogénique (créée par des organismes vivants) au monde, construite par des milliards d'organismes minuscules, connus en tant que coraux polypes ; à ce titre, elle soutient une large diversité de vie marine. La chaîne de télévision CNN la labellise comme une des Sept merveilles naturelles du monde. Le Queensland National Trust la nomme comme l'une des icônes du Queensland."],"src":"https://fr.wikipedia.org/wiki/Grande_Barri%C3%A8re_de_corail","sw":"w","q":"Q7343","pays":["AU"],"c":["oceanie"]},"grande-bretagne":{"n":"Grande-Bretagne","t":"île","km2":228938,"pop":65121000,"bref":["La Grande-Bretagne (en anglais : Great Britain ou plus rarement Britain ; en gallois : Prydain Fawr ; en scots : Great Breetain ; en cornique : Breten Veur, en gaélique écossais : Breatainn Mhòr ; en breton : Breizh-Veur) est une île au large du littoral nord-ouest de l'Europe continentale. Elle représente la majorité du territoire du Royaume-Uni. En son acception politique, ce toponyme désigne l'Angleterre, le pays de Galles et l'Écosse ainsi que la plupart des territoires insulaires contigus à l'exclusion de l'île de Man et des îles Anglo-Normandes.","Située à la jonction de l'Atlantique et de la mer du Nord, elle est séparée de l'Irlande par la mer d'Irlande et du continent par la Manche. C'est la plus grande île et la plus peuplée du continent européen."],"src":"https://fr.wikipedia.org/wiki/Grande-Bretagne","sw":"w","q":"Q23666","pays":["GB"],"c":["europe"]},"grenade":{"n":"Grenade","t":"île","km2":349,"pop":114299,"bref":["La Grenade (en anglais : Grenada) est une île (en fait, un mini-archipel) et un pays du sud des Antilles, au nord de Trinité-et-Tobago.","Sa capitale est Saint-Georges. Ses habitants sont appelés les Grenadins et Grenadines."],"src":"https://fr.vikidia.org/wiki/Grenade_(pays)","sw":"v","q":"Q769","pays":["GD"],"c":["amerique-nord"]},"groenland":{"n":"Groenland","t":"île","km2":2166086,"pop":56609,"bref":["Le Groenland, en groenlandais Kalaallit Nunaat, en danois Grønland, est une immense île du Nord de l’océan Atlantique longeant le Nord-Est du Canada ; c'est la plus grande au monde, étant admis que l'Australie est un continent. Le Groenland n'est pas un continent, comme l'Australie (l'Océanie), c'est la plus grande île du monde. Nuuk est la ville la plus peuplée du Groenland, avec 19604 habitants, contrairement à ce que la plupart des personnes pensent.","Le Groenland est séparé de l'île de Baffin (la plus grande île canadienne, néanmoins quatre fois plus petite que lui) par le détroit de Davis et la baie de Baffin, et de l'île d'Ellesmere (l'île canadienne la plus septentrionale) par le détroit de Nares, d'une largeur minimum de 35 km, qui prolonge la baie de Baffin vers l'océan Arctique."],"src":"https://fr.vikidia.org/wiki/Groenland","sw":"v","q":"Q223"},"guam":{"n":"Guam","t":"île","km2":544,"pop":153836,"bref":["L’île de Guam est située dans le Sud-Est de la mer des Philippines, dans l’archipel des Mariannes, en Micronésie.","Sa superficie est de 549 km2. Sa capitale est Hagåtña (Agana en anglais, qui est avec le chamorro l'une des deux langues officielles de l'île)."],"src":"https://fr.vikidia.org/wiki/Guam","sw":"v","q":"Q16635","pays":["US"],"c":["amerique-nord"]},"haiti":{"n":"Haïti","t":"île","km2":27750,"pop":10981229,"bref":["Haïti (forme courante ; en créole haïtien : Ayiti), ou la République d'Haïti (forme officielle), est un pays des Antilles qui occupe la partie ouest de l'île d'Hispaniola (aussi appelée Haïti ou Saint-Domingue). Sa capitale est Port-au-Prince.","Haïti est le premier des pays colonisés où les esclaves noirs ont fait la guerre contre la puissance coloniale (la France) pendant la révolution française. Lorsque Napoléon arrive au pouvoir, il écrase le soulèvement. Pour des raisons économiques et politiques, Haïti obtienne leur indépendance en 1804."],"src":"https://fr.vikidia.org/wiki/Ha%C3%AFti","sw":"v","q":"Q790","pays":["HT"],"c":["amerique-nord"]},"hispaniola":{"n":"Hispaniola","t":"île","km2":76420,"pop":22261005,"bref":["Hispaniola, aussi appelée Haïti ou Saint-Domingue, est une île de l'archipel des Antilles, aujourd'hui partagée entre la République d'Haïti et la République dominicaine."],"src":"https://fr.vikidia.org/wiki/Hispaniola","sw":"v","q":"Q25277","pays":["DO","HT"],"c":["amerique-nord"]},"hokkaido":{"n":"Hokkaidō","t":"île","km2":77984,"pop":5383579,"bref":["à l'est-nord-est du mont Yoichi, un volcan éteint."],"src":"https://fr.vikidia.org/wiki/Hokkaid%C5%8D","sw":"v","q":"Q35581","pays":["JP"],"c":["asie"]},"honshu":{"n":"Honshu","t":"île","km2":227940,"pop":104000000,"bref":["Honshū est la plus grande île du Japon, autrefois connue en Occident sous le nom de « Hondo », sur laquelle se trouvent entre autres les villes de Tokyo, Osaka, Kyoto, Hiroshima, Yokohama, Nara et Nagoya."],"src":"https://fr.wikipedia.org/wiki/Honsh%C5%AB","sw":"w","q":"Q13989","pays":["JP"],"c":["asie"]},"huahine":{"n":"Huahine","t":"île","km2":78,"bref":["Huahine, ou « l'Authentique », est une île de Polynésie française qui fait partie des îles Sous-le-Vent, dans l'archipel de la Société. Elle est située à 34 km à l'est-nord-est de Raiatea, à 43 km à l'est-sud-est de Taha'a et à 167 km à l'ouest-nord-ouest de Tahiti, par 151° de longitude Ouest et 16°30 de latitude Sud. Elle est aussi proche de Bora-Bora."],"src":"https://fr.wikipedia.org/wiki/Huahine","sw":"w","q":"Q521020","pays":["FR"],"c":["europe"]},"ile-d-ellesmere":{"n":"Île d'Ellesmere","t":"île","km2":196235,"pop":146,"bref":["L’Île d’Ellesmere (en anglais Ellesmere Island) est une île qui se situe au Canada, dans le territoire du Nunavut. L’île fait partie de l’archipel de la Reine-Élisabeth (en anglais Queen Élisabeth Islands). Elle est baignée par l’océan Arctique, le passage du Nord-Ouest, la mer de Lincoln et la baie de Baffin ; sa superficie est de 196 235 km2. C'est par la superficie la troisième île canadienne (après l'île de Baffin et l'île Victoria)."],"src":"https://fr.vikidia.org/wiki/%C3%8Ele_d'Ellesmere","sw":"v","q":"Q146841","pays":["CA"],"c":["amerique-nord"]},"ile-d-oleron":{"n":"Île d'Oléron","t":"île","km2":174,"pop":21790,"bref":["L’île d’Oléron, Ile d’Olerun en saintongeais, est une île française située dans le golfe de Gascogne au large du département de la Charente-Maritime, c'est la plus grande des îles françaises métropolitaines après la Corse. Elle est séparée du continent par le pertuis (détroit) de Maumusson. L'île d'Oléron est divisée en huit communes, La Brée-les-Bains, Le Château-d'Oléron, Dolus-d'Oléron, Le Grand-Village-Plage, Saint-Denis-d'Oléron, Saint-Georges-d'Oléron, Saint-Pierre-d'Oléron et Saint-Trojan-les-Bains, (La ville la plus peuplée est Saint-Pierre-d'Oléron avec ses 6 687 habitants.)","Depuis le 19 mars 1966, l’île est reliée au continent par le pont de l'île d'Oléron qui est long de 3 021 mètres, il est le troisième plus long pont de France après celui de l’île de Ré et celui de Saint-Nazaire."],"src":"https://fr.vikidia.org/wiki/%C3%8Ele_d'Ol%C3%A9ron","sw":"v","q":"Q292568","pays":["FR"],"c":["europe"]},"ile-de-baffin":{"n":"Île de Baffin","t":"île","km2":507451,"pop":13148,"bref":["L'île de Baffin, aussi nommée terre de Baffin est une des îles de l'archipel Arctique dans le passage du Nord-Ouest.","Elle dépend administrativement du territoire du Nunavut. C’est la plus grande île du Canada et la cinquième du monde, avec une superficie de 507 451 km2, soit une surface très légèrement supérieure à celle de l'Espagne. L'île a été nommée par le navigateur et explorateur William Edward Parry en hommage à l'explorateur William Baffin."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_de_Baffin","sw":"w","q":"Q81178","pays":["CA"],"c":["amerique-nord"]},"ile-de-paques":{"n":"Île de Pâques","t":"île","km2":164,"pop":4800,"bref":["L'île de Pâques, ou Rapa Nui, est une île du Sud-Est de l'océan Pacifique, abordée et peuplée par des Polynésiens vers 1200. Elle est ainsi nommée car elle fut découverte par des Européens pour la première fois le jour de Pâques, en l'an 1722. Ses habitants s'appellent les Pascuans. Elle est célèbre pour ses statues impressionnantes, les moais. Appartenant au Chili, l'île est un territoire spécial rattaché à la région de Valparaiso et sa population est d'environ 7 750 habitants. Le chef-lieu est Hanga Roa."],"src":"https://fr.vikidia.org/wiki/%C3%8Ele_de_P%C3%A2ques","sw":"v","q":"Q14452","pays":["CL"],"c":["amerique-sud"]},"ile-de-re":{"n":"Île de Ré","t":"île","km2":85,"bref":["L’île de Ré est une île française située dans le département de la Charente-Maritime, sur la côte Atlantique.","Cette petite île de 30 km de long abrite dix villages de tailles différentes, dont le plus grand, considéré comme la « capitale » de l’île, est Saint-Martin-de-Ré. Cependant, le village le plus peuplé est Sainte-Marie-de-Ré."],"src":"https://fr.vikidia.org/wiki/%C3%8Ele_de_R%C3%A9","sw":"v","q":"Q292384","pays":["FR"],"c":["europe"]},"ile-du-nord":{"n":"Île du Nord","t":"île","km2":113729,"pop":3519800,"bref":["L'île du Nord (en anglais : North Island et en maori de Nouvelle-Zélande : Te Ika-a-Maui ce qui signifie « Le poisson de Maui ») est une des deux principales îles de la Nouvelle-Zélande, l'autre étant l'île du Sud dont elle est séparée par le détroit de Cook. Elle se situe en mer de Tasman, mais ses rivages septentrionaux et orientaux sont baignés par l'océan Pacifique. Plusieurs villes importantes sont situées sur cette île, notamment Auckland, la ville la plus peuplée du pays, et Wellington, la capitale. Environ 76 % de la population de la Nouvelle-Zélande, soit 3 148 400 habitants, réside sur l'île du Nord. On la connait également sous le nom d'île Fumante."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_du_Nord","sw":"w","q":"Q118863","pays":["NZ"],"c":["oceanie"]},"ile-du-sud":{"n":"Île du Sud","t":"île","km2":150437,"pop":1115800,"bref":["L'île du Sud (en anglais : South Island et en maori de Nouvelle-Zélande : Te Waipounamu) est l'une des deux îles principales de la Nouvelle-Zélande, l'autre étant l'île du Nord dont elle est séparée par le détroit de Cook.","Son nom maori est Te Waipounamu, qui signifie : « La rivière des pierres vertes », en raison de la néphrite que les Maoris y avaient découverte. Au XIXe siècle, plusieurs cartes la désignaient sous le nom de Middle Island ou New Munster, le nom île du Sud ou New Leinster étant attribué à ce qui est aujourd'hui l'île Stewart."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_du_Sud","sw":"w","q":"Q120755","pays":["NZ"],"c":["oceanie"]},"ile-europa":{"n":"Île Europa","t":"île","km2":28,"bref":["L'île Europa est une île située dans le canal du Mozambique appartenant au groupement des îles Éparses. Avec les autres îles de ce groupement, l'ile Europa est un territoire français d'outre-mer et des Terres australes et antarctiques françaises. Elle est étendue sur 28 km².","Beaucoup d'animaux y vivent : principalement des oiseaux marins, des bernard l'ermite et des lézards. Le centre de l'île est recouvert d'une steppe salée tandis qu'une forêt s'étend aux bords."],"src":"https://fr.vikidia.org/wiki/%C3%8Ele_Europa","sw":"v","q":"Q193089","pays":["FR","MG"],"c":["europe","afrique"]},"ile-victoria":{"n":"Île Victoria","t":"île","km2":217291,"pop":1875,"bref":["L'île Victoria (en anglais : Victoria Island) est une île du Canada située dans le passage du Nord-Ouest, au-delà du cercle arctique, à cheval entre le Nunavut et les Territoires du Nord-Ouest (tiers ouest de l'île). Par sa superficie de 217 291 kilomètres carrés, l'île se classe deuxième du Canada, troisième d'Amérique et neuvième du monde, juste après la Grande-Bretagne.","L’île a été nommée ainsi en 1839 en l'honneur de la reine Victoria."],"src":"https://fr.wikipedia.org/wiki/%C3%8Ele_Victoria","sw":"w","q":"Q158129","pays":["CA"],"c":["amerique-nord"]},"iles-cook":{"n":"Îles Cook","t":"île","km2":240,"pop":14222,"bref":["Les îles Cook sont un archipel et un État situé dans l'océan Pacifique Sud, à 1 147 km à l'ouest-sud-ouest de Papeete, sur l'île de Tahiti, et à 3 009 km à l'est-nord-est d'Auckland. Il a le statut d'État associé à la Nouvelle-Zélande. Sa capitale est Avarua. Il bénéficie de nombreux droits, notamment celui de s'autogouverner mais il n'est pas indépendant. Les citoyens de l'archipel sont de nationalité néo-zélandaise.","Les îles s'étendents sur 236 km² et sont habitées par près de 17 500 habitants. Les langues officielles sont celles de la Nouvelle-Zélande, soit l'anglais et le māori (bien qu'aux Îles Cook, seul le māori des Îles Cook est officiel, contrairement à toute la Nouvelle-Zélande où tous les dialectes de māori sont officiels)."],"src":"https://fr.vikidia.org/wiki/%C3%8Eles_Cook","sw":"v","q":"Q26988","pays":["CK"],"c":["oceanie"]},"iles-feroe":{"n":"Îles Féroé","t":"île","km2":1399,"pop":54149,"bref":["Les îles Féroé (signifiant les « îles des moutons ») ou Faeroe sont un groupe d'îles dans le Nord de l'océan Atlantique, entre l'Écosse et l'Islande. Elles sont, comme le Danemark lui-même et le Groenland, un pays constitutif du royaume de Danemark.","Leurs habitants, les Féroïens ou Féringiens, parlent une langue proche de l'islandais : le féroïen ou féringien, issu du vieux norrois. La capitale est Tórshavn."],"src":"https://fr.vikidia.org/wiki/%C3%8Eles_F%C3%A9ro%C3%A9","sw":"v","q":"Q4628"},"iles-marshall":{"n":"Îles Marshall","t":"île","km2":181,"pop":53127,"bref":["Les Îles Marshall sont un pays situé en Océanie, dans l'hémisphère nord. Sa superficie de 181 km2 (l'équivalent de la superficie des villes de Paris et de Strasbourg réunies) est si réduite que seuls six pays sont plus petits que lui."],"src":"https://fr.vikidia.org/wiki/%C3%8Eles_Marshall","sw":"v","q":"Q709","pays":["MH"],"c":["oceanie"]},"iles-salomon":{"n":"Îles Salomon","t":"île","km2":28400,"pop":611343,"bref":["Les îles Salomon (en anglais : Solomon Islands) sont un archipel de l'Océanie, situé dans l'Ouest de l'océan Pacifique et formant un État du Commonwealth britannique. La capitale de cet État est Honiara.","L'archipel des Salomon est réparti sur trois mers : l'océan Pacifique Sud où se trouvent les îles les plus grandes, la mer des Salomon où se situent l'archipel de Nouvelle-Géorgie, Guadalcanal et les îles Florida, enfin la mer de Corail. Bien qu'appartenant â l'État des Salomon, les îles Santa Cruz constituent un archipel géographiquement indépendant."],"src":"https://fr.vikidia.org/wiki/%C3%8Eles_Salomon","sw":"v","q":"Q685","pays":["SB"],"c":["oceanie"]},"indonesie":{"n":"Indonésie","t":"île","km2":1916907,"pop":275439000,"bref":["L'Indonésie (forme courte ; en indonésien : Indonesia) ou République d'Indonésie (forme longue) est un pays dont le territoire est en partie en Asie et en Océanie, mais traditionnellement considéré comme un pays de l'Asie du Sud-Est. Il s'étend sur un archipel de plusieurs centaines d'îles, dont les principales sont Sumatra et Java. Sa capitale est Jakarta (au nord de Java) et ses habitants les Indonésiens.","En 2020, elle comptait 270 203 917 habitants, ce qui la classe quatrième pays du monde. De plus, l'Indonésie possède la plus importante population musulmane. Les volcans y sont nombreux et les séismes fréquents."],"src":"https://fr.vikidia.org/wiki/Indon%C3%A9sie","sw":"v","q":"Q252","pays":["ID"],"c":["asie"]},"irlande-q22890":{"n":"Irlande","t":"île","km2":84421,"pop":7185600,"bref":["L'Irlande, aussi surnommée l'île d'Émeraude, est une île située à l'ouest de la Grande-Bretagne, entre la mer d'Irlande (qui la sépare de la Grande-Bretagne et, plus précisément, de l'Angleterre) et l'océan Atlantique.","L'un des lieux les plus beaux d'Irlande est constitué des îles d'Aran. Cet archipel est constitué de trois îles: Inishmore, Inishmaan et Inisheer. Ce petit archipel est marqué par l'océan, tant du point de vue de la géographie physique que de l'aspect culturel et traditionnel. Autrefois les marins d'Aran affrontaient les eaux dangereuses sur de fragiles esquifs d'osier doublés de toile bitumée. La pêche est l'activité économique principale. Le nom même d'Aran vient du poisson le Hareng qui constitue encore de nos jours l'alimentation principale des habitants de ces îles."],"src":"https://fr.vikidia.org/wiki/Irlande_(%C3%AEle)","sw":"v","q":"Q22890","pays":["IE","GB"],"c":["europe"]},"islande":{"n":"Islande","t":"île","km2":103004,"pop":364260,"bref":["L'Islande, en forme longue la république d'Islande, est un pays insulaire d'Europe du Nord situé dans l'océan Atlantique. Ayant pour capitale sa plus grande ville Reykjavik, il est gouverné sous la forme d'une république parlementaire.","Située dans l'océan Atlantique nord, entre le Groenland et la Norvège, au nord-ouest des îles Féroé, l'Islande, y compris les îles qui lui sont rattachées, s'étend sur 102 775 km2. Son relief, culminant à 2 109,6 m au Hvannadalshnjúkur, est assez montagneux, le centre de l'île constituant les Hautes Terres d'Islande désertiques et les côtes étant découpées par des fjords. Plus de 10 % de l'île est constitué de glaciers. L'Islande est située sur la dorsale médio-atlantique séparant les plaques tectoniques eurasienne et nord-américaine, ce qui lui confère une intense activité volcanique. Son climat est océanique, tempéré malgré les latitudes, l'influence polaire étant limitée par le Gulf Stream."],"src":"https://fr.wikipedia.org/wiki/Islande","sw":"w","q":"Q189","pays":["IS"],"c":["europe"]},"jamaique":{"n":"Jamaïque","t":"île","km2":10992,"pop":2697983,"bref":["La Jamaïque (en anglais : Jamaica) est une île des Grandes Antilles et un État indépendant du Commonwealth qui se trouve au sud de Cuba et à l'ouest de l'île d'Hispaniola.","Sa capitale est Kingston, et ses habitants sont les Jamaïcains et les Jamaïcaines."],"src":"https://fr.vikidia.org/wiki/Jama%C3%AFque","sw":"v","q":"Q766"},"japon":{"n":"Japon","t":"île","km2":377974,"pop":123802000,"bref":["Le Japon est un pays insulaire de l'Asie de l'Est, situé entre la mer du Japon et l'océan Pacifique, à l'est de la Chine, de la Corée du Sud et de la Corée du Nord, au sud de la Russie, et au nord-est de Taïwan.","Étymologiquement, les kanjis (caractères chinois) qui constituent le nom du Japon signifient « pays d'origine du Soleil » ; c'est ainsi que le Japon est désigné comme le « pays du soleil levant »."],"src":"https://fr.wikipedia.org/wiki/Japon","sw":"w","q":"Q17","pays":["JP"],"c":["asie"]},"java":{"n":"Java","t":"île","km2":128297,"pop":160293748,"bref":["Java est une île d'Indonésie de la mer de Java située entre Sumatra, Bornéo et Bali. Elle baigne au sud l'océan Indien, et à l'est la mer de Bali."],"src":"https://fr.vikidia.org/wiki/Java_(%C3%AEle)","sw":"v","q":"Q3757","pays":["ID"],"c":["asie"]},"kiribati":{"n":"Kiribati","t":"île","km2":811,"pop":134518,"bref":["Les Kiribati, anciennement connues sous le nom d'îles Gilbert, sont un État d'Océanie composé de trois archipels d'iles : les îles Gilbert, les îles Phœnix et les îles de la Ligne auxquels il faut rajouter l'île soulevée, à l'écart, de Banaba. Ces îles sont situées dans l'océan Pacifique et composent un État très petit en superficie mais recouvrant une grande zone maritime. Elles comptent 33 atolls et îles coralliennes. La capitale est South Tarawa. Le pays est isolé, entre Hawaï et l’Australie."],"src":"https://fr.vikidia.org/wiki/Kiribati","sw":"v","q":"Q710","pays":["KI"],"c":["oceanie"]},"la-desirade":{"n":"La Désirade","t":"île","km2":21,"bref":["L'île de La Désirade est une île française de l'arc des Petites Antilles et une dépendance administrative de la Guadeloupe. Située à une dizaine de kilomètres à l'est de la Grande-Terre, elle fait partie de la commune de même nom, La Désirade, laquelle intègre en outre les îles de la Petite-Terre qui sont inhabitées.","Comme ceux de la commune, les habitants de l'île sont les Désiradiens. Ils sont au nombre de 1 465 sur l'île en 2016."],"src":"https://fr.wikipedia.org/wiki/La_D%C3%A9sirade_(%C3%AEle)","sw":"w","q":"Q1024682","pays":["FR"],"c":["europe"]},"la-reunion":{"n":"La Réunion","t":"île","km2":2512,"pop":889679,"bref":["La Réunion est une île française de 2 512 km2 située dans l'Ouest de l'océan Indien, à l'est de l'Afrique : plus précisément dans l'archipel des Mascareignes, à près de 700 kilomètres à l'est de Madagascar et à un peu plus de 200 kilomètres au sud-ouest de l'île Maurice, terre la plus proche. Son climat est tropical.","Ancienne colonie française, sa devise (issue de cette période de son histoire) est Florebo quocumque ferar, qui est traduisible par \"je fleurirai partout où je serai plantée/portée\"."],"src":"https://fr.vikidia.org/wiki/La_R%C3%A9union","sw":"v","q":"Q17070","pays":["FR"],"c":["europe"]},"lucon":{"n":"Luçon","t":"île","km2":109965,"pop":53336134,"bref":["Luçon est la plus grande île des Philippines. Située au nord de l'archipel, elle compte environ 50 millions d'habitants, soit plus d'un tiers de la population totale du pays. C'est aussi là que se trouve la capitale, Manille.","Luçon est divisée en huit régions, elles-mêmes divisées en 38 provinces."],"src":"https://fr.vikidia.org/wiki/Lu%C3%A7on_(Philippines)","sw":"v","q":"Q125384","pays":["PH"],"c":["asie"]},"madagascar":{"n":"Madagascar","t":"île","km2":587295,"pop":31964956,"bref":["Madagascar (Madagasikara) est un État formé par une île d'Afrique, au large du Mozambique, à environ 400 kilomètres de distance dans l'océan Indien. Les habitants sont des Malgaches et leur monnaie est l'Ariary. En 2022, la population était d'environ 29,6 millions d'habitants, répartis sur 587 041 km².Madagascar compte en 2026 environ 33 522 052 millions d'habitants. Le pays compte de nombreuses ethnies issues de mélanges successifs de population venant des îles indonésiennes et d'Afrique, puis plus tard d'Inde, de Chine et d'Europe.","Madagascar est la cinquième plus grande île au monde après l'Australie, le Groenland, la Nouvelle-Guinée et Bornéo. Le relief de l’île est constitué d'une plaine étroite sur les côtes et de hauts plateaux dans le centre de l'île. Ce relief donne une grande variété de climats. Madagascar est une zone très importante pour la biodiversité. Une grande partie des espèces animales et végétales n'est présente qu'à Madagascar. Ce sont donc des espèces endémiques."],"src":"https://fr.vikidia.org/wiki/Madagascar","sw":"v","q":"Q1019","pays":["MG"],"c":["afrique"]},"maldives":{"n":"Maldives","t":"île","km2":298,"pop":436330,"bref":["Les Maldives, en forme longue la république des Maldives, sont un pays d'Asie du Sud composé de 1 199 îles, dont 202 habitées, situé au sud-ouest du sous-continent indien. Une distance de 608 km sépare Malé, la capitale, de Thiruvananthapuram en Inde. La superficie des terres émergées est de 298 km2 sur les 21 372,72 km2 de superficie totale du pays, lagons inclus.","Les îles sont regroupées en vingt-six atolls et trois îles isolées réparties en vingt subdivisions appelées elles aussi « atoll » et portant chacune le nom d'une lettre thâna. Il constitue de fait le plus petit état insulaire d'Asie."],"src":"https://fr.wikipedia.org/wiki/Maldives","sw":"w","q":"Q826","pays":["MV"],"c":["asie"]},"maurice":{"n":"Maurice","t":"île","km2":2040,"pop":1264613,"bref":["Maurice (en anglais : Mauritius) est un État de l'océan Indien rattaché politiquement â l'Afrique. L'île fait partie d'un groupe insulaire d'origine volcanique, bien que toute activité ait cessé depuis l'Holocène. La plus grande île est l'île Maurice. Sa capitale est Port-Louis.","Ce fut une colonie néerlandaise de 1598 à 1715, puis française jusqu'en 1810, et enfin britannique jusqu'à son indépendance en 1968. Il est membre du Commonwealth."],"src":"https://fr.vikidia.org/wiki/Maurice_(pays)","sw":"v","q":"Q1027","pays":["MU"],"c":["afrique"]},"mindanao":{"n":"Mindanao","t":"île","km2":97530,"pop":27021036,"bref":["Mindanao est une île de la mer des Philippines située dans le Sud de l'archipel des Philippines. Elle baigne au nord, à l'est et au sud-est la mer des Philippines, au nord-ouest la mer de Sulu et au sud la mer de Célèbes. C'est en surface la deuxième île du pays. En 2020, elle comptait environ 26 252 442 habitants, dont environ un quart de musulmans.","Mindanao est divisée en six régions, elles-mêmes divisées en 27 provinces. Sa plus grande ville est Davao."],"src":"https://fr.vikidia.org/wiki/Mindanao","sw":"v","q":"Q124873","pays":["PH"],"c":["asie"]},"moorea":{"n":"Moorea","t":"île","km2":134,"pop":16191,"bref":["Moorea est une île du Pacifique Sud située dans en Polynésie française. Elle fait partie des îles du Vent dans l'archipel de la Société. Moorea est surnommée « la petite sœur de Tahiti » car elle est à portée de vue de Tahiti. L'île de Moorea est entourée d'un récif de corail qui protège les côtes de l'île des vagues de l'océan. Entre le récif et l'île, c'est ce lagon bleu, calme, peu profond bordé de sable blanc. De nombreux poissons viennent s'y reproduire ainsi que les tortues marines sur des sites de ponte bien à l'abri dans le sable, les raies léopards ou les raies papillons s'y laissent facilement observées. Les pieuvres se cachent volontiers dans les massifs de coraux colorés."],"src":"https://fr.vikidia.org/wiki/Moorea","sw":"v","q":"Q673400","pays":["FR"],"c":["europe"]},"moruroa":{"n":"Moruroa","t":"île","km2":15,"bref":["Moruroa, aussi transcrit en Mururoa et historiquement appelé Aopuni, est un atoll de l’archipel des Tuamotu, situé en Polynésie française. À partir des années 1880 et la colonisation des Tuamotu par la France, l'atoll est exploité pour la production de coprah et de nacre par plusieurs sociétés commerciales basées à Tahiti.","En 1964, Moruroa passe en pleine propriété à l’État français. L'atoll est choisi, avec Fangataufa, pour servir de lieu d’expérimentation des essais nucléaires français. Plusieurs milliers de travailleurs polynésiens et de militaires défrichent l'atoll pour y construire les infrastructures nécessaires (pistes d'atterrissage, bunkers, casernes, etc)."],"src":"https://fr.wikipedia.org/wiki/Moruroa","sw":"w","q":"Q318446","pays":["FR"],"c":["europe"]},"nauru":{"n":"Nauru","t":"île","km2":21,"pop":13650,"bref":["Nauru (en nauruan : Naoero), ou République de Nauru (forme officielle), est un État insulaire situé dans l'océan Pacifique, en Micronésie. C'est le plus petit État d'Océanie, et la plus petite république du monde avec 21 km2. Le pays obtient son indépendance de l'Australie en 1968.","Formé d'une seule île, il compte environ 14 000 habitants, appelés les Nauruans et les Nauruanes. Il est le seul pays au monde qui n'a pas de capitale officielle. Toutefois, les bureaux du gouvernement étant à Yaren, la ville sert de capitale officieuse."],"src":"https://fr.vikidia.org/wiki/Nauru","sw":"v","q":"Q697","pays":["NR"],"c":["oceanie"]},"niue":{"n":"Niue","t":"île","km2":260,"pop":1821,"bref":["Niue ou Niué (en niuéen : Niuē Fekai) est un État insulaire de l'océan Pacifique situé à 2 400 km au nord-est de la Nouvelle-Zélande. Sa superficie est de 260 km2 et sa population de 1 492 habitants. Sa capitale et plus grande ville est Alofi."],"src":"https://fr.vikidia.org/wiki/Niue","sw":"v","q":"Q34020","pays":["NU"],"c":["oceanie"]},"nouvelle-guinee":{"n":"Nouvelle-Guinée","t":"île","km2":785753,"pop":11300000,"bref":["La Nouvelle-Guinée est une île d'Océanie, située au nord de l'Australie. Une moitié de l'île fait partie de l'Indonésie et l'autre moitié (celle orientale) représente la plus grande partie de la Papouasie-Nouvelle-Guinée (qui inclut aussi l'archipel Bismarck, l'île Bougainville, et beaucoup d'autres petites îles)."],"src":"https://fr.vikidia.org/wiki/Nouvelle-Guin%C3%A9e","sw":"v","q":"Q40285","pays":["ID","PG"],"c":["asie","oceanie"]},"nouvelle-zelande":{"n":"Nouvelle-Zélande","t":"île","km2":268021,"pop":5307800,"bref":["La Nouvelle-Zélande (en anglais : New Zealand ; en māori : Aotearoa) est un pays situé dans le Sud-Ouest de l'océan Pacifique, à environ 1 452 km de la Nouvelle-Calédonie (son plus proche voisin) et à 1 595 km de l'île d'Anatom, au Vanuatu. Le continent australien se trouve à 1 645 km de l'île du Sud. Le pays est donc très isolé géographiquement.","Les deux grandes îles qui le constituent principalement sont à peu près aux antipodes de l'Europe, c'est à dire à l'autre bout de la planète par rapport à ce continent... et avec un décalage horaire d'environ 12 heures. La capitale est Wellington, la ville la plus peuplée étant Auckland (2 156 km à vol d'oiseau entre celle-ci et Sydney en Australie)."],"src":"https://fr.vikidia.org/wiki/Nouvelle-Z%C3%A9lande","sw":"v","q":"Q664","pays":["NZ"],"c":["oceanie"]},"palaos":{"n":"Palaos","t":"île","km2":466,"pop":21729,"bref":["Palaos est un pays d'Océanie, situé dans la région de la Micronésie. Depuis 2006, sa capitale est Melekeok qui, avec ses 300 habitants, est la plus petite capitale au monde.","Palaos appartient aux îles Carolines. Le pays est un archipel qui regroupe 26 îles et plus de 300 îlots, d'origine volcanique ou de structure corallienne. La plus grande île du pays est Babelthuap (368 km2), mais la population vit en majorité sur la petite île de Koror (8 km2)."],"src":"https://fr.vikidia.org/wiki/Palaos","sw":"v","q":"Q695","pays":["PW"],"c":["oceanie"]},"papouasie-nouvelle-guinee":{"n":"Papouasie-Nouvelle-Guinée","t":"île","km2":462840,"pop":8935000,"bref":["La Papouasie-Nouvelle-Guinée (en anglais : Papua New Guinea) est un des plus grands pays de l'Océanie, c'est aussi l'un des plus pauvres. Il est situé au nord de l'Australie et dans la partie orientale de l'île de Nouvelle-Guinée. Il occupe aussi plusieurs îles alentour. La capitale est Port Moresby."],"src":"https://fr.vikidia.org/wiki/Papouasie-Nouvelle-Guin%C3%A9e","sw":"v","q":"Q691","pays":["PG"],"c":["oceanie"]},"philippines":{"n":"Philippines","t":"île","km2":343448,"pop":112729484,"bref":["La république des Philippines (nom officiel), couramment appelée Philippines (en espagnol : Filipinas ; en filipino : Pilipinas), est un pays formé d'un archipel de 7 107 îles, dont les langues officielles sont l'anglais et le tagalog. Les plus grandes îles se situent dans la mer des Philippines, au sud-est de l'Asie. D'autres îles, comme Palawan, se trouvent en mer de Sulu et quelques unes en mer de Célèbes. Sa capitale est la mégapole de Manille.","C'est l'un des deux seuls pays asiatiques où le catholicisme est la religion principale, avec le Timor oriental."],"src":"https://fr.vikidia.org/wiki/Philippines","sw":"v","q":"Q928","pays":["PH"],"c":["asie"]},"raiatea":{"n":"Raiatea","t":"île","km2":175,"pop":12245,"bref":["Raiatea, également orthographié Raìātea (graphie Turo Raapoto) ou (graphie de l'Académie tahitienne) est une île de Polynésie française faisant partie des îles Sous-le-Vent dans l'archipel de la Société. Elle est la quatrième plus grande île après Tahiti, Nuku Hiva et Hiva Oa. L'île est située à 4,5 km au sud de Tahaa, à 34 km à l'ouest-sud-ouest de Huahine et à 201 km à l'ouest-nord-ouest de Tahiti.","Elle partage le même lagon que l'île de Taha'a. Elle a pour ville principale Uturoa, et est divisée en trois communes, Uturoa, Taputapuatea et Tumaraa."],"src":"https://fr.wikipedia.org/wiki/Raiatea","sw":"w","q":"Q847008","pays":["FR"],"c":["europe"]},"recif-de-ningaloo":{"n":"Récif de Ningaloo","t":"île","km2":7075,"bref":["Le récif de Ningaloo est un récif corallien situé au large de la côte ouest de l'Australie, à environ 1 200 km au nord de Perth. Ce récif frangeant, le plus large d'Australie, est long de 260 km. Il est connu pour accueillir de façon saisonnière de nombreux requins-baleines qui viennent s'y nourrir. Il est inclus dans le parc marin de Ningaloo, un parc géré à la fois par le Commonwealth et l'état d'Australie-Occidentale. Il est aussi inclus dans le site du patrimoine mondial de la côte de Ningaloo, classé en 2011."],"src":"https://fr.wikipedia.org/wiki/R%C3%A9cif_de_Ningaloo","sw":"w","q":"Q1541665","pays":["AU"],"c":["oceanie"]},"republique-dominicaine":{"n":"République dominicaine","t":"île","km2":48671,"pop":10760028,"bref":["La République dominicaine (nom officiel ; en espagnol : República Dominicana) ou Saint-Domingue (nom courant) est un pays d'Amérique centrale, formé de la partie est de l'île de Saint-Domingue ou Hispaniola, dans la mer des Caraïbes, où débarqua Christophe Colomb en 1492.","La République dominicaine est une ancienne colonie espagnole, État indépendant depuis 1821."],"src":"https://fr.vikidia.org/wiki/R%C3%A9publique_dominicaine","sw":"v","q":"Q786","pays":["DO"],"c":["amerique-nord"]},"royaume-uni":{"n":"Royaume-Uni","t":"île","km2":242495,"pop":67326569,"bref":["Le Royaume-Uni de Grande-Bretagne et d'Irlande du Nord, appelé également Royaume-Uni (en anglais : United Kingdom), est un État transcontinental."],"src":"https://fr.vikidia.org/wiki/Royaume-Uni","sw":"v","q":"Q145","pays":["GB"],"c":["europe"]},"saint-christophe-et-nieves":{"n":"Saint-Christophe-et-Niévès","t":"île","km2":272,"pop":46922,"bref":["Saint-Christophe-et-Niévès, ou Saint-Kitts-et-Nevis (en anglais : Saint Kitts and Nevis), est un pays composé de deux îles situé dans les Antilles. Ce pays peut sembler peu important mais il fut autrefois surnommé \"la colonie mère des Antilles\" et c'est le lieu de naissance d'Alexander Hamilton.","L'île de Nevis était à l'origine nommée Saint-Martin par Christophe Colomb en 1493, qui avait donné à l'île le nom de son saint-patron, Saint-Christophe. Aujourd'hui, on ne sait cependant pas qui a changé le nom du pays en Saint-Christophe-et-Niévès."],"src":"https://fr.vikidia.org/wiki/Saint-Christophe-et-Ni%C3%A9v%C3%A8s","sw":"v","q":"Q763","pays":["KN"],"c":["amerique-nord"]},"saint-martin":{"n":"Saint-Martin","t":"île","km2":87,"pop":72239,"bref":["Saint-Martin est une île des Antilles (Amérique), à 250 km au nord de la Guadeloupe.","La moitié nord est française et la moitié sud est néerlandaise."],"src":"https://fr.vikidia.org/wiki/Saint-Martin_(%C3%AEle)","sw":"v","q":"Q25596","pays":["FR","SX"],"c":["europe","amerique-nord"]},"saint-vincent-et-les-grenadines":{"n":"Saint-Vincent-et-les-Grenadines","t":"île","km2":389,"pop":109296,"bref":["Saint-Vincent-et-les Grenadines (en anglais : Saint Vincent and the Grenadines) est un État insulaire (un pays composé uniquement d’îles) situé dans les Antilles, entre Sainte-Lucie et la Grenade.","Ce pays est composé de l’île Saint-Vincent et d’une partie de l’archipel des Grenadines. Sa capitale est Kingstown."],"src":"https://fr.vikidia.org/wiki/Saint-Vincent-et-les_Grenadines","sw":"v","q":"Q757","pays":["VC"],"c":["amerique-nord"]},"sainte-lucie":{"n":"Sainte-Lucie","t":"île","km2":617,"pop":167591,"bref":["Sainte-Lucie (en anglais : Saint Lucia) est une île volcanique et un pays des Antilles.","Ses habitants sont les Saints-Luciens et Saint-Luciennes. Sa capitale est Castries."],"src":"https://fr.vikidia.org/wiki/Sainte-Lucie","sw":"v","q":"Q760","pays":["LC"],"c":["amerique-nord"]},"sakhaline":{"n":"Sakhaline","t":"île","km2":72492,"pop":673100,"bref":["Sakhaline est la plus grande île de la mer d'Okhotsk et de Russie. Elle borde à l'ouest la mer du Japon. Située à l'extrême est de la Russie, Sakhaline se trouve à environ 6 400 km au nord-est de Moscou."],"src":"https://fr.vikidia.org/wiki/Sakhaline","sw":"v","q":"Q7792","pays":["RU"],"c":["asie","europe"]},"samoa":{"n":"Samoa","t":"île","km2":2842,"pop":200010,"bref":["Les ou le Samoa (en forme longue : État indépendant des Samoa) constituent un État indépendant de Polynésie, comprenant quatre îles habitées (Upolu, Savai'i, Manono et Apolima) et six îlots inhabités, dans le Sud de l'océan Pacifique. Les deux plus grandes îles sont Upolu et Savai'i, à l'ouest. La capitale Apia et l’aéroport international de Faleolo sont situés sur la côte nord d'Upolu."],"src":"https://fr.vikidia.org/wiki/Samoa","sw":"v","q":"Q683","pays":["WS"],"c":["oceanie"]},"sao-tome-et-principe":{"n":"Sao Tomé-et-Principe","t":"île","km2":1001,"pop":204327,"bref":["Sao Tomé-et-Principe, São Tomé-et-Príncipe ou Saint-Thomas-et-l'île du Prince (en portugais São Tomé e Príncipe), en forme longue la république démocratique de Sao Tomé-et-Principe, est un État insulaire d'Afrique centrale, l'un des plus petits pays d'Afrique. Il occupe un archipel situé dans le golfe de Guinée, à 239 km des côtes du Gabon (São Tomé) et 216 km de la Guinée équatoriale (Principe).","Il est formé de deux îles principales, São Tomé au sud-ouest et Principe au nord-est, se trouvant entre les deux îles équato-guinéennes de Bioko au nord et d'Annobón au sud. L'ensemble du territoire couvre une superficie d'environ 1 000 km2. Le relief volcanique culmine à plus de 2 000 m, le climat est de type équatorial. L'agriculture — et notamment la production de cacao — conserve une place importante, mais l'exploitation attendue des hydrocarbures et le potentiel touristique ont fait naître de grands espoirs dans un pays pauvre, qui reste largement tributaire de l'aide internationale."],"src":"https://fr.wikipedia.org/wiki/Sao_Tom%C3%A9-et-Principe","sw":"w","q":"Q1039","pays":["ST"],"c":["afrique"]},"seychelles":{"n":"Seychelles","t":"île","km2":459,"pop":119773,"bref":["Les Seychelles sont un État insulaire situé dans l’océan Indien, au nord-est de Madagascar et à l’est du continent africain. L’archipel est composé de 115 îles réparties entre les îles granitiques (comme Mahé, Praslin, et La Digue) et les îles coralliennes plus éloignées."],"src":"https://fr.vikidia.org/wiki/Seychelles","sw":"v","q":"Q1042","pays":["SC"],"c":["afrique"]},"singapour":{"n":"Singapour","t":"île","km2":719,"pop":5866139,"bref":["Singapour est une cité-État, c'est-à-dire un État constitué d'une seule ville (et éventuellement des territoires environnants). Il se situe en Asie du Sud-Est, à l'extrémité de la péninsule de Malacca, à 10 741 km à l'est de Paris, 894 km au nord-ouest de Jakarta, 315 km au sud-est de Kuala Lumpur et 1,9727e+10 mm de Quito.","Singapour se compose de 65 îles dispersées dans le détroit de Singapour."],"src":"https://fr.vikidia.org/wiki/Singapour","sw":"v","q":"Q334","pays":["SG"],"c":["asie"]},"sri-lanka":{"n":"Sri Lanka","t":"île","km2":65610,"pop":21444000,"bref":["Le Sri Lanka, officiellement la République socialiste démocratique du Sri Lanka, est un pays insulaire situé au sud-est de l'Inde, dans le Sud-Ouest du golfe du Bengale. Il s'appelait autrefois Ceylan. Sa capitale est Sri Jayawardenapura Kotte (capitale politique) à ne pas confondre avec Colombo qui est la capitale économique et la plus grande ville du pays."],"src":"https://fr.vikidia.org/wiki/Sri_Lanka","sw":"v","q":"Q854","pays":["LK"],"c":["asie"]},"sumatra":{"n":"Sumatra","t":"île","km2":473481,"pop":60000000,"bref":["Sumatra est une île de l'Ouest de l'Indonésie située sur l'équateur. Son nom vient de Samudra, la capitale du sultanat de Pasai dans le nord de l'île (en langue malaise, samudera signifie « océan »). Avec ses 473 481 km2, elle est la sixième plus grande île du monde, tout en étant légèrement supérieure à la Papouasie-Nouvelle-Guinée et à la Suède. En 2021, le recensement comptait 59 185 500 habitants.","Les principales langues parlées sont : aceh, batak, malais, minangkabau. La majorité des habitants sont musulmans, mais Sumatra compte aussi des protestants, des catholiques, des bouddhistes, des hindous."],"src":"https://fr.wikipedia.org/wiki/Sumatra","sw":"w","q":"Q3492","pays":["ID"],"c":["asie"]},"tahiti":{"n":"Tahiti","t":"île","km2":1042,"pop":178133,"bref":["Tahiti est une île de la Polynésie française (collectivité d'outre-mer) située dans l'océan Pacifique Sud. Elle fait partie de l’archipel de la Société et du groupe des îles du Vent. L'île se trouve à 3 811 kilomètres à l'est-nord-est de la Nouvelle-Zélande, à 4 083 km au sud de Hawaï et à 7 334 km à l'ouest du point le plus proche du continent américain et situé dans le Chili méridional (péninsule Taitao, région d'Aysén).","C'est une île haute et montagneuse, d'origine volcanique, entourée d'un récif de corail. Son point culminant est le mont Orohena avec une altitude de 2 241 mètres. Ce sommet est aussi le plus haut de la Polynésie française et même de l'océan Pacifique Sud (hors mers bordières). Il est aussi l'un des sommets les plus isolés du monde et le plus isolé de l'océan Pacifique."],"src":"https://fr.vikidia.org/wiki/Tahiti","sw":"v","q":"Q42000","pays":["FR"],"c":["europe"]},"taiwan":{"n":"Taïwan","t":"île","km2":36197,"pop":23262544,"bref":["Taïwan, ou la République de Chine, est un État souverain au statut contesté situé sur l'île de Taïwan en mer de Chine méridionale. Elle est séparée de la Chine continentale par le détroit de Taïwan. Elle était autrefois appelée Formose.","L'île est depuis 1949 sous l'autorité du gouvernement de la République de Chine, totalement indépendante du gouvernement de la République populaire de Chine qui la revendique comme une province de son territoire. Seuls dix-huit pays la reconnaissent comme un pays. De plus en plus de pays cessent de reconnaître Taïwan comme un État indépendant sous la pression de la République populaire de Chine."],"src":"https://fr.vikidia.org/wiki/Ta%C3%AFwan","sw":"v","q":"Q865","pays":["TW"],"c":["asie"]},"terre-neuve":{"n":"Terre-Neuve","t":"île","km2":108860,"pop":479538,"bref":["Terre-Neuve est une île du golfe du Saint-Laurent au large du Canada. Sa côte nord-est baigne la mer du Labrador. Avec une partie de la péninsule du Labrador, elle forme la province canadienne de Terre-Neuve-et-Labrador."],"src":"https://fr.vikidia.org/wiki/Terre-Neuve","sw":"v","q":"Q48335","pays":["CA"],"c":["amerique-nord"]},"timor-oriental":{"n":"Timor oriental","t":"île","km2":14919,"pop":1400638,"bref":["Le Timor oriental, Timor-Oriental ou Timor-Leste (formes courtes ; en portugais : Timor-Leste ; en tétoum : Timor Lorosa'e), ou la République démocratique de Timor oriental (forme longue), est un pays classé, selon les géographes, en Asie (position traditionnelle) ou en Océanie."],"src":"https://fr.vikidia.org/wiki/Timor_oriental","sw":"v","q":"Q574","pays":["TL"],"c":["asie"]},"tonga":{"n":"Tonga","t":"île","km2":749,"pop":108020,"bref":["Les Tonga, ou îles Tonga, sont un archipel situé dans l'océan pacifique, au nord de la Nouvelle-Zélande et à 650 km à l'est des îles Fidji. Le territoire national comporte environ 170 îles. On compte dans le pays environ 120 000 habitants, les Tongiens et les Tongiennes, qui se répartissent sur 748 km2. La capitale des Tonga est Nuku'alofa.","Le pays est un royaume et le régime politique est une monarchie constitutionnelle, le chef de l'État est le roi Tupou VI."],"src":"https://fr.vikidia.org/wiki/Tonga","sw":"v","q":"Q678","pays":["TO"],"c":["oceanie"]},"trinite-et-tobago":{"n":"Trinité-et-Tobago","t":"île","km2":5128,"pop":1369125,"bref":["Trinité-et-Tobago (en anglais : Trinidad and Tobago), en forme longue la République de Trinité-et-Tobago (en anglais : Republic of Trinidad and Tobago) est un archipel et un pays du Sud des Antilles, à 12 km seulement au large du Venezuela.","Sa capitale est Port-d'Espagne."],"src":"https://fr.vikidia.org/wiki/Trinit%C3%A9-et-Tobago","sw":"v","q":"Q754","pays":["TT"],"c":["amerique-nord"]},"tubuai":{"n":"Tubuai","t":"île","km2":45,"pop":2285,"bref":["Tubuai, en tahitien (graphie de l'Académie tahitienne) ou Tupuaì (graphie Raapoto), est une île volcanique située dans le groupe des îles Australes, en Polynésie française. La commune de Tubuai est le chef-lieu de l'archipel."],"src":"https://fr.wikipedia.org/wiki/Tubuai","sw":"w","q":"Q514626","pays":["FR"],"c":["europe"]},"tuvalu":{"n":"Tuvalu","t":"île","km2":26,"pop":10643,"bref":["Les Tuvalu sont un pays situé en Océanie, plus précisément en Polynésie. Le pays est un archipel volcanique composé de trois îles (Nanumanga, Niutao et Niulakita) et six atolls (Funafuti, Nanumea, Nui, Nukufetau, Nukulaelae et Vaitupu), tous habités, et qui sont d'ailleurs représentés par les 9 étoiles jaunes sur le drapeau du pays.","Le pays a une superficie de 26 km2, ce qui en fait le quatrième plus petit pays au monde (après la Cité du Vatican, Monaco et Nauru). La population des Tuvalu est également très petite (10 507 habitants au recensement de 2017), ce qui les classe troisième pays le moins peuplé (après la Cité du Vatican et Nauru)."],"src":"https://fr.vikidia.org/wiki/Tuvalu","sw":"v","q":"Q672","pays":["TV"],"c":["oceanie"]},"vanuatu":{"n":"Vanuatu","t":"île","km2":12190,"pop":300019,"bref":["Le Vanuatu, en forme longue la république du Vanuatu, est un État situé en mer de Corail et faisant partie de la Mélanésie. L'archipel est composé de 83 îles pour la plupart d'origine volcanique, au nord-est de la Nouvelle-Calédonie, mais aussi au sud-est des îles Salomon et à l'ouest des îles Fidji."],"src":"https://fr.vikidia.org/wiki/Vanuatu","sw":"v","q":"Q686","pays":["VU"],"c":["oceanie"]}},
"deserts":{"dacht-e-kavir":{"n":"Dacht-e Kavir","t":"désert","km2":55000,"bref":["Le Dacht-e Kavir ou Dasht-e Kavir, aussi connu sous le nom de Kavir-e Namak ou « Grand désert salé », est un grand désert au milieu du plateau iranien. Il mesure environ 800 km de long et 320 km de large. La surface de ce désert s'étend depuis la chaîne montagneuse de l'Elbourz au nord-ouest jusqu'au Dacht-e Lout (« désert du vide ») au sud-est et se répartit entre les provinces iraniennes du Khorassan, de Semnan, d'Ispahan et de Yazd. Son nom est dérivé des marais salés (kavirs) qui existent dans cette région."],"src":"https://fr.wikipedia.org/wiki/Dacht-e_Kavir","sw":"w","q":"Q272514","pays":["IR"],"c":["asie"]},"desert-arabique":{"n":"Désert Arabique","t":"désert","km2":221900,"bref":["Le désert Arabique ou désert oriental d'Égypte est un désert de l’Est de l’Égypte situé à l’extrémité Nord-Est du Sahara. Il est délimité par le delta du Nil au nord, le canal de Suez et la mer Rouge à l’est, la vallée du Nil à l’ouest et le désert de Nubie au sud, au-delà du lac Nasser.","En Égypte, la région est qualifiée de désert oriental par opposition au désert occidental d'Égypte (désert Libyque), tandis que le désert du Sud peut être qualifié de désert méridional d'Égypte."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_Arabique","sw":"w","q":"Q624170","pays":["EG","ER","SD","ET"],"c":["afrique"]},"desert-d-arabie":{"n":"Désert d'Arabie","t":"désert","km2":2330000,"bref":["Le désert d'Arabie s'étend sur la plus grande partie de la péninsule arabique. Son climat extrêmement sec a longtemps freiné le développement de sa population. L'exploitation du pétrole a entrainé un développement important des pays de la région depuis le milieu du XXIe siècle."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_d'Arabie","sw":"v","q":"Q208299","pays":["SA","OM","YE","IQ","JO","AE"],"c":["asie"]},"desert-d-atacama":{"n":"Désert d'Atacama","t":"désert","km2":1813005,"bref":["Le désert d'Atacama est un désert situé dans les régions d'Antofagasta et d'Atacama, dans le Nord du Chili, en Amérique du sud. Cette zone couvre entre environ 100 000 et 130 000 km², selon les frontières choisies. Cette barrière naturelle est composée notamment de volcans, de lagunes turquoises, de geysers et de vallées encaissées. On trouve aussi dans ce désert le plus grand dépôt salin du Chili, le salar d'Atacama. Celui-ci abrite un des plus importants gisements de lithium au monde."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_d'Atacama","sw":"v","q":"Q47141","pays":["CL"],"c":["amerique-sud"]},"desert-danakil":{"n":"Désert Danakil","t":"désert","km2":136956,"bref":["Le désert Danakil est un désert situé dans la Corne de l'Afrique, au nord-est de l'Éthiopie et au sud de l'Érythrée, dans le district du sud de la mer Rouge."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_Danakil","sw":"w","q":"Q141513","pays":["ER","DJ","ET"],"c":["afrique"]},"desert-de-badain-jaran":{"n":"Désert de Badain Jaran","t":"désert","km2":50000,"bref":["Le désert de Badain Jaran est un désert de Chine qui s'étend sur les provinces du Gansu, de Ningxia et de Mongolie Intérieure et couvre une surface de 49 000 kilomètres carrés.","Le désert détient les dunes les plus hautes du monde, s'élevant jusqu'à 500 mètres. Ces dunes se maintiennent dans cette région ventée grâce à la présence de sources souterraines, alimentées par des eaux de fonte qui parcourent des centaines de kilomètres à travers des failles rocheuses."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Badain_Jaran","sw":"w","q":"Q939033","pays":["CN"],"c":["asie"]},"desert-de-chihuahua":{"n":"Désert de Chihuahua","t":"désert","km2":362600,"bref":["Le désert de Chihuahua (en anglais : Chihuahuan Desert, en espagnol : Desierto Chihuahuense) est l’un des déserts les plus riches du point de vue de la diversité biologique. Il s’étend sur 647 000 km2 à travers le nord du Mexique (Chihuahua, Coahuila, Nuevo León, Durango, Zacatecas et San Luís Potosí) et le sud-ouest des États-Unis (Arizona, Nouveau-Mexique et Texas). C'est le deuxième plus grand désert des Amériques et le plus grand d'Amérique du Nord.","Le désert de Chihuahua est bordé à l'ouest par le désert de Sonora, le plateau du Colorado et la vaste chaîne de la Sierra Madre occidentale, ainsi que par les basses terres du nord-ouest de la Sierra Madre orientale. Près de 90 % de sa surface est située au Mexique. Ce désert est relativement jeune, puisqu'il n'existe que depuis 8 000 ans."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Chihuahua","sw":"w","q":"Q855658","pays":["US","MX"],"c":["amerique-nord"]},"desert-de-gibson":{"n":"Désert de Gibson","t":"désert","km2":155000,"bref":["Le désert de Gibson (en anglais Gibson Desert) est un désert d'Australie-Occidentale formant une écorégion terrestre définie par le WWF. Il fait partie de l'écozone australasienne et du biome des déserts et terres arbustives xériques.","Il couvre une zone de plus 155 000 km2 de collines couvertes d'herbes sèches. Il est situé au sud du Grand Désert de Sable et au nord du grand désert de Victoria. Son altitude moyenne est de 500 m. Il n'est habité que par des aborigènes qui vivent dans les régions les plus élevées. On y trouve des kangourous et des émeus. Il forme une partie du plateau de l'Australie occidentale et s'étend, entre le lac Disappointment et le lac Macdonald (en), le long du Tropique du Capricorne. Il doit son nom à l'explorateur Alfred Gibson qui mourut en essayant de le traverser en 1874 en compagnie de l'explorateur Ernest Giles."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Gibson","sw":"w","q":"Q272577","pays":["AU"],"c":["oceanie"]},"desert-de-gobi":{"n":"Désert de Gobi","t":"désert","km2":2354460,"bref":["Le désert de Gobi est une vaste étendue désertique située entre la Chine et la Mongolie. Sa superficie est de 1 300 000 km². C'est l'un des plus vastes déserts au monde.","Il est essentiellement composé de pierres."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_de_Gobi","sw":"v","q":"Q42070","pays":["CN","MN"],"c":["asie"]},"desert-de-nubie":{"n":"Désert de Nubie","t":"désert","km2":400000,"bref":["Le désert de Nubie, en arabe Şaḩrā’ an Nūbyah, est la partie orientale du désert du Sahara, au nord-est du Soudan et au sud-est de l'Égypte mesurant 407 000 km2 de superficie. Il est délimité par le Nil à l'ouest, l'Itbay bordant la mer Rouge à l'est, le désert Arabique au nord et des savanes au sud."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Nubie","sw":"w","q":"Q464909","pays":["SD"],"c":["afrique"]},"desert-de-simpson":{"n":"Désert de Simpson","t":"désert","km2":176500,"bref":["Le désert de Simpson forme une écorégion terrestre définie par le WWF occupant le centre de l'Australie. Il fait partie du biome des déserts et terres arbustives xériques et de l'écozone australasienne.","Il s'étend à la limite de trois des États australiens occupant le sud-est du Territoire du Nord ainsi que les espaces limitrophes du Queensland et de l'Australie-Méridionale. Sa superficie est évaluée selon les sources de 143 000 km² à 300 000 km². Ses contours incertains sont fixés à l'ouest par le cours du fleuve Finke, au nord par la chaine de montagnes des MacDonnell Ranges, à l'est par les fleuves Georgina et Diamantina et au sud par le Lac Eyre. Dans ce désert, les précipitations annuelles sont faibles (comprises entre 150 et 200 mm) et il peut s'écouler plusieurs années sans pluie."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Simpson","sw":"w","q":"Q211839","pays":["AU"],"c":["oceanie"]},"desert-de-sonora":{"n":"Désert de Sonora","t":"désert","km2":310800,"bref":["Le désert de Sonora aussi appelé désert de Gila est une vaste zone désertique située entre le Sud-Ouest des États-Unis et le Nord-Ouest du Mexique, en Amérique du Nord.","C'est le plus grand désert d'Amérique du Nord. Il est connu pour la flore exceptionnelle qu'il abrite et ses paysages. Beaucoup de touristes le visitent entre mars et avril."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_de_Sonora","sw":"v","q":"Q189429","pays":["US","MX"],"c":["amerique-nord"]},"desert-de-syrie":{"n":"Désert de Syrie","t":"désert","km2":518000,"bref":["Le désert de Syrie appelé aussi simplement la Badiya est une zone de désert chaud, de semi-désert et de steppe située dans le nord du désert d'Arabie et de la péninsule arabique, s'étendant de la Jordanie à l’Irak en passant par la Syrie. Ce grand arc steppique parcouru par les nomades, d'une superficie d'environ 520 000 km2, est très rocailleux et compte peu de reliefs.","Par abus de langage, le désert de Syrie est également appelé la Chamiyé, terme qui désigne le domaine steppique sur la rive droite de l’Euphrate, limité au sud par la ligne joignant Damas à Anah, dans la vallée de l’Euphrate au sud d’Abu Kamal."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Syrie","sw":"w","q":"Q339162","pays":["SY","JO","IQ","SA"],"c":["asie"]},"desert-de-tanami":{"n":"Désert de Tanami","t":"désert","km2":184500,"bref":["Le désert de Tanami est un désert du nord de l’Australie. C’est un terrain rocailleux avec de petites collines.","Le désert de Tanami est l’un des plus isolés et des plus arides endroits de la Terre. Il était la frontière nord du Territoire du Nord et n’a pas été exploré avant le XXe siècle. Il est traversé par la Tanami Track (ou Tanami Road)."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_de_Tanami","sw":"w","q":"Q674262","pays":["AU"],"c":["oceanie"]},"desert-des-mojaves":{"n":"Désert des Mojaves","t":"désert","km2":124000,"bref":["Le désert des Mojaves, de Mojave, ou simplement désert Mojave, est une grande étendue désertique d'environ 40 000 km2. Il est situé dans l'ouest des États-Unis, dans le sud de la Californie essentiellement, mais il déborde sur les états voisins du Nevada au nord, et de l'Arizona à l'est. Ce désert appartient au même ensemble géologique que le Grand Bassin ou que le désert de Sonora. Son nom est emprunté à un peuple amérindien, les Mohaves. C'est un désert d'abri, bordé par les montagnes Tehachapi, San Gabriel et San Bernadino.","La rivière Mojave (Mojave River) est une source d'eau importante pour l'irrigation. En outre, une partie du fleuve Colorado traverse l'est du désert de Mojave."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_des_Mojaves","sw":"w","q":"Q184355","pays":["US"],"c":["amerique-nord"]},"desert-du-grand-bassin":{"n":"Désert du Grand Bassin","t":"désert","km2":492000,"bref":["Le Grand Bassin des États-Unis (Great Basin en anglais) est un désert de l'Ouest des États-Unis. C'est une région de montagnes, de bassins sédimentaires et de hauts plateaux. La région offre une grande variété de paysages : ceux du parc national du Grand Bassin sont protégés. Faune et flore sont présentes, bien que discrètes, surtout autour des lacs dont la salinité généralement assez élevée est due à l'endoréisme. Couvrant quelque 10 % des États-Unis, le Grand Bassin est la région la plus sèche du pays."],"src":"https://fr.wikipedia.org/wiki/Grand_Bassin_des_%C3%89tats-Unis","sw":"w","q":"Q273446","pays":["US"],"c":["amerique-nord"]},"desert-du-kalahari":{"n":"Désert du Kalahari","t":"désert","km2":930000,"bref":["Le désert du Kalahari est une zone semi-aride située dans une immense cuvette du plateau intérieur de l'Afrique australe et s'étendant sur 930 000 kilomètres carrés depuis la rivière Auab, située en Namibie et affluent de l'Orange, à l'ouest, jusqu'à la rivière Shashi, affluent du Limpopo, à l'est, et depuis le delta de l'Okavango, au Botswana, au nord, jusqu'au fleuve Orange et à son affluent le Vaal au sud, dans la province du Cap-Nord en Afrique du Sud."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_du_Kalahari","sw":"v","q":"Q47700","pays":["BW","NA","AO","ZA"],"c":["afrique"]},"desert-du-karakoum":{"n":"Désert du Karakoum","t":"désert","km2":400000,"bref":["Le désert du Karakoum, ou du Kara-Koum, s'étend en Asie centrale, essentiellement au Turkménistan dont il occupe plus de la moitié du territoire (350 000 km2)."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_du_Karakoum","sw":"w","q":"Q172702","pays":["TM"],"c":["asie"]},"desert-du-kyzylkoum":{"n":"Désert du Kyzylkoum","t":"désert","km2":298000,"bref":["Le désert du Kyzylkoum ou désert du Kyzyl-Koum est un désert partagé entre le Kazakhstan, l'Ouzbékistan et, pour une petite partie, le Turkménistan."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_du_Kyzylkoum","sw":"w","q":"Q184364","pays":["TM","KZ","UZ"],"c":["asie","europe"]},"desert-du-namib":{"n":"Désert du Namib","t":"désert","km2":81000,"bref":["Le désert du Namib est un désert situé dans le sud-ouest de la Namibie. C'est le plus vieux désert du monde, il est aride depuis 80 millions d'années."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_du_Namib","sw":"v","q":"Q131377","pays":["NA"],"c":["afrique"]},"desert-du-taklamakan":{"n":"Désert du Taklamakan","t":"désert","km2":337000,"bref":["Le désert du Taklamakan — en chinois Taklimakan shamo, aussi écrit simplement Takla Makan — est le plus grand désert de Chine : il mesure 1 000 km d'est en ouest pour 500 km du nord au sud. C'est en surface le troisième désert de sable au monde, après le Sahara et le Kalahari. Il occupe la plus grande partie du bassin du Tarim, dans le Nord-Ouest de la Chine. Il se trouve dans la région autonome du Xinjiang où la population ouïgoure (peuple d'Asie centrale) est très importante. Il est en position d'abri entre les montagnes du Kunlun et du Tian Shan, si bien que les précipitations y sont très faibles. Sa superficie est d'environ 340 000 km2, c'est-à-dire presque la taille de l'Allemagne.","Divers peuples vivent dans le désert du Takla Makan : les Ouïgours, les Kirghizes et les Kazakhs. Ce sont des nomades élevant des moutons."],"src":"https://fr.vikidia.org/wiki/D%C3%A9sert_du_Taklamakan","sw":"v","q":"Q132956","pays":["CN"],"c":["asie"]},"desert-du-thar":{"n":"Désert du Thar","t":"désert","km2":200000,"bref":["Le désert du Thar (rajasthani : (thār marudhar) ; hindi : (thār marusthal) ou (thār rēgistān)) — appelé aussi le Grand Désert indien ou Mârusthali, le Pays de la mort — est un désert qui s'étend sur 200 000 km2 dans l'État du Rajasthan, dans le nord-ouest de l'Inde et au Pakistan où il est appelé désert du Cholistan."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_du_Thar","sw":"w","q":"Q172691","pays":["IN","PK"],"c":["asie"]},"desert-libyque":{"n":"Désert Libyque","t":"désert","km2":1100000,"bref":["Le désert Libyque ou désert de Libye est un désert, d'environ 700 000 km2, situé dans la partie ouest de l'Égypte, la partie est de la Libye et au nord-ouest du Soudan. Ce désert est une partie du Sahara. Une partie de sa surface constituée de calcaire est appelée désert blanc.","En Égypte, le désert est aussi appelé désert occidental par opposition au désert oriental (désert arabique)."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_Libyque","sw":"w","q":"Q181528","pays":["LY","EG","SD"],"c":["afrique"]},"grand-desert-de-sable":{"n":"Grand désert de sable","t":"désert","km2":284993,"bref":["Le Grand Désert de Sable (en anglais : Great Sandy Desert) est une vaste plaine désertique de 360 000 km2 dans le nord-ouest de l'Australie. Région très peu peuplée, sans aucune localité notable, elle est partagée entre les chaînes du Pilbara et le Kimberley. Au sud-est, elle se prolonge par le désert de Gibson et à l'est par le désert de Tanami. Seule la région côtière à l'ouest compte quelques élevages de moutons."],"src":"https://fr.wikipedia.org/wiki/Grand_D%C3%A9sert_de_Sable","sw":"w","q":"Q326896","pays":["AU"],"c":["oceanie"]},"grand-desert-de-victoria":{"n":"Grand désert de Victoria","t":"désert","km2":348750,"bref":["Le grand désert de Victoria (en anglais : The Great Victoria Desert) est une écorégion désertique du sud de l'Australie, à cheval sur l'Australie-Occidentale et l'Australie-Méridionale. Elle fait partie de l'écozone australasienne et du biome des déserts et terres arbustives xériques. On y trouve des dunes de sable, des zones d'herbes sèches et des lacs de sel. Il s'étale, d'est en ouest, sur 700 km de large et couvre une superficie de 424 400 km2.","Les moyennes de précipitations annuelles se situent autour de 200 à 250 mm par an et les orages n'y sont pas rares (15 à 20 par an). Les températures oscillent entre 32 et 40 °C en été et 18 et 23 °C en hiver."],"src":"https://fr.wikipedia.org/wiki/Grand_d%C3%A9sert_de_Victoria","sw":"w","q":"Q145165","pays":["AU"],"c":["oceanie"]},"grand-erg-oriental":{"n":"Grand Erg oriental","t":"désert","km2":185000,"bref":["Le Grand Erg oriental est un grand erg dans le Sahara. Situé pour les cinq sixièmes de sa superficie dans les basses terres sahariennes du nord-est de l'Algérie, sa partie nord-est s'étend sur le territoire de la Tunisie.","Le Grand Erg oriental couvre 185 000 km2, soit 570 kilomètres d'est en ouest sur 590 kilomètres du nord au sud. Il est le second plus grand erg d'Algérie après l'Erg Chech. La partie tunisienne couvre environ 30 000 km2. Ses limites sont les monts du djebel Dahar (Tunisie) à l'est, la Hamada de Tinrhert (Algérie) au sud, le plateau de Tademaït au sud-ouest, la dorsale du Mzab à l'ouest et au nord ; il est bordé par l'Atlas, les montagnes de l'Aurès et le Chott el-Jérid (Tunisie)."],"src":"https://fr.wikipedia.org/wiki/Grand_Erg_oriental","sw":"w","q":"Q307143","pays":["DZ","TN","LY"],"c":["afrique"]},"nefoud":{"n":"Néfoud","t":"désert","km2":78000,"bref":["Le désert du Néfoud est un désert de la partie Nord de la péninsule Arabique. Il occupe une grande dépression ovale, de 290 km de long et 225 km de large, pour une superficie de 78 000 à 103 600 km2, selon les délimitations."],"src":"https://fr.wikipedia.org/wiki/D%C3%A9sert_du_N%C3%A9foud","sw":"w","q":"Q749205","pays":["SA"],"c":["asie"]},"neguev":{"n":"Néguev","t":"désert","km2":13000,"bref":["Le Néguev est une région désertique du sud d'Israël. En hébreu biblique, Néguev signifie « sud ». Le Néguev couvre la plus grande part du district sud d’Israël."],"src":"https://fr.wikipedia.org/wiki/N%C3%A9guev","sw":"w","q":"Q162843","pays":["IL"],"c":["asie"]},"petit-desert-de-sable":{"n":"Petit désert de sable","t":"désert","km2":111500,"bref":["Le Petit Désert de Sable est un désert situé en Australie-Occidentale au sud-ouest du Grand Désert de Sable et à l'ouest du désert de Gibson. Il doit son nom à sa proximité et à sa similitude (sauf pour la taille) avec le Grand Désert de Sable. Ses paysages, sa faune et sa flore sont comparables en tout point avec ceux de son voisin. Les deux déserts sont traversés par le chemin pour le bétail de Canning (Canning cattle route en anglais), un chemin de 1800 kilomètres qui relie Halls Creek à Wiluna à travers le désert, découvert par Alfred Canning (en), qui repéra 52 puits sur le trajet."],"src":"https://fr.wikipedia.org/wiki/Petit_D%C3%A9sert_de_Sable","sw":"w","q":"Q4076","pays":["AU"],"c":["oceanie"]},"rub-al-khali":{"n":"Rub al-Khali","t":"désert","km2":680000,"bref":["Le Rub al Khali est l'un des plus grands déserts et la plus grande étendue ininterrompue de sable au monde. Il occupe environ 650 000 km2 dans le tiers le plus méridional de la péninsule Arabique.","Il a approximativement la forme d'un rectangle de 1 000 kilomètres de longueur et 500 kilomètres de largeur. Il est situé pour l'essentiel sur le territoire de l'Arabie saoudite et pour une bien moindre part sur les territoires du Yémen, d'Oman et des Émirats arabes unis. Son altitude varie du niveau de la mer dans son nord-est, à environ 800 m d'altitude dans son sud-ouest."],"src":"https://fr.wikipedia.org/wiki/Rub_al-Khali","sw":"w","q":"Q229269","pays":["AE","SA","YE","OM"],"c":["asie"]},"sahara":{"n":"Sahara","t":"désert","km2":9200000,"bref":["Le Sahara, au nord de l'Afrique, est le plus grand désert du monde (plus de 8 millions de km²) ; en arabe, le mot (Sahara) signifie désert.","Cette vaste région chaude s'étend sur 10 pays : la Tunisie, l'Algérie, le Maroc, la Libye, l'Égypte, le Soudan, le Tchad, le Niger, le Mali et la Mauritanie. La température la plus chaude est de +55 °C."],"src":"https://fr.vikidia.org/wiki/Sahara","sw":"v","q":"Q6583","pays":["DZ","TD","EG","MA","TN","MR","NE","ML","SD"],"c":["afrique"]},"sinai":{"n":"Sinaï","t":"désert","km2":60000,"bref":["Le Sinaï est une péninsule égyptienne triangulaire, célèbre pour son importance historique, géographique et religieuse."],"src":"https://fr.vikidia.org/wiki/Sina%C3%AF","sw":"v","q":"Q36755","pays":["EG"],"c":["afrique"]},"steppe-de-la-faim":{"n":"Steppe de la Faim","t":"désert","km2":75000,"bref":["La steppe de la Faim, Bet-Pak-Dala ou Betpak-Dala, est un désert du Kazakhstan situé à l'ouest du lac Balkhach, entre le fleuve Tchou et la rivière Saryssou. Sa superficie est d'environ 75 000 km2.","En mai 2015, une mystérieuse épidémie décime les troupeaux de saïgas présents dans le désert, si bien qu'en novembre 2015 il ne reste plus que 12 % de la population initialement présente."],"src":"https://fr.wikipedia.org/wiki/Steppe_de_la_Faim_(Kazakhstan)","sw":"w","q":"Q1359850","pays":["KZ"],"c":["asie","europe"]},"tenere":{"n":"Ténéré","t":"désert","km2":400000,"bref":["Le Ténéré, surnommé aussi le « désert des déserts », est une région hyper-aride de plaines sableuses située dans la partie centre-sud du Sahara qui s'étend au Niger. Délimité par le massif de l'Aïr à l'ouest, le Hoggar au nord, le plateau du Djado au nord-est et le bassin du lac Tchad au sud, le Ténéré couvre 400 000 km2. Ce terme vient de l'expression tamasheq (la langue des Touareg) tin ere, « celle qui rend », en référence aux dunes de sable formés par le vent (l'erg), et signifie simplement « désert »."],"src":"https://fr.wikipedia.org/wiki/T%C3%A9n%C3%A9r%C3%A9","sw":"w","q":"Q272521","pays":["NE"],"c":["afrique"]}},
"continents":{"afrique":{"n":"Afrique","id":"afrique","t":"continent","pop":1500000000,"npays":60,"bref":["L'Afrique est l'un des six continents de la Terre. Il regroupe cinquante-quatre pays. Avec une superficie de 30 415 873 km2, il recouvre près de 20 % de la surface des terres émergées. Le Nil, son plus long fleuve (dont une partie coule en Égypte), est aussi le deuxième fleuve de la planète, derrière l'Amazone. En 2026, sa population dépassait les 1,59 milliard d'habitants ; c'est par la population le deuxième continent du monde après l'Asie. C'est aussi en Afrique que se produit le plus important rift continental du monde. Il s'agit du rift est-africain ou vallée du Grand Rift. Ce dernier nom a été donné par l'explorateur John Walter Gregory.","On distingue l'Afrique du Nord et l'Afrique subsaharienne, c'est-à-dire celle située sous le désert du Sahara, le plus vaste du monde après les étendues glacées de l'Antarctique. L'Afrique subsaharienne peut être divisée en Afrique de l'Ouest, Afrique centrale, Afrique orientale et Afrique australe."],"src":"https://fr.vikidia.org/wiki/Afrique","sw":"v","km2":30415873,"q":"Q15"},"amerique-du-nord":{"n":"Amérique du Nord","id":"amerique-nord","t":"continent","pop":620000000,"npays":40,"bref":["L'Amérique du Nord est la partie du continent américain qui se trouve au nord de l'Amérique centrale. Elle comprend le Groenland (sur les plans géographique et géologique, le plan politique n'intervenant pas dans la définition des continents), le Canada, les États-Unis et le Mexique.","Il est à noter que les géologues, géographes et historiens sont partagés sur leur façon de concevoir l'Amérique, et donc, l'Amérique du Nord : y a-t-il un ou deux continents américains ? L'Amérique centrale pourrait poser question, mais tous les géographes sont d'accord pour l'inclure dans l'Amérique du Nord dont elle constitue une région."],"src":"https://fr.vikidia.org/wiki/Am%C3%A9rique_du_Nord","sw":"v","km2":24700000,"q":"Q49"},"amerique-du-sud":{"n":"Amérique du Sud","id":"amerique-sud","t":"continent","pop":440000000,"npays":15,"bref":["L'Amérique du Sud est la partie sud du continent américain, au sud de l'Amérique centrale, mais elle est souvent considérée comme un continent à part entière."],"src":"https://fr.vikidia.org/wiki/Am%C3%A9rique_du_Sud","sw":"v","km2":17840000,"q":"Q18"},"antarctique":{"n":"Antarctique","id":"antarctique","t":"continent","pop":5000,"npays":1,"bref":["L'Antarctique est le continent le plus austral du monde et abrite le pôle Sud. La mer la plus proche du pôle est la banquise de Ross, une dèpendance de l'océan Pacifique. Avec une superficie de 14,1 millions de kilomètres carrés, il est presque entièrement couvert de glace et comprend les régions les plus froides de la planète. Contrairement à l'Arctique qui est un océan recouvert de glace (la banquise), l'Antarctique est un continent. Entièrement entouré par les océans Atlantique, Indien et Pacifique, il est très isolé par rapport aux autres continents, se situant en effet à 3 850 km de l'Afrique du Sud et 970 km de l'Amérique du Sud."],"src":"https://fr.vikidia.org/wiki/Antarctique","sw":"v","km2":14000000,"q":"Q51"},"asie":{"n":"Asie","id":"asie","t":"continent","pop":5000000000,"npays":52,"bref":["L'Asie est le continent le plus étendu avec une superficie de 43 810 582 km2 (soit 29,4 % des terres émergées). Il dépasse l'étendue du continent américain de 3,84 %. C'est aussi le plus peuplé avec environ 58,46% des humains, appelés Asiatiques.","Sa forme est massive, l'Asie forme un bloc d'un seul tenant. Elle est liée à l'Europe au niveau des monts Oural et limitée par le fleuve Oural au sud de la chaîne. C'est en Asie que se trouve le point terrestre le plus éloigné des étendues maritimes (à 2 750 km). L'Asie est presque entièrement située dans l'hémisphère nord, à l'exception des Petites îles de la Sonde, des Moluques méridionales et d'une partie des Grandes îles de la Sonde situées en Insulinde. L'Asie est enfin le continent des hautes montagnes, et même celui des plus élevées du monde."],"src":"https://fr.vikidia.org/wiki/Asie","sw":"v","km2":43810582,"q":"Q48"},"europe":{"n":"Europe","id":"europe","t":"continent","pop":740000000,"npays":54,"bref":["L'Europe est un continent. L'usage traditionnel définit le continent comme étant l'une des cinq parties du monde. Elle est bordée par l'océan Atlantique à l'ouest, par l'océan Arctique au nord, par la mer Méditerranée et la mer Noire au sud et par le massif ancien de l'Oural (qui la sépare de l'Asie) et la mer Caspienne à l'est. Dans un sens plus géographique et plus rigoureux, le continent est entendu comme une « vaste étendue de terres émergées d'un seul tenant entourée d'océans ». D'où l'on déduit que cet ensemble géographique n'est pas un continent puisqu'il fait partie, tout comme l'Asie, d'un ensemble plus vaste : l'Eurasie, appelée aussi parfois « continent eurasiatique ».","Dans les limites telles que les a déterminées le tsar Pierre Ier, l'Europe n'est pas une péninsule. Elle est soudée à l'Asie non par un seul côté mais sur deux côtés : à l'est, les monts Oural puis le fleuve Oural jusqu'à la mer Caspienne et au sud-est la chaîne du Caucase entre la mer Noire et la mer Caspienne."],"src":"https://fr.vikidia.org/wiki/Europe","sw":"v","km2":10180000,"q":"Q46"},"oceanie":{"n":"Océanie","id":"oceanie","t":"continent","pop":12000000,"npays":26,"bref":["Souvent assimilée à un continent par les géographes, l’Océanie peut être considérée comme le moins étendu des continents émergés de la Terre. Elle englobe toutes les terres situées entre l'Asie de l'Est et l'Asie du Sud-Est à l'ouest et l'Amérique à l'est. Elle comprend aussi une petite partie de l'archipel malais (Îles Raja Ampat et archipel Aru). Elle est divisée en quatre régions : l'Australasie, la Micronésie, la Mélanésie et la Polynésie, bien que cette distinction soit controversée."],"src":"https://fr.wikipedia.org/wiki/Oc%C3%A9anie","sw":"w","km2":8525989,"q":"Q538"}}
});
